window.DK_TERIM_DIZIN=window.DK_TERIM_DIZIN||{};DK_TERIM_DIZIN["mto323"]={"v":"a4867ee1fd","terim":[{"id":"absorbing-aerosol","tr":"Soğurucu aerosol","en":"absorbing aerosol","kisa":"","tur":"kavram","es":["soğuran aerosol","absorbing particles"],"tanim":["Güneş ışınımını belirgin biçimde soğuran ve tek saçılma albedosu (ω) 1'den küçük olan aerosol türüdür.","İs (siyah karbon), kahverengi karbon ve mineral toz bu grupta yer alır.","Bulunduğu atmosfer tabakasını ısıtırken yeryüzüne ulaşan güneş ışığını azaltır ve yarı doğrudan etkiyle bulutları buharlaştırabilir."],"tanim_en":"An aerosol type that significantly absorbs solar radiation and has a single-scattering albedo notably below unity.","bag":{"kavram":["aerosol-dogrudan"],"soru":["S25"],"hesap":[]}},{"id":"ammonia","tr":"Amonyak","en":"Ammonia","kisa":"NH₃","tur":"kavram","es":["amonyak gazı","NH3","azot trihidrür","NH₃","azane"],"tanim":["Atmosferdeki başlıca bazik gaz olan azot ve hidrojenden oluşan bir bileşiktir (NH₃).","Tarım ve hayvancılık etkinliklerinden salınır; gaz fazında bulunur.","Sülfürik asit ve nitrik asidi nötrleyerek amonyum sülfat ve amonyum nitrat gibi ikincil ince parçacıkları oluşturur."],"tanim_en":"The primary alkaline trace gas in the atmosphere that neutralizes acidic compounds to form ammonium salts.","bag":{"kavram":["aerosol-sinif","stokiyometri","asit-yagmuru"],"soru":["S14","S28"],"hesap":[]}},{"id":"ammonium","tr":"Amonyum","en":"Ammonium","kisa":"NH₄⁺","tur":"kavram","es":["amonyum iyonu","NH₄⁺","ammonium ion"],"tanim":["Amonyak gazının bir proton almasıyla oluşan tek yüklü katyondur (NH₄⁺).","Atmosferde serbest gaz olarak bulunmaz; sülfat ve nitrat anyonlarıyla tuz oluşturarak aerosol fazında yer alır.","Asidik kirleticilerin amonyakla nötrlenmesi sonucu oluşur ve ince moddaki aerosol kütlesine önemli katkı yapar."],"tanim_en":"A positively charged polyatomic cation formed by protonation of ammonia, found predominantly in fine aerosol particles.","bag":{"kavram":["aerosol-sinif"],"soru":["S14","S28"],"hesap":[]}},{"id":"ammonium-nitrate","tr":"Amonyum nitrat","en":"Ammonium nitrate","kisa":"NH₄NO₃","tur":"kavram","es":["ikincil nitrat","NH₄NO₃","ammonium nitrate aerosol"],"tanim":["Amonyak gazı ile nitrik asit buharının nötrleşme tepkimesiyle oluşan ikincil inorganik aerosol bileşiğidir (NH₄NO₃).","Gazdan parçacığa dönüşüm yoluyla oluşur ve ince parçacık modunda (PM2.5) yer alır.","Sıcaklık arttığında tekrar gaz öncüllerine ayrışabilen yarı uçucu bir tuzdur."],"tanim_en":"A secondary inorganic aerosol compound formed by the reversible reaction between gas-phase ammonia and nitric acid.","bag":{"kavram":["aerosol-sinif"],"soru":["S14"],"hesap":[]}},{"id":"black-carbon","tr":"İs (siyah karbon)","en":"Black carbon","kisa":"BC","tur":"kavram","es":["siyah karbon","kurum","dizel isi","element karbon (EC)","BC"],"tanim":["Fosil yakıt ve biyokütlenin eksik yanması sonucu doğrudan atmosfere salınan, birincil ve güçlü soğurucu karbonlu aerosoldür.","Görünür ışık dalga boylarının tamamında güçlü soğurma yapar ve tek saçılma albedosu (ω) düşüktür.","Atmosfer tabakasını ısıtırken kar ve buz üzerine çökerek yüzey albedosunu düşürür ve erimeyi hızlandırır."],"tanim_en":"A primary carbonaceous aerosol produced by incomplete combustion that strongly absorbs solar radiation across all visible wavelengths.","bag":{"kavram":["aerosol-sinif","aerosol-dogrudan","pm"],"soru":["S1","S2","S3","S4","S5","S6"],"hesap":["etkin-sicaklik","zorlama","bulut-net","clausius"]}},{"id":"brown-carbon","tr":"Kahverengi karbon","en":"brown carbon","kisa":"","tur":"kavram","es":["BrC","kahverengi karbon aerosolü"],"tanim":["Biyokütle ve biyoyakıt yanmasından kaynaklanan, ışığı dalga boyuna bağlı olarak soğuran organik aerosol bileşenidir.","Özellikle morötesi ve mavi dalga boylarında soğurma yapar, uzun dalga boylarına doğru soğurması hızla azalır.","Işınımı soğurarak tek saçılma albedosunu düşürür ve bölgesel atmosferik ısınmaya katkı verir."],"tanim_en":"A light-absorbing organic aerosol component that absorbs solar radiation primarily at ultraviolet and shorter visible wavelengths.","bag":{"kavram":["aerosol-sinif","aerosol-dogrudan"],"soru":[],"hesap":[]}},{"id":"coarse-particles","tr":"İri parçacıklar","en":"Coarse particles","kisa":"PM10","tur":"kavram","es":["iri parçacık","kaba parçacıklar","kaba fraksiyon","PM10-2.5"],"tanim":["Aerodinamik çapı 2,5 µm'den büyük olan atmosferik aerosol parçacıklarıdır.","Rüzgâr, deniz dalgaları ve mekanik sürtünme gibi fiziksel süreçlerle doğrudan üretilir; kütlece baskındır.","Yerçekimsel çökelme hızı yüksek olduğundan atmosferik ömrü kısadır ve üst solunum yollarında tutulur."],"tanim_en":"Atmospheric particles with aerodynamic diameters larger than 2.5 micrometers, predominantly produced by mechanical generation.","bag":{"kavram":["aerosol-sinif","pm","boyut-modlari"],"soru":["S14","S15","S16","S17","S19","S20"],"hesap":[]}},{"id":"desert-dust","tr":"Çöl tozu","en":"Desert dust","kisa":"","tur":"kavram","es":["mineral tozu","mineral dust","rüzgârla kalkan toz","toprak tozu","Mineral toz","mineral toz"],"tanim":["Kurak ve yarı kurak bölgelerden rüzgâr erozyonuyla atmosfere karışan birincil mineral aerosol türüdür.","Ağırlıklı olarak iri modda yer alır; silikatlar, kil mineralleri ve demir oksit içerir.","Güneş ışığını saçar, demir oksit içeriği nedeniyle kısa dalga boylarında bir miktar soğurma yapar ve uzun mesafelere taşınır."],"tanim_en":"A primary mineral aerosol entrained into the atmosphere by wind erosion over arid and semi-arid regions.","bag":{"kavram":["aerosol-sinif","pm"],"soru":["S14"],"hesap":[]}},{"id":"fine-particles","tr":"İnce parçacıklar","en":"Fine particles","kisa":"PM2.5","tur":"kavram","es":["ince parçacık","fine mode","ince mod","ince fraksiyon","fine particulate matter","ince aerosol"],"tanim":["Aerodinamik çapı 2,5 µm ve daha küçük olan aerosol parçacıklarıdır (PM2.5).","Yanma süreçleri ve gazdan parçacığa yoğuşma tepkimeleriyle oluşur.","Atmosferde günlerce kalarak uzun mesafelere taşınabilir ve solunum yoluyla akciğer alveollerine kadar ulaşır."],"tanim_en":"Atmospheric particles with aerodynamic diameters not exceeding 2.5 micrometers, primarily formed by combustion and condensation.","bag":{"kavram":["aerosol-sinif","pm","boyut-modlari"],"soru":["S14","S16","S17","S19","S21"],"hesap":[]}},{"id":"isoprene","tr":"İzopren","en":"Isoprene","kisa":"C₅H₈","tur":"kavram","es":["2-metilbütadien","biyojenik VOC","2-metil-1,3-bütadien","isoprene","C₅H₈","2-methyl-1,3-butadiene"],"tanim":["Bitki örtüsü tarafından atmosfere bol miktarda salınan, beş karbonlu uçucu organik bileşiktir (C₅H₈).","Gündüz saatlerinde güneş ışığı ve sıcaklıkla yapraklardan salınımı artar; atmosferik ömrü kısadır.","OH radikali ve ozonla hızla tepkimeye girerek düşük uçuculukta bileşikler üretir ve ikincil organik aerosol (SOA) oluşturur."],"tanim_en":"A biogenic volatile organic compound emitted by vegetation that oxidizes rapidly to produce secondary organic aerosol.","bag":{"kavram":["aerosol-sinif"],"soru":["S14","S18"],"hesap":[]}},{"id":"nitrate-aerosol","tr":"Nitrat aerosolü","en":"Nitrate aerosol","kisa":"NO₃⁻","tur":"kavram","es":["partikül nitrat","nitrat parçacığı","NO3-","nitrate","nitrat","Nitrat iyonu"],"tanim":["Azot oksitlerin yükseltgenmesiyle oluşan nitrik asidin amonyakla nötrleşmesi ya da yoğuşmasıyla oluşan ikincil inorganik aerosol türü.","Atmosferde çoğunlukla ince modda (PM2.5) amonyum nitrat tuzu hâlinde bulunur.","Güneş ışığını saçar, asit çökelmesine katkıda bulunur ve hava kalitesini düşürür."],"tanim_en":"Nitrate aerosol is a secondary inorganic particle formed by the atmospheric oxidation and neutralization of nitrogen compounds.","bag":{"kavram":["aerosol-sinif","pm","koschmieder"],"soru":["S14","S21","S27"],"hesap":[]}},{"id":"nitric-acid","tr":"Nitrik asit","en":"Nitric acid","kisa":"HNO₃","tur":"kavram","es":["hidrojen nitrat","kezzap","HNO3","HNO₃"],"tanim":["Azot dioksit gazının hidroksil radikaliyle üç cisimli tepkimesi sonucu oluşan tek protonlu kuvvetli bir inorganik asit (HNO₃).","Suda tamamen H⁺ ve NO₃⁻ iyonlarına ayrışarak yağış suyunun asitliğini artırır.","Kutup stratosfer bulutlarının yapısına katılarak klor aktivasyonu ve denitrifikasyon olaylarına zemin hazırlar."],"tanim_en":"Nitric acid is a strong atmospheric acid formed by the oxidation of nitrogen dioxide that contributes to acid deposition and polar stratospheric cloud formation.","bag":{"kavram":["aerosol-sinif","asit-yagmuru","psc"],"soru":["S14","S21","S27","S32"],"hesap":["ph-asit"]}},{"id":"organic-carbon","tr":"Organik karbon","en":"Organic carbon","kisa":"OC","tur":"kavram","es":["organik aerosol","organik karbon parçacığı","OC","partikül organik karbon"],"tanim":["Atmosferik parçacıklar içinde C–H ve C–O kimyasal bağları içeren organik bileşiklerin karbon kütlesi payı.","Hem doğrudan biyolojik salımlar ve yanmadan hem de uçucu organik bileşiklerin yükseltgenmesiyle oluşan ikincil organik aerosolden kaynaklanır.","Işığı çoğunlukla saçar ve higroskopik özelliklerine bağlı olarak bulut yoğuşma çekirdeği görevi yapar."],"tanim_en":"Organic carbon represents the fraction of particulate matter containing carbon-hydrogen and carbon-oxygen chemical bonds.","bag":{"kavram":["aerosol-sinif"],"soru":["S14","S18"],"hesap":[]}},{"id":"oxidant","tr":"Oksidan","en":"Oxidant","kisa":"","tur":"kavram","es":["yükseltgen","atmosferik oksidan"],"tanim":["Atmosferde diğer kimyasal türlerden elektron alan veya onlara oksijen aktararak yükseltgenmelerini sağlayan kimyasal olarak etkin tür.","Troposferdeki başlıca örnekleri hidroksil radikali (OH), ozon (O₃) ve nitrat radikalidir (NO₃).","Kükürt dioksit ve organik gazları yükseltgeyerek sülfat ve ikincil organik aerosol gibi parçacıkların oluşumunu başlatır."],"tanim_en":"An oxidant is a reactive chemical agent capable of oxidizing trace gas molecules and pollutants in the atmosphere.","bag":{"kavram":["aerosol-sinif"],"soru":["S14","S18","S29","S31","S44"],"hesap":[]}},{"id":"pollen","tr":"Polen","en":"Pollen","kisa":"","tur":"kavram","es":["çiçek tozu","biyolojik parçacık","biyolojik aerosol","aerosol polen"],"tanim":["Bitkiler tarafından çoğalma amacıyla havaya salınan biyolojik kökenli birincil aerosol parçacığı.","Çapı çoğunlukla 2,5 µm'den büyük olduğu için aerosol boyut dağılımında mekanik kaynaklı iri modda yer alır.","Yerçekimsel çökelmeyle atmosferden kısa sürede uzaklaşır, ancak bulutlarda buz çekirdeklenmesini tetikleyebilir."],"tanim_en":"Pollen is a coarse primary biological particle emitted by vegetation that rapidly settles under gravity.","bag":{"kavram":["aerosol-sinif"],"soru":["S14"],"hesap":[]}},{"id":"primary-aerosol","tr":"Birincil aerosol","en":"Primary aerosol","kisa":"","tur":"kavram","es":["primer aerosol","doğrudan salınan parçacık"],"tanim":["Kaynaktan atmosfere doğrudan katı veya sıvı parçacık biçiminde salınan aerosol türü.","Deniz tuzu, çöl tozu ve polen gibi mekanik iri parçacıkların yanında yanmadan çıkan ince isi de kapsar.","Atmosferde kimyasal gaz dönüşümü gerektirmeden partikül yükünü ve doğrudan ışınım etkisini belirler."],"tanim_en":"A primary aerosol is a particulate matter component emitted directly into the atmosphere in solid or liquid form.","bag":{"kavram":["aerosol-sinif"],"soru":["S17"],"hesap":[]}},{"id":"sea-salt","tr":"Deniz tuzu","en":"Sea salt","kisa":"NaCl","tur":"kavram","es":["deniz spreyi","sea salt aerosol","deniz tuzu aerosolü","NaCl"],"tanim":["Okyanus yüzeyinde dalga kırılması ve köpük kabarcıklarının patlamasıyla havaya fırlatılan birincil doğal aerosol.","Bileşimi büyük oranda NaCl tuzundan oluşur ve mekanik üretim nedeniyle çoğunlukla iri modda bulunur.","Çok higroskopik olduğu için denizel sınır tabakada etkin bir bulut yoğuşma çekirdeği (CCN) olarak davranır ve güneş ışığını saçar."],"tanim_en":"Sea salt is a primary natural aerosol produced by breaking waves that acts as an efficient cloud condensation nucleus.","bag":{"kavram":["aerosol-sinif"],"soru":["S14","S16"],"hesap":[]}},{"id":"secondary-aerosol","tr":"İkincil aerosol","en":"Secondary aerosol","kisa":"","tur":"kavram","es":["sekonder aerosol","gazdan dönüşen parçacık","gazdan oluşan aerosol"],"tanim":["Atmosferde gaz fazındaki öncül maddelerin kimyasal tepkimelerle düşük uçuculukta ürünlere dönüşmesi ve yoğuşmasıyla oluşan parçacık.","Sülfat, nitrat, amonyum ve ikincil organik aerosol (SOA) türlerini kapsar.","Çoğunlukla 1 µm'den küçük ince modda yer alarak güneş ışığını saçar ve görüş mesafesini azaltır."],"tanim_en":"A secondary aerosol is particulate matter produced in the atmosphere by the chemical transformation and condensation of precursor gas molecules.","bag":{"kavram":["aerosol-sinif","asit-yagmuru"],"soru":["S14","S17","S28","S31"],"hesap":[]}},{"id":"secondary-organic-aerosol","tr":"İkincil organik aerosol","en":"Secondary organic aerosol","kisa":"SOA","tur":"kavram","es":["sekonder organik aerosol","SOA"],"tanim":["Uçucu organik bileşiklerin atmosferik oksidanlarla tepkimeye girerek düşük uçuculukta bileşikler oluşturması ve bunların yoğuşmasıyla meydana gelen organik parçacık.","İzopren ve terpen gibi biyojenik salımlar ile insan kaynaklı hidrokarbonların yükseltgenmesinden kaynaklanır.","Aerosol boyut dağılımında ince modda yer alır, güneş ışığını saçar ve iklim üzerinde doğrudan ile dolaylı ışınımsal etki yapar."],"tanim_en":"Secondary organic aerosol is particulate matter formed through the atmospheric oxidation and condensation of volatile organic compounds.","bag":{"kavram":["aerosol-sinif","leighton"],"soru":["S14","S18"],"hesap":[]}},{"id":"sulfate-aerosol","tr":"Sülfat aerosolü","en":"Sulfate aerosol","kisa":"SO₄²⁻","tur":"kavram","es":["sülfat","ikincil sülfat","sülfat parçacığı","sülfat partikülleri","sulfate particles","sülfat aerosol damlacığı"],"tanim":["Kükürt dioksitin (SO₂) atmosferde yükseltgenerek sülfürik asit ve sülfat tuzlarına dönüşmesiyle oluşan ikincil inorganik aerosol.","Tek saçılma albedosu bire yakın (ω ≈ 1) olduğu için güneş ışığını güçlü şekilde saçar ve yüzey sıcaklığını düşürür.","Troposferde yaklaşık bir haftalık ömre sahipken stratosfere ulaşan volkanik sülfat aerosolü yaklaşık bir yıllık e-katlanma süresiyle kalır."],"tanim_en":"Sulfate aerosol is a secondary inorganic particle formed by sulfur dioxide oxidation that efficiently scatters solar radiation and cools the climate.","bag":{"kavram":["aerosol-sinif","aerosol-dogrudan","volkan-aerosol"],"soru":["S14","S18","S25","S27","S28","S29"],"hesap":[]}},{"id":"sulfuric-acid","tr":"Sülfürik asit","en":"Sulfuric acid","kisa":"H₂SO₄","tur":"kavram","es":["zaç yağı","H₂SO₄","sulphuric acid","sülfat aerosolünün asidi"],"tanim":["Kükürt dioksidin atmosferde yükseltgenmesiyle (SO₂ → SO₃ → H₂SO₄) oluşan, seyreltik çözeltide iki proton veren kuvvetli bir asit.","Seyreltik yağmur suyunda her molü 2 mol H⁺ verir; kitabın pH hesabında [H⁺] = [HNO₃] + 2[H₂SO₄].","Düşük buhar basıncı nedeniyle gazdan parçacığa dönüşerek ikincil sülfat aerosollerini ve asit yağmurunu oluşturan temel bileşiktir."],"tanim_en":"A strong diprotic mineral acid formed by the atmospheric oxidation of sulfur dioxide that drives secondary sulfate particle formation and acid precipitation.","bag":{"kavram":["aerosol-sinif","asit-yagmuru","volkan-aerosol"],"soru":["S14","S27","S28","S29","S31","S33"],"hesap":["ph-asit"]}},{"id":"volcanic-ash","tr":"Volkan külü","en":"volcanic ash","kisa":"","tur":"kavram","es":["volkanik kül","yanardağ külü","tefra","tephra"],"tanim":["Patlamalı volkanik püskürmeler sırasında parçalanan kayaç, mineral ve volkanik cam taneciklerinden oluşan birincil katı parçacıklar.","İri ve ağır mineral modunda yer aldığından yerçekimsel çökelme ile yanardağ çevresinde günler ya da haftalar içinde atmosferden temizlenir.","Havacılık güvenliğini doğrudan tehdit eder; fakat uzun vadeli küresel iklim soğumasına kül değil, kükürt dioksitten oluşan ince sülfat aerosolü yol açar."],"tanim_en":"Volcanic ash consists of fine particles of pulverized rock, mineral crystals, and volcanic glass ejected into the atmosphere during an explosive volcanic eruption.","bag":{"kavram":["aerosol-sinif","volkan-aerosol"],"soru":[],"hesap":[]}},{"id":"volatile-organic-compound","tr":"Uçucu organik bileşikler","en":"volatile organic compounds","kisa":"VOC","tur":"kod","es":["UOB","VOC","VOC'ler"],"tanim":["Oda sıcaklığında yüksek buhar basıncına sahip olan ve atmosfere kolayca buharlaşan karbon temelli organik bileşikler.","Troposferde OH radikaliyle tepkimeye girerek peroksi radikalleri (RO₂) oluşturur; bu radikaller NO'yu O₃ harcamadan NO₂'ye yükseltger.","Hem fotokimyasal dumanın ve troposferik ozonun hem de ikincil organik aerosollerin (SOA) temel öncülüdür."],"tanim_en":"An organic chemical compound having high vapour pressure at ambient temperature that acts as a key precursor to tropospheric ozone and secondary organic aerosol.","bag":{"kavram":["aerosol-sinif","leighton","titrasyon"],"soru":["S43","S44"],"hesap":[]}},{"id":"biomass-burning","tr":"Biyokütle yanması","en":"biomass burning","kisa":"","tur":"surec","es":["biyokütle yakma","biyokütle yanışı","bitki örtüsü yangınları","vegetation fire"],"tanim":["Orman, savan ve tarımsal anız gibi canlı veya ölü bitki örtüsünün yanması sürecidir.","Atmosfere is (siyah karbon), organik karbon ve kahverengi karbon parçacıkları ile çeşitli iz gaz bileşikleri salar.","Güneş ışınımını doğrudan saçıp soğurarak iklimi ve bölgesel hava kalitesini etkileyen önemli bir birincil aerosol kaynağıdır."],"tanim_en":"Biomass burning is the combustion of living or dead vegetation that emits carbonaceous aerosol particles and trace gas compounds into the atmosphere.","bag":{"kavram":["aerosol-sinif"],"soru":[],"hesap":[]}},{"id":"combustion","tr":"Yanma","en":"Combustion","kisa":"","tur":"surec","es":["yakma","fosil yakıt yanması"],"tanim":["Bir yakıtın oksijenle hızlı tepkimeye girerek ısı, ışık ve yanma ürünleri açığa çıkardığı yüksek sıcaklıklı kimyasal süreç.","Fosil yakıt ve biyokütle yakılması atmosfere CO₂, CO, NOₓ, SO₂ ve birincil parçacıklar salar.","İnce aerosol modunda yer alan dizel isi gibi birincil parçacıkların ve asit yağmuru ile duman öncülü gazların ana antropojenik kaynağıdır."],"tanim_en":"A high-temperature exothermic chemical reaction between a fuel and an oxidant that produces thermal energy and emits air pollutants.","bag":{"kavram":["aerosol-sinif"],"soru":["S14","S28"],"hesap":[]}},{"id":"condensation","tr":"Yoğuşma","en":"Condensation","kisa":"","tur":"surec","es":["yoğunlaşma","buhar yoğuşması"],"tanim":["Gaz ya da buhar fazındaki bir maddenin sıvı faza geçmesi; buhar hâlinden sıvı hâle geçiş.","Süreç sırasında çevreye gizli ısı salınır; atmosferde su buharı bağıl nem %100'e ulaştığında veya aşırı doygunlukta yoğuşur.","Atmosferde bulut damlacıklarının oluşumunu, bulut tabanını (LCL) ve gazdan parçacığa dönüşümle ince aerosol modlarının büyümesini belirler."],"tanim_en":"The phase transition of a substance from the vapour state to the liquid state, accompanied by the liberation of latent heat.","bag":{"kavram":["aerosol-sinif","boyut-modlari","lcl"],"soru":["S8","S11","S12","S14","S15","S17"],"hesap":["lcl"]}},{"id":"gas-to-particle-conversion","tr":"Gazdan parçacığa dönüşüm","en":"Gas-to-particle conversion","kisa":"GPC","tur":"surec","es":["gazdan parçacık oluşumu","ikincil aerosol oluşumu","GPC"],"tanim":["Atmosferdeki gaz fazı öncüllerin kimyasal tepkimelerle düşük uçuculukta ürünlere dönüşerek yeni parçacık oluşturması veya mevcut parçacıklar üzerinde yoğuşması süreci.","Kükürt dioksit, azot oksitler ve uçucu organik bileşiklerin hidroksil radikali gibi oksidanlarla yükseltgenmesi ve amonyağın bu asitlerle nötrleşmesi yoluyla gerçekleşir.","Atmosferdeki 2,5 µm altındaki ikincil ince parçacıkların (sülfat, nitrat, amonyum ve SOA) tamamını meydana getirir."],"tanim_en":"The transformation of trace gas precursor molecules into low-volatility compounds that form secondary aerosol particles by nucleation or condensation.","bag":{"kavram":["aerosol-sinif"],"soru":["S14","S17","S33"],"hesap":[]}},{"id":"mechanical-generation","tr":"Mekanik üretim","en":"Mechanical generation","kisa":"","tur":"surec","es":["mekanik parçalanma","mekanik aşınma"],"tanim":["Rüzgâr, dalga kırılması veya sürtünme gibi mekanik kuvvetlerin yeryüzünden doğrudan katı veya sıvı parçacık koparması süreci.","Parçacık küçüldükçe yüzey/hacim oranı ve gereken yüzey enerjisi aşırı arttığı için mekanik üretim 1 µm altındaki parçacıkları üretemez.","Deniz tuzu, çöl tozu ve polen gibi 2,5 µm'den büyük iri modlu birincil aerosollerin temel oluşum yoludur."],"tanim_en":"The production of coarse primary aerosol particles directly from the surface through physical forces such as wind shear and wave breaking.","bag":{"kavram":["aerosol-sinif","stokes"],"soru":["S14","S17"],"hesap":[]}},{"id":"unit-cubic-centimeter-per-molecule-second","tr":"Santimetreküp bölü molekül saniye","en":"cubic centimeters per molecule per second","kisa":"cm³ molekül⁻¹ s⁻¹","tur":"birim","es":["cm³ molecule⁻¹ s⁻¹","cm^3 molecule^-1 s^-1","ikinci mertebe hız sabiti birimi","cm³ s⁻¹"],"tanim":["Gaz fazındaki iki cisimli kimyasal tepkimelerin hız sabiti k için kullanılan standart hız katsayısı birimi.","İki tepkenin sayı yoğunluklarının çarpımıyla çarpılınca birim zamanda birim hacimdeki tepkime sayısını, tek bir tepkenin sayı yoğunluğuyla çarpılınca s⁻¹ biriminde kayıp frekansını verir.","Atmosfer kimyasında gazların hidroksil radikali veya ozon ile bimoleküler kayıp hızlarını hesaplamada kullanılır."],"tanim_en":"The cm³ molecule⁻¹ s⁻¹ is the standard unit of bimolecular (second-order) rate constants in gas-phase atmospheric chemistry.","bag":{"kavram":["arrhenius","omur","chapman"],"soru":["S37","S38","S44"],"hesap":[]}},{"id":"unit-kilojoule-per-mole","tr":"Kilojoule bölü mol","en":"kilojoules per mole","kisa":"kJ/mol","tur":"birim","es":["kJ mol⁻¹","kJ mol^-1","molar enerji birimi"],"tanim":["Bir mol kimyasal maddenin içerdiği veya bir kimyasal dönüşüm sırasında soğurulan ya da salınan enerjiyi ifade eden molar enerji birimi.","1 kJ/mol = 10³ J/mol; molekül başına enerjiye geçmek için Avogadro sayısına bölünür.","Atmosfer kimyasında kimyasal bağ ayrışma enerjileri ile Arrhenius aktivasyon enerjisi parametresini belirtmede kullanılır."],"tanim_en":"The kilojoule per mole (kJ/mol) is the molar energy unit used for activation energies and bond dissociation energies.","bag":{"kavram":["arrhenius","fotoliz"],"soru":["S40"],"hesap":[]}},{"id":"unit-per-second","tr":"Saniye üzeri eksi bir","en":"reciprocal second","kisa":"s⁻¹","tur":"birim","es":["1/s","s^-1","ters saniye","per second"],"tanim":["Birinci mertebe veya sözde birinci mertebe tepkime hız katsayıları ile fotoliz frekansını ifade eden zamanın tersi birimi.","Birim zamanda dönüşüme uğrayan madde kesrini gösterir; ömrün tersi şeklinde tanımlanır.","Atmosferde fotolitik ayrışma hızı J ve kirleticilerin birinci mertebe kimyasal kayıp hız katsayısı k' bu birimle gösterilir."],"tanim_en":"The reciprocal second (s⁻¹) is the unit of first-order rate coefficients and photolysis frequencies, giving the fraction of a species lost per unit time.","bag":{"kavram":["arrhenius","fotoliz","omur"],"soru":["S37","S38","S39","S40","S41","S44"],"hesap":[]}},{"id":"first-order-reaction","tr":"Birinci mertebe tepkime","en":"first-order reaction","kisa":"","tur":"kavram","es":["birinci derece kayıp","first-order decay","birinci mertebe kinetik","birinci mertebe kayıp","first-order loss","üstel azalma"],"tanim":["Tepkime hızının yalnızca tek bir türün derişimiyle doğru orantılı olduğu kimyasal dönüşüm süreci.","Hız denklemi hız = k[A] biçiminde olup birinci mertebe hız sabitinin birimi s⁻¹ veya 1/yıl; türün atmosferik ömrü ise τ = 1/k formülüyle hesaplanır.","Atmosferdeki fotoliz tepkimeleri ile bir bileşenin derişimi neredeyse sabit kalan bir reaktifle tepkimeye girdiği sözde birinci mertebe kayıpların matematiksel temelidir."],"tanim_en":"A chemical reaction whose rate is directly proportional to the concentration of a single reacting chemical species.","bag":{"kavram":["arrhenius","ustel","omur"],"soru":["S31","S37","S40"],"hesap":[]}},{"id":"three-body-reaction","tr":"Üç cisimli tepkime","en":"three-body reaction","kisa":"","tur":"kavram","es":["üçüncü cisim tepkimesi","üç moleküllü tepkime","termoleküler tepkime","termolecular reaction","üç cisimli hız sabiti"],"tanim":["İki kimyasal türün birleşerek tek bir ürün oluştururken açığa çıkan aşırı enerjiyi ortamdaki üçüncü bir cismin uzaklaştırdığı kimyasal tepkime.","Hız sabiti birimi cm⁶ molekül⁻² s⁻¹ olup tepkime hızı ortamın sayı yoğunluğu ve basınç ile doğru orantılı olarak artar.","Stratosferde ozon oluşumunun temel adımıdır ve sıcaklık azaldıkça tepkime hızı genellikle yükselir."],"tanim_en":"A termolecular chemical reaction in which two colliding species combine into a single product while a third body removes the surplus energy.","bag":{"kavram":["arrhenius","asit-yagmuru","chapman"],"soru":["S41","S43"],"hesap":["chapman-o"]}},{"id":"activation-energy","tr":"Aktivasyon enerjisi","en":"activation energy","kisa":"Eₐ","tur":"olcu","es":["aktifleşme enerjisi","Ea sembolü","etkinleşme enerjisi","enerji engeli","Ea","Eₐ"],"tanim":["Bir kimyasal tepkimenin başlayabilmesi ve tepkenlerin geçiş durumuna ulaşabilmesi için aşılması gereken minimum enerji engeli.","Arrhenius denkleminde Eₐ simgesiyle yer alır; birimi J/mol veya kJ/mol olup atmosfer kimyasında çoğunlukla Eₐ/R oranı olarak Kelvin cinsinden ifade edilir.","Tepkime hız sabitinin sıcaklığa olan duyarlılığını belirler; yüksek aktivasyon enerjisine sahip tepkimeler sıcaklık artışıyla çok daha hızlı ivmelenir."],"tanim_en":"The minimum amount of energy required by reactant molecules to overcome the potential barrier and initiate a chemical reaction.","bag":{"kavram":["arrhenius"],"soru":["S37","S40"],"hesap":["ea-iki-nokta"]}},{"id":"pre-exponential-factor","tr":"Ön çarpan","en":"pre-exponential factor","kisa":"A","tur":"olcu","es":["ön üstel çarpan","frekans faktörü","A sembolü","Arrhenius A","Arrhenius A faktörü","üstel öncesi çarpan"],"tanim":["Arrhenius denkleminde üstel fonksiyonun önünde yer alan ve sıcaklık sonsuza yaklaştığındaki kuramsal hız sabitini gösteren parametre.","A simgesiyle gösterilir; birimi tepkimenin mertebesine göre hız sabitiyle aynıdır (ikinci mertebe için cm³ molekül⁻¹ s⁻¹).","Reaktif moleküller arasındaki çarpışma sıklığı ile tepkimeye yol açan uygun geometrik yönelim olasılığının çarpımını ifade eder."],"tanim_en":"The pre-exponential constant A in the Arrhenius equation that represents the frequency of molecular collisions with the correct steric orientation.","bag":{"kavram":["arrhenius"],"soru":["S37","S40"],"hesap":["arrhenius"]}},{"id":"boltzmann-distribution","tr":"Boltzmann dağılımı","en":"Boltzmann distribution","kisa":"","tur":"yontem","es":["Maxwell–Boltzmann dağılımı","Boltzmann istatistiği","Boltzmann faktörü"],"tanim":["Termal dengedeki bir parçacık topluluğunda belirli bir enerji durumunda bulunma olasılığını sıcaklığın fonksiyonu olarak veren istatistiksel mekanik dağılımı.","Moleküllerin kinetik enerjilerinin dağılımını belirler ve aktivasyon enerjisi Eₐ üzerindeki enerjiye sahip çarpışmaların kesrini exp(−Eₐ/RT) üstel terimiyle tanımlar.","Atmosfer kimyasında gaz tepkimelerinin Arrhenius hız bağıntısındaki üstel sıcaklık bağımlılığının teorik temelini oluşturur."],"tanim_en":"The Boltzmann distribution gives the fraction of molecules in each energy state at thermal equilibrium; the fraction with energy above Eₐ scales as exp(−Eₐ/RT).","bag":{"kavram":["arrhenius"],"soru":[],"hesap":["arrhenius"]}},{"id":"two-temperature-activation-energy-method","tr":"İki sıcaklıktan aktivasyon enerjisi","en":"two-temperature Arrhenius method","kisa":"","tur":"yontem","es":["iki nokta Arrhenius yöntemi","iki sıcaklık yöntemi","Arrhenius iki sıcaklık denklemi"],"tanim":["Bir kimyasal tepkimenin iki farklı sıcaklıkta ölçülen hız sabitleri oranından aktivasyon enerjisini hesaplayan analitik yöntem.","Arrhenius bağıntısının logaritmik biçimi kullanılarak ln(k₂/k₁) = (Eₐ/R)(1/T₁ − 1/T₂) eşitliği üzerinden doğrudan Eₐ çözülür.","Ön çarpan A bilinmediğinde atmosfer sıcaklık değişimlerinin tepkime kinetiğine etkisini belirlemede pratik kolaylık sağlar."],"tanim_en":"The two-temperature Arrhenius method obtains the activation energy from rate constants measured at two temperatures: Eₐ = R ln(k₂/k₁)/(1/T₁ − 1/T₂).","bag":{"kavram":["arrhenius"],"soru":["S40"],"hesap":["arrhenius"]}},{"id":"unit-mole-per-liter","tr":"Mol bölü litre (molarite)","en":"mole per liter","kisa":"mol/L","tur":"birim","es":["M","molarite","mol L⁻¹","moles per litre"],"tanim":["Bir litre çözelti içinde çözünmüş maddenin mol miktarını belirten derişim (molarite) birimidir.","Simgesi mol/L veya M olup kimyasal dengelerde ve sulu çözelti tepkimelerinde kullanılır.","Atmosfer kimyasında bulut ve yağmur damlalarındaki hidrojen, sülfat ve nitrat iyonu derişimlerini belirtir."],"tanim_en":"Mole per liter is a unit of molar concentration defining the amount of a dissolved solute in one liter of aqueous solution.","bag":{"kavram":["asit-yagmuru","temiz-yagmur"],"soru":["S26","S27"],"hesap":[]}},{"id":"acid-deposition","tr":"Asit çökelmesi","en":"acid deposition","kisa":"","tur":"kavram","es":["asit birikimi","asitli çökelme","acidic deposition"],"tanim":["Kükürt ve azot içeren kirleticilerin atmosferik taşınımı sonucu asidik maddelerin yeryüzüne ıslak veya kuru yollarla aktarılması.","Islak çökelme ile gaz ve aerosol parçacıklarının doğrudan tutunması olan kuru çökelme mekanizmalarının toplamını kapsar.","Toprak, göl ve nehir sularında pH değerini düşürerek ekosistemlerde, ormanlarda ve yapı malzemelerinde bozulmaya yol açar."],"tanim_en":"The transfer of acidic substances from the atmosphere to the Earth's surface through both wet and dry deposition pathways.","bag":{"kavram":["asit-yagmuru"],"soru":["S21"],"hesap":[]}},{"id":"bisulfite-radical","tr":"Bisülfit radikali","en":"bisulfite radical","kisa":"HSO₃","tur":"kavram","es":["hidrojen sülfit radikali","HSO3","hydrogen sulfite radical","HSO₃ radikali","HSO₃"],"tanim":["Kükürt dioksitin hidroksil radikaliyle tepkimesi sonucu oluşan kararsız bir kükürt ara radikalidir.","Formülü HSO₃ olup eşleşmemiş bir elektrona sahiptir ve moleküler oksijen ile hızla tepkimeye girer.","Atmosferde SO₂ gazının sülfürik aside ve sülfat aerosolüne dönüşüm zincirindeki ilk temel ara üründür."],"tanim_en":"Bisulfite radical is a short-lived transient intermediate formed by the gas-phase addition of a hydroxyl radical to sulfur dioxide.","bag":{"kavram":["asit-yagmuru","volkan-aerosol"],"soru":[],"hesap":[]}},{"id":"calcium-sulfate","tr":"Kalsiyum sülfat (alçı)","en":"calcium sulfate","kisa":"CaSO₄","tur":"kavram","es":["alçı","CaSO4","gypsum","alçıtaşı","calcium sulphate","CaSO₄"],"tanim":["Kalsiyum ve sülfat iyonlarının oluşturduğu, formülü CaSO₄ olan inorganik bir tuzdur.","Susuz hâli doğada anhidrit, iki su içeren hâli (CaSO₄·2H₂O) alçıtaşı (jips) mineralidir; suda kalsiyum karbonattan çok daha çözünürdür.","Asit yağmurundaki sülfürik asidin mermer yapılardaki CaCO₃ ile tepkimesi sonucu yüzeyde kabuklaşan ve yıkanıp aşınmaya yol açan bileşiktir."],"tanim_en":"Calcium sulfate is an inorganic salt formed when atmospheric sulfuric acid reacts with calcium carbonate on marble or limestone.","bag":{"kavram":["asit-yagmuru"],"soru":["S29"],"hesap":[]}},{"id":"hydrogen-ion","tr":"Hidrojen iyonu","en":"hydrogen ion","kisa":"H⁺","tur":"kavram","es":["proton","hidronyum","H+","hidronyum iyonu","[H+]","proton derişimi"],"tanim":["Bir hidrojen atomunun elektronunu kaybetmesiyle oluşan tek pozitif yüklü katyondur; sulu çözeltilerde su molekülüyle birleşerek hidronyum (H₃O⁺) formunda bulunur.","Çözeltideki derişimi [H⁺] mol/L birimiyle belirtilir; eksi logaritması pH = −log₁₀[H⁺] eşitliğiyle ortamın asitliğini tanımlar.","Atmosferde temiz yağmurun pH değerini 5,6 seviyesine çeker; sülfürik ve nitrik asit girdisiyle asit yağmurlarında derişimi belirgin biçimde yükselir."],"tanim_en":"The hydrogen ion (H⁺, a proton) is released by acids in aqueous solution; its molar concentration sets the pH and the acidity of precipitation.","bag":{"kavram":["asit-yagmuru","temiz-yagmur"],"soru":["S26","S27","S28","S29"],"hesap":["ph-temiz","ph-asit"]}},{"id":"hydroperoxyl-radical","tr":"Hidroperoksil radikali","en":"hydroperoxyl radical","kisa":"HO₂","tur":"kavram","es":["HO2","peroksil radikali","hidroperoksil","perhidroksil","hidroperoksi radikali","HO₂"],"tanim":["Formülü HO₂ olan, eşleşmemiş elektron taşıyan oldukça etkin bir serbest radikaldir.","Troposferde uçucu organik bileşiklerin ve karbonmonoksitin hidroksil radikaliyle yükseltgenmesi sürecinde oluşur.","Ozon tüketmeden NO molekülünü NO₂ molekülüne dönüştürerek fotokimyasal duman ve ozon üretimini hızlandırır."],"tanim_en":"Hydroperoxyl radical is a reactive free radical that converts nitric oxide to nitrogen dioxide without consuming ozone.","bag":{"kavram":["asit-yagmuru","volkan-aerosol","katalitik"],"soru":["S44"],"hesap":[]}},{"id":"limestone","tr":"Kireçtaşı","en":"limestone","kisa":"CaCO₃","tur":"kavram","es":["kalker","kalsiyum karbonat","CaCO₃","calcium carbonate"],"tanim":["Ağırlıklı olarak kalsiyum karbonat (CaCO₃) mineralinden oluşan, atmosferik asitleri nötrleme kapasitesine sahip tortul bir kayaç türü.","Asit yağmurundaki hidrojen iyonlarıyla tepkimeye girerek serbest asitliği tüketir ve ortamı tamponlar.","Kireçtaşı içeren havzalardaki göller asit yağışlarına karşı direnç göstererek pH dengesini granit havzalara göre çok daha iyi korur."],"tanim_en":"A sedimentary rock composed mainly of calcium carbonate that acts as a natural buffer against acidic deposition.","bag":{"kavram":["asit-yagmuru","stokiyometri"],"soru":["S29"],"hesap":[]}},{"id":"marble","tr":"Mermer","en":"marble","kisa":"","tur":"kavram","es":["mermer aşınması","metamorfik kireçtaşı"],"tanim":["Kireçtaşının yüksek sıcaklık ve basınç altında yeniden kristallenmesiyle oluşan kalsiyum karbonat (CaCO₃) esaslı metamorfik kayaç.","Sülfürik asit içeren asit yağmuruyla tepkimeye girerek yüzeyinde çözünür alçı oluşturur.","Tarihi yapılarda ve heykellerde asit çökelmesi nedeniyle yüzey kabartmalarının silinmesine ve yapısal malzeme kaybına uğrar."],"tanim_en":"A metamorphic rock consisting predominantly of calcium carbonate that undergoes chemical degradation when exposed to acidic precipitation.","bag":{"kavram":["asit-yagmuru","stokiyometri"],"soru":["S29"],"hesap":[]}},{"id":"nitric-oxide","tr":"Azot monoksit","en":"nitric oxide","kisa":"NO","tur":"kavram","es":["nitrojen monoksit","azot(II) oksit","nitrogen monoxide"],"tanim":["Yüksek sıcaklıktaki yanma olaylarında oluşan, azot ve oksijen atomlarından meydana gelen renksiz, zehirli ve radikal yapılı bir gazdır.","IUPAC adı azot monoksit olup egzoz emisyonlarındaki azot oksitlerin büyük payını oluşturur; şehir ortamında derişimi onlarca ppb düzeyine ulaşabilir.","Troposferde taze egzoz bölgesinde ozonla hızla tepkimeye girerek ozonu tüketir (titrasyon) ve azot dioksite (NO₂) dönüşür."],"tanim_en":"Reactive radical gas emitted from combustion that rapidly reacts with ozone in polluted air.","bag":{"kavram":["asit-yagmuru","titrasyon","leighton"],"soru":["S40","S43","S44"],"hesap":["leighton"]}},{"id":"primary-pollutant","tr":"Birincil kirletici","en":"primary pollutant","kisa":"","tur":"kavram","es":["birincil kirleticiler","doğrudan salınan kirletici","primary emission"],"tanim":["Belirli bir kaynaktan (baca, egzoz, volkan, yangın) doğrudan atmosfere verilen kimyasal kirleticidir.","Havadaki derişimi salım miktarına, rüzgâr hızına ve atmosferik sınır tabakanın karışma yüksekliğine bağlı olarak değişir.","NO, SO₂, CO ve is parçacıkları tipik örnekleridir; atmosferde kimyasal tepkimeye girerek ikincil kirleticileri oluştururlar."],"tanim_en":"Pollutant emitted directly into the atmosphere from an identifiable origin rather than forming through chemical reaction in the air.","bag":{"kavram":["asit-yagmuru","aerosol-sinif","titrasyon"],"soru":["S17","S28","S31","S43","S44"],"hesap":[]}},{"id":"secondary-pollutant","tr":"İkincil kirletici","en":"secondary pollutant","kisa":"","tur":"kavram","es":["ikincil kirleticiler","secondary air pollutant"],"tanim":["Kaynaktan doğrudan salınmayıp, birincil kirleticilerin ve öncül gazların atmosferde kimyasal veya fotokimyasal tepkimelere girmesiyle oluşan kirleticidir.","Oluşumu güneş ışığına, sıcaklığa ve ortamdaki öncül derişimlerine bağlı olup tepe değerleri emisyon kaynaklarının üzerinde değil, rüzgâraltında görülür.","Troposferik ozon (O₃), sülfürik asit (H₂SO₄), nitrik asit (HNO₃) ve peroksiasetil nitrat (PAN) en bilinen örnekleridir."],"tanim_en":"Air pollutant formed in the atmosphere through chemical or photochemical transformation of precursor emissions.","bag":{"kavram":["asit-yagmuru","titrasyon","aerosol-sinif"],"soru":["S14","S17","S21","S28","S31","S43"],"hesap":[]}},{"id":"strong-acid","tr":"Kuvvetli asit","en":"strong acid","kisa":"","tur":"kavram","es":["güçlü asit","tam ayrışan asit"],"tanim":["Sulu çözeltisinde moleküler yapısı neredeyse tamamen iyonlarına ayrışarak ortama hidronyum veren asit türü.","Atmosfer kimyasında kükürt dioksit ve azot oksitlerin yükseltgenmesiyle oluşan H₂SO₄ ve HNO₃ temel kuvvetli asitlerdir.","Yağmur suyunun pH değerini temiz yağmur referansı olan 5,6 seviyesinin altına indirerek asit yağmurunu oluşturur."],"tanim_en":"An acid that dissociates completely into ions in an aqueous solution, such as sulfuric acid and nitric acid in rain droplets.","bag":{"kavram":["asit-yagmuru"],"soru":["S27"],"hesap":[]}},{"id":"sulfur-trioxide","tr":"Kükürt trioksit","en":"sulfur trioxide","kisa":"SO₃","tur":"kavram","es":["kükürttrioksit","SO3","sulphur trioxide","kükürt VI oksit","SO₃"],"tanim":["Kükürdün +6 yükseltgenme basamağına sahip, formülü SO₃ olan inorganik gaz bileşiğidir.","Atmosferde kükürt dioksitin hidroksil radikalinin başlattığı tepkime zinciriyle yükseltgenmesi sonucu oluşur.","Su buharı ile çok hızlı tepkimeye girerek sülfürik aside (H₂SO₄) dönüşür ve sülfat aerosolü oluşturur."],"tanim_en":"Sulfur trioxide is an inorganic gas compound that rapidly reacts with water vapor to form sulfuric acid in the atmosphere.","bag":{"kavram":["asit-yagmuru","volkan-aerosol"],"soru":["S28"],"hesap":[]}},{"id":"third-body","tr":"Üçüncü cisim","en":"third body","kisa":"M","tur":"kavram","es":["çarpışan üçüncü cisim","çarpışma partneri","third body collider","[M]","üçüncü cisim molekülü","üçüncü gövde"],"tanim":["Üç cisimli tepkimede ürünün fazla enerjisini çarpışarak alıp götüren, kendisi değişmeden çıkan molekül; M ile gösterilir (çoğunlukla N₂ ya da O₂).","[M] havanın toplam sayı yoğunluğudur (molekül/cm³; kitapta 30 km'de 3,8 × 10¹⁷). Üç cisimli tepkimenin hız sabiti cm⁶ molekül⁻² s⁻¹ biriminde.","Yükseklikle [M] azaldığından R2 (O + O₂ + M → O₃ + M) yüksekte yavaşlar; M olmadan birleşen atom fazla enerjiyle hemen yeniden ayrışır."],"tanim_en":"A third body is a molecule, such as N₂ or O₂, that takes up the excess energy released when two species combine, so that the product is stabilised without the third body itself being changed.","bag":{"kavram":["asit-yagmuru","psc","arrhenius"],"soru":["S41"],"hesap":["chapman-o"]}},{"id":"transboundary-pollution","tr":"Sınır aşan kirlilik","en":"transboundary pollution","kisa":"","tur":"kavram","es":["sınır aşan hava kirliliği","transboundary air pollution","sınır ötesi kirlilik","uzun menzilli kirlilik"],"tanim":["Bir ülkenin sınırları içinde salınan kirleticilerin atmosferik hava hareketleriyle yüzlerce kilometre taşınarak başka ülkelerin topraklarına veya sularına çökmesi olayı.","Özellikle SO₂ ve NOₓ gibi öncül gazların atmosferik taşınım süresince sülfat ve nitrata dönüşmesiyle asit çökelmesi biçiminde ortaya çıkar.","Çevre kirliliğinin ulusal sınırları aşması nedeniyle uluslararası sözleşmeler ve sınır ötesi hava kirliliği protokolleri gerektirir."],"tanim_en":"Air pollution that originates in one country and creates environmental damage in another country after long-range atmospheric transport.","bag":{"kavram":["asit-yagmuru"],"soru":[],"hesap":[]}},{"id":"weathering","tr":"Ayrışma","en":"weathering","kisa":"","tur":"kavram","es":["kimyasal ayrışma","kayaç bozunması","bozunma","chemical weathering"],"tanim":["Yerkabuğundaki kayaç ve minerallerin atmosfer koşullarına maruz kalarak bulundukları yerde fiziksel veya kimyasal yollarla parçalanıp bozunması süreci.","Kimyasal ayrışmada atmosferik CO₂ gazının yağmur suyunda oluşturduğu karbonik asit ile asit yağmuru bileşenleri silikat ve karbonat minerallerini çözer.","Jeolojik zaman ölçeğinde atmosferdeki karbondioksitin dengelenmesinde ve toprak oluşumunda birincil rol oynar."],"tanim_en":"The chemical or mechanical breakdown of rock materials at the Earth's surface under the action of atmospheric agents.","bag":{"kavram":["asit-yagmuru"],"soru":["S26","S27","S29"],"hesap":["ph-temiz"]}},{"id":"buffering","tr":"Tamponlama","en":"buffering","kisa":"","tur":"surec","es":["tampon etkisi","asit tamponlama","tamponlama kapasitesi","buffer capacity"],"tanim":["Bir sulu çözeltinin veya çevresel ortamın asit ya da baz eklenmesine karşı kendi pH değerini koruma yeteneğidir.","Kireçtaşı içeren havzalarda karbonat ve bikarbonat iyonlarının asit yağmuruyla gelen H⁺ iyonlarını nötrlemesiyle gerçekleşir.","Asit yağmurlarının göl, akarsu ve toprak ekosistemlerinde neden olduğu pH düşüşünü ve ekolojik zararı sınırlar."],"tanim_en":"Buffering is the capacity of an aquatic or soil system to neutralize added acidic input and maintain its pH level.","bag":{"kavram":["asit-yagmuru"],"soru":["S29"],"hesap":[]}},{"id":"chain-reaction","tr":"Zincirleme tepkime","en":"chain reaction","kisa":"","tur":"surec","es":["tepkime zinciri","radikal zinciri","zincir tepkimesi","zincirleme reaksiyon"],"tanim":["Bir başlama basamağında üretilen reaktif ara ürünün tekrarlayan adımlarla çok sayıda tepkimeyi yürütmesi sürecidir.","Başlama, ilerleme ve sonlanma basamaklarından oluşur; reaktif radikal her çevrimde yeniden üretilir.","Stratosferde tek bir klor atomunun binlerce ozon molekülünü parçalamasını ve troposferde fotokimyasal duman gelişimini sağlar."],"tanim_en":"A chain reaction is a sequence of chemical elementary steps where a reactive intermediate is repeatedly regenerated to propagate reaction cycles.","bag":{"kavram":["katalitik","leighton"],"soru":["S32","S42"],"hesap":[]}},{"id":"neutralization","tr":"Nötrleme","en":"neutralization","kisa":"","tur":"surec","es":["nötralizasyon","asit nötrleme","nötralleşme","acid neutralization"],"tanim":["Bir asit ile bir bazın stokiyometrik oranlarda birleşerek birbirinin asidik ve bazik özelliklerini yok etmesi sürecidir.","Tepkime sonucunda tipik olarak tuz ve su (veya amonyum tuzları) açığa çıkar.","Atmosferdeki amonyak gazının sülfürik ve nitrik asitleri nötrleyerek amonyum sülfat ve amonyum nitrat aerosollerine dönüştürmesini sağlar."],"tanim_en":"Neutralization is a chemical reaction between an acid and a base yielding a salt and eliminating acidity.","bag":{"kavram":["asit-yagmuru","stokiyometri"],"soru":["S28","S29"],"hesap":[]}},{"id":"teragram","tr":"Teragram","en":"teragram","kisa":"Tg","tur":"birim","es":["Tg","10¹² g","bir milyon ton"],"tanim":["Metrik sistemde 10¹² grama yani 10⁹ kilograma veya bir milyon tona denk gelen kütle birimi.","Sembolü Tg olup atmosfer kimyası ve iklim çalışmalarında küresel atmosferik gaz yüklerini ve yıllık salım miktarlarını göstermek için kullanılır.","Kutu modellerinde gazların atmosferik ömrü hesaplanırken toplam atmosferik yük ile yıllık kayıp hızı bu birim üzerinden oranlanır."],"tanim_en":"A metric unit of mass equal to 10¹² grams or one megatonne, commonly applied to quantify global atmospheric pollutant burdens and annual emission flux.","bag":{"kavram":["atmosfer-kutlesi","omur","kutu-modeli"],"soru":["S4","S36"],"hesap":[]}},{"id":"column-density","tr":"Sütun yoğunluğu","en":"column density","kisa":"","tur":"kavram","es":["hava sütunu","air column","Hava sütunu","atmospheric column","kolon yoğunluğu","dikey sütun miktarı"],"tanim":["Yeryüzündeki birim yatay alanın üzerinde atmosferin üst sınırına kadar uzanan dikey hava sütunundaki toplam parçacık veya molekül sayısı.","Birimi molekül/cm² veya mol/m² olup toplam ozon miktarını belirtmek için Dobson birimi yaygın olarak kullanılır.","Uydu uzaktan algılama aygıtları ile doğrudan ölçülerek gazların optik derinliği ve ışınım soğurması hesaplanır."],"tanim_en":"The total number of gas molecules or particles per unit area integrated along a vertical path through the atmosphere.","bag":{"kavram":["atmosfer-kutlesi"],"soru":["S4"],"hesap":[]}},{"id":"dry-air","tr":"Kuru hava","en":"dry air","kisa":"","tur":"kavram","es":["kuru hava bileşimi","su buharı içermeyen hava"],"tanim":["İçerisindeki değişken su buharı tamamen uzaklaştırılmış, sabit bileşenli kuramsal atmosferik gaz karışımı.","Mol kesri olarak yaklaşık %78 N₂, %21 O₂ ve %0,93 Ar içerir; ortalama mol kütlesi 28,97 g/mol kabul edilir.","Meteoroloji ve atmosfer kimyasında nem hesaplamaları, karışma oranı ve gaz sabitleri için standart referans ortamdır."],"tanim_en":"Atmospheric air from which all water vapor has been removed, consisting primarily of nitrogen, oxygen, and argon with an average molar mass near 29 g/mol.","bag":{"kavram":["atmosfer-kutlesi"],"soru":["S4","S11"],"hesap":[]}},{"id":"methane","tr":"Metan","en":"methane","kisa":"CH₄","tur":"kavram","es":["CH4","bataklık gazı","metan gazı","marsh gas","CH₄"],"tanim":["En basit hidrokarbon yapısındaki kimyasal tür ve karbondioksitten sonraki en etkili ikinci insan kaynaklı sera gazı.","Küresel ortalama atmosferik karışım oranı yaklaşık 1934 ppb ve atmosferdeki toplam yükü yaklaşık 5600 Tg düzeyinde bulunur.","Troposferde yaklaşık 10 yıllık atmosferik ömrüyle iyi karışmış bir gazdır; temel yutağı hidroksil (OH) radikaliyle tepkimesidir."],"tanim_en":"An organic trace gas molecule that acts as the second most important anthropogenic greenhouse contributor with an atmospheric lifetime of approximately 10 years.","bag":{"kavram":["atmosfer-kutlesi","karisim-orani","sera-etkisi"],"soru":["S4","S5","S15","S36","S37","S38"],"hesap":[]}},{"id":"nitrogen-oxides","tr":"Azot oksitler","en":"nitrogen oxides","kisa":"NOₓ","tur":"kavram","es":["NOx","azot oksitleri","Azot oksitleri","NOₓ"],"tanim":["Atmosfer kimyasında azot monoksit (NO) ve azot dioksit (NO₂) bileşiklerinin toplamını belirten kimyasal terim.","Fosil yakıt yanması ve motorlu taşıt trafiğiyle salınan, ömrü troposferde saatler ile günler arasında değişen reaktif gaz grubudur.","Troposferik ozon ve fotokimyasal duman oluşumunda anahtar öncül olarak rol alır; havadaki oksidasyonuyla nitrik aside dönüşerek asit yağmuruna yol açar."],"tanim_en":"The atmospheric group comprising nitric oxide and nitrogen dioxide that serves as a key precursor to tropospheric ozone and photochemical smog.","bag":{"kavram":["atmosfer-kutlesi","aerosol-sinif","asit-yagmuru"],"soru":[],"hesap":[]}},{"id":"short-lived-gas","tr":"Kısa ömürlü gaz","en":"short-lived gas","kisa":"","tur":"kavram","es":["short-lived species","kısa ömürlü tür","kısa ömürlü iklim zorlayıcı"],"tanim":["Atmosferik ömrü küresel troposferik karışma süresinden (yaklaşık 1 yıl) belirgin şekilde daha kısa olan kimyasal tür.","Atmosferde homojen dağılacak zaman bulamadığından derişimi emisyon kaynaklarının yakınında yüksek kalır ve mekânsal değişkenlik gösterir.","NO₂, OH ve CO gibi türleri kapsar; bu gazların salımlarının azaltılması hava kalitesine ve iklime hızla yansır."],"tanim_en":"An atmospheric trace chemical whose lifetime is substantially shorter than the global mixing timescale, leading to pronounced spatial variability near emission regions.","bag":{"kavram":["atmosfer-kutlesi"],"soru":["S36","S38"],"hesap":[]}},{"id":"well-mixed-gas","tr":"İyi karışmış gaz","en":"well-mixed gas","kisa":"","tur":"kavram","es":["homojen karışmış gaz","homojen gaz","homojen dağılmış gaz","well-mixed greenhouse gas"],"tanim":["Atmosferdeki kalış ömrü küresel hava karışma süresinden (yaklaşık 1 yıl) çok daha uzun olan kimyasal gaz.","Troposfer genelinde homojen bir dağılım sergiler; yeryüzünde ölçülen karışım oranı değeri bütün dikey sütunu güvenle temsil eder.","Karbondioksit (CO₂), metan (CH₄) ve diazot monoksit (N₂O) gibi uzun ömürlü sera gazlarını kapsar."],"tanim_en":"An atmospheric trace gas component whose lifetime exceeds the global mixing timescale, resulting in a spatially uniform mixing ratio throughout the troposphere.","bag":{"kavram":["atmosfer-kutlesi","omur"],"soru":["S38"],"hesap":[]}},{"id":"air-density","tr":"Hava yoğunluğu","en":"air density","kisa":"ρ","tur":"olcu","es":["kütle yoğunluğu","yoğunluk","havanın yoğunluğu"],"tanim":["Birim hacimdeki havanın kütlesi.","Birimi kg/m³ olup deniz seviyesinde standart koşullarda yaklaşık 1,2 kg/m³ olarak ölçülür; irtifa arttıkça üstel olarak azalır.","Hidrostatik denge, dikey basınç gradyanı ve atmosfer kütlesi hesaplamalarında temel fiziksel durum büyüklüğüdür."],"tanim_en":"The mass of air per unit volume, typically measured in kilograms per cubic meter.","bag":{"kavram":["atmosfer-kutlesi","sayi-yogunlugu","stokes"],"soru":["S1","S15","S16","S17","S40","S41"],"hesap":["aerosol-mod","stokes"]}},{"id":"hydrostatic-balance","tr":"Hidrostatik denge","en":"hydrostatic balance","kisa":"","tur":"yontem","es":["hydrostatic equilibrium"],"tanim":["Atmosferde yukarı doğru yönelen düşey basınç gradyan kuvveti ile aşağı doğru çeken yerçekimi kuvvetinin tam dengede olması durumu.","Düşey eksende dP/dz = −ρg diferansiyel denklemiyle ifade edilir.","Büyük ölçekli atmosfer dinamiğinin temel kabullerindendir; yüzey basıncından toplam atmosfer kütlesinin hesaplanmasına olanak tanır."],"tanim_en":"The condition where the upward vertical pressure gradient force exactly balances the downward gravitational force in the atmosphere.","bag":{"kavram":["atmosfer-kutlesi"],"soru":["S4"],"hesap":["atmosfer-kutlesi"]}},{"id":"diffuse-radiation","tr":"Yaygın (difüz) ışınım","en":"Diffuse radiation","kisa":"","tur":"kavram","es":["dağınık ışınım","saçılan ışık","difüz ışık","saçılan gök ışığı","yayılı ışınım"],"tanim":["Güneşten gelen ışınımın atmosferdeki gaz molekülleri ve aerosol parçacıkları tarafından saçılmasıyla gökyüzünün her yönünden yeryüzüne ulaşan güneş ışınımı.","Birimi W/m² olup doğrudan gelen güneş demetiyle birlikte toplam küresel ışınımı oluşturur.","Bulutlu ve yoğun puslu günlerde doğrudan ışın engellenirken yüzeye ulaşan güneş ışınımının neredeyse tamamı yaygın ışıktan meydana gelir."],"tanim_en":"Solar radiation reaching the Earth's surface after its direction has been altered by scattering from atmospheric molecules and aerosol particles.","bag":{"kavram":["beer-lambert","aerosol-dogrudan"],"soru":["S24","S25"],"hesap":[]}},{"id":"direct-beam","tr":"Doğrudan ışın","en":"direct beam","kisa":"","tur":"kavram","es":["direkt ışınım","doğrudan güneş ışınımı","direct solar radiation"],"tanim":["Güneş diskinden çıkıp atmosfer boyunca yön değiştirmeden ve saçılmaya uğramadan doğrudan yeryüzüne varan paralel güneş ışınımı demeti.","Şiddeti W/m² birimiyle ifade edilir ve soğurucu ile saçıcı tabakadan geçerken Beer–Lambert yasasına göre üstel olarak zayıflar.","Yeryüzünde net gölge oluşumunu sağlayan temel bileşendir; yaygın ışık ile toplanarak yeryüzünün toplam güneşlenme girdisini belirler."],"tanim_en":"Solar radiation traveling in a straight line from the solar disk to the surface without being scattered or absorbed by the atmosphere.","bag":{"kavram":["beer-lambert"],"soru":["S24","S25","S33"],"hesap":["egik-isin"]}},{"id":"optical-air-mass","tr":"Optik hava kütlesi","en":"optical air mass","kisa":"m","tur":"olcu","es":["optik hava kütlesi faktörü","eğik ışın yolu","eğik optik yol","Eğik ışın yolu","Eğik yol","Slant path"],"tanim":["Güneş ışınının atmosferden geçerken katettiği eğik optik yol uzunluğunun dikey (zenit) yol uzunluğuna oranını veren boyutsuz çarpan.","Düzlem paralel atmosferde yaklaşık 1/cos θ olarak hesaplanır; güneş tepedeyken 1 iken, θ = 60°'de 2 ve θ = 80°'de 5,76 değerini alır.","Beer–Lambert eşitliğinde dikey optik derinliği çarparak eğik gelen doğrudan ışının atmosferde katettiği fazladan yolu hesaba katar."],"tanim_en":"The ratio of the optical path length of a solar beam through the atmosphere at a given zenith angle to the path length vertically overhead.","bag":{"kavram":["beer-lambert"],"soru":["S24"],"hesap":["egik-isin"]}},{"id":"transmittance","tr":"Geçirgenlik","en":"transmittance","kisa":"I/I₀","tur":"olcu","es":["doğrudan geçen pay","geçen pay","transmisyon","Doğrudan ışın geçirimi","Direct beam transmittance","transmissivity"],"tanim":["Bir ortamdan geçen ışınımın, ortama gelen ışınıma oranıdır.","Boyutsuzdur ve 0 ile 1 arasında değer alır; kitapta I/I₀ olarak yazılır. Optik derinlikle bağı T = e^(−τ) biçiminde, eğik yolda T = exp(−τ / cos θ) olur.","Atmosferin güneş ışığını ne kadar geçirdiğini ölçer; 'transmission' süreci, 'transmittance' ise ölçülen oranı anlatır."],"tanim_en":"Transmittance is the ratio of the radiation transmitted by a medium to the radiation incident on it.","bag":{"kavram":["beer-lambert","tek-katman"],"soru":["S24","S25"],"hesap":["egik-isin","optik-derinlik","beer-kesit"]}},{"id":"rayleigh-scattering","tr":"Rayleigh saçılması","en":"Rayleigh scattering","kisa":"","tur":"surec","es":["moleküler saçılma","mavi ışık saçılması"],"tanim":["Işığın dalga boyundan çok küçük saçıcılar (hava molekülleri) tarafından saçılmasıdır.","Şiddet λ⁻⁴ ile orantılıdır: kısa dalga boyları (mavi) uzun dalga boylarından (kırmızı) çok daha güçlü saçılır.","Mavi gökyüzünü ve kırmızı gün batımını açıklar; aerosol boyutunda (D ≈ λ) saçılma Mie türüne geçer."],"tanim_en":"Rayleigh scattering is the scattering of radiation by particles much smaller than the wavelength, such as air molecules, with intensity proportional to λ⁻⁴.","bag":{"kavram":["beer-lambert","koschmieder"],"soru":["S24"],"hesap":[]}},{"id":"scattering","tr":"Saçılma","en":"scattering","kisa":"","tur":"surec","es":["ışık saçılması","ışık saçma","Işık saçılması","Light scattering","light scattering"],"tanim":["Işınımın atmosferdeki gaz molekülleri veya aerosol parçacıklarıyla etkileşime girerek foton enerjisi kaybolmaksızın yön değiştirmesi süreci.","Saçılma kesiti σₛ (cm²) ya da saçılma katsayısıyla ölçülür; saçılma ve soğurma kesitlerinin toplamı sönüm kesitini, katsayılarının toplamı ise sönüm (yok olma) katsayısını verir.","Gökyüzünün mavi görünmesini sağlar, puslu havalarda görüş mesafesini sınırlar ve güneş ışığını uzaya geri saçarak gezegen albedosunu yükseltir."],"tanim_en":"The physical mechanism in which electromagnetic radiation is deflected in diverse directions by atmospheric particles or gas molecules without thermal conversion.","bag":{"kavram":["beer-lambert","aerosol-dogrudan","volkan-aerosol"],"soru":["S15","S18","S22","S23","S24","S25"],"hesap":["optik-derinlik","beer-kesit"]}},{"id":"unit-nanometer","tr":"Nanometre","en":"Nanometer","kisa":"nm","tur":"birim","es":["milimikron","dalga boyu birimi","nm"],"tanim":["Uzunluk birimidir: 1 nm = 10⁻⁹ m = 10⁻³ µm.","Kitapta aerosol boyutunu (nm'den yaklaşık 100 µm'ye) ve morötesi dalga boylarını ifade etmek için kullanılır.","Küçük parçacıkları ve fotolizin eşik dalga boyunu (örneğin O₂ için λ < 240 nm) karşılaştırmak için uygundur."],"tanim_en":"The nanometre is a unit of length equal to one billionth of a metre (10⁻⁹ m), used for particle sizes and wavelengths of light.","bag":{"kavram":["boyut-modlari","aerosol-sinif","fotoliz"],"soru":[],"hesap":[]}},{"id":"accumulation-mode","tr":"Birikme modu","en":"Accumulation mode","kisa":"","tur":"kavram","es":["birikim modu","akümülasyon modu"],"tanim":["Çapı yaklaşık 0,1–2,5 µm olan aerosol parçacıklarının boyut modudur (kitaptaki örnekte yarıçap ≈ 0,1 µm).","Parçacıklar pıhtılaşma ve yoğuşmayla büyüyerek bu modda 'birikir'; hem büyümesi hem çökelmesi yavaştır, bu yüzden en uzun ömürlü moddur.","Çapları görünür ışığın dalga boyuna (0,4–0,7 µm) yakın olduğundan kesit başına en verimli saçıcıdır; görüşü, saçılmayı ve bulut çekirdeği sayısını bu mod belirler."],"tanim_en":"The accumulation mode is the aerosol size range of roughly 0.1–2.5 µm in diameter, in which particles grow by coagulation and condensation, persist longest and dominate light scattering and visibility.","bag":{"kavram":["boyut-modlari","koschmieder"],"soru":["S15","S16","S20","S23"],"hesap":[]}},{"id":"aerosol-size-distribution","tr":"Aerosol boyut dağılımı","en":"Aerosol size distribution","kisa":"","tur":"kavram","es":["boyut spektrumu","parçacık boyut dağılımı","boyut dağılımı","size distribution"],"tanim":["Havadaki aerosol parçacıklarının farklı boyut sınıflarındaki göreli bolluğudur.","Aynı dağılım sayıyla (r⁰), kesitle (S = nπr², r²) ya da hacimle (V = n·4/3·πr³, r³) tartılabilir; tepe her tartımda başka modda çıkar.","Hangi niceliğin çizildiği eksen başlığından okunur; sayı çekirdek modunu, kesit birikme modunu, hacim iri modu gösterir."],"tanim_en":"The aerosol size distribution is the relative abundance of atmospheric aerosol particles in various size categories, weighted by number, surface area or volume.","bag":{"kavram":["boyut-modlari"],"soru":["S15"],"hesap":[]}},{"id":"coarse-mode","tr":"İri mod","en":"Coarse mode","kisa":"","tur":"kavram","es":["kaba mod","iri parçacık modu"],"tanim":["Çapı 2,5 µm'den büyük (D > 2,5 µm) aerosol parçacıklarının oluşturduğu boyut modudur.","Rüzgâr, dalga ve aşınma gibi mekanik süreçlerle oluşur ve kısa sürede çöker.","Sayıca azdır ama hacmi (kütlesi) en büyük moddur; PM10 kütlesini belirler."],"tanim_en":"The coarse mode is the aerosol size range of particles larger than about 2.5 µm in diameter, produced mainly by mechanical generation (wind, waves, abrasion) and dominating particle mass.","bag":{"kavram":["boyut-modlari","pm"],"soru":["S10","S14","S15","S16","S23"],"hesap":[]}},{"id":"nucleation-mode","tr":"Çekirdek modu","en":"Nucleation mode","kisa":"","tur":"kavram","es":["çekirdeklenme modu","Aitken modu","nuclei mode","nükleasyon modu","Aitken çekirdekleri","Aitken mode"],"tanim":["Gazdan yeni doğan en küçük aerosol parçacıklarının modudur (r ≈ 0,005–0,01 µm).","Sayıca en çok, kütlece en az moddur; kesit ve hacim payı küçüktür.","Bazı kaynaklar 10–100 nm aralığını ayrı bir mod olarak adlandırır; kitapta çekirdek modu olarak geçer."],"tanim_en":"The nucleation mode is the smallest aerosol size range (radius about 0.005–0.01 µm), containing freshly formed particles that are most numerous but contribute least to mass.","bag":{"kavram":["boyut-modlari"],"soru":["S15","S16"],"hesap":[]}},{"id":"ultrafine-particles","tr":"Ultra ince (nano) parçacıklar","en":"Ultrafine particles","kisa":"UFP","tur":"kavram","es":["nano parçacık","nanopartikül","ultra ince parçacık","UFP"],"tanim":["Çapı 0,1 µm'den küçük (D < 0,1 µm) aerosol parçacıklarıdır.","Kütlesi çok küçük olduğundan PM ölçümünde neredeyse görünmez; ama sayıca çoktur.","Difüzyonla solunum yolu duvarına ulaşır ve akciğerin en derin bölgesine (alveol) iner; mikron altı ve nano parçacıklar kana geçebilir."],"tanim_en":"Ultrafine particles are aerosol particles smaller than about 0.1 µm in diameter, which contribute little mass but are numerous and deposit deep in the lung.","bag":{"kavram":["boyut-modlari","pm"],"soru":["S20"],"hesap":[]}},{"id":"cross-sectional-area","tr":"Kesit alanı","en":"cross-sectional area","kisa":"πR²","tur":"olcu","es":["kesit alanı derişimi","izdüşüm alanı"],"tanim":["Bir parçacığın ya da gök cisminin gelen paralel ışın demetine dik izdüşüm alanı.","Parçacık topluluklarında birim hacimdeki toplam kesit alanı S = nπr² bağıntısıyla belirlenir ve µm²/cm³ birimiyle ifade edilir.","Gelen ışınımın soğurulma ve saçılma miktarını doğrudan belirler; gezegenin güneş enerjisini yakalayan disk alanını temsil eder."],"tanim_en":"The geometric projected area of an atmospheric particle or planetary body perpendicular to incident radiation.","bag":{"kavram":["boyut-modlari","twomey","isinim-dengesi"],"soru":["S6","S15","S22"],"hesap":["etkin-sicaklik"]}},{"id":"sym-particle-diameter","tr":"Parçacık çapı","en":"particle diameter","kisa":"D","tur":"olcu","es":["D_p","çap","parçacık boyu"],"tanim":["Bir aerosol parçacığının ya da bulut damlasının doğrusal boyutu veya eşdeğer küresel genişliği.","Genellikle mikrometre (µm) ya da nanometre (nm) birimiyle verilir; r yarıçapının iki katı olarak (D = 2r) tanımlanır.","Parçacığın havada asılı kalma süresini, solunum yolundaki çökelme bölgesini ve optik saçılma verimini kontrol eder."],"tanim_en":"The linear physical dimension characterizing the geometric size of an airborne aerosol particle or cloud droplet.","bag":{"kavram":["boyut-modlari","pm","stokes"],"soru":["S15","S16","S17","S20","S23"],"hesap":["stokes"]}},{"id":"sym-volume-concentration","tr":"Hacim derişimi","en":"volume concentration","kisa":"V","tur":"olcu","es":["parçacık hacmi","hacimsel derişim","hacim","aerosol hacmi","V","toplam aerosol hacmi"],"tanim":["Birim hava hacminde bulunan aerosol parçacıklarının toplam geometrik hacmi.","Genellikle µm³/cm³ birimiyle ifade edilir; küresel parçacık yaklaşımında V = n(4/3)πr³ bağıntısıyla hesaplanır.","Parçacık yoğunluğu ile çarpıldığında doğrudan atmosferik kütle derişimine (µg/m³) dönüşür; kütle payının belirlenmesini sağlar."],"tanim_en":"The total geometric volume of suspended aerosol material contained within a unit volume of air.","bag":{"kavram":["boyut-modlari","aerosol-sinif"],"soru":["S1","S2","S3","S4","S15","S16"],"hesap":["aerosol-mod"]}},{"id":"brownian-diffusion","tr":"Brown difüzyonu","en":"Brownian diffusion","kisa":"","tur":"surec","es":["Brown hareketi","difüzyonla çökelme","Brownian motion"],"tanim":["Akışkan moleküllerinin rastgele ısıl çarpışmaları sonucu çok küçük aerosol parçacıklarının net yer değiştirmesi süreci.","Parçacık çapı küçüldükçe difüzyon katsayısı hızla artar; özellikle 0,1 µm altındaki nano parçacıklarda baskın taşıma mekanizmasıdır.","Solunum yolunun en derin bölgesi olan alveollerde nano parçacıkların doku yüzeylerine çarparak tutulmasını sağlar."],"tanim_en":"The net transport of ultrafine aerosol material driven by continuous random thermal collisions with surrounding air molecules.","bag":{"kavram":["boyut-modlari","pm"],"soru":["S20"],"hesap":[]}},{"id":"coagulation","tr":"Pıhtılaşma","en":"coagulation","kisa":"","tur":"surec","es":["koagülasyon","topaklaşma"],"tanim":["Havada asılı küçük parçacıkların çarpışıp birleşerek daha büyük tek bir parçacık oluşturmasıdır.","Parçacık sayısı azalır, boyutu artar; toplam kütle değişmez.","Çekirdek modundaki parçacıkları birikme moduna taşıyan başlıca yoldur; kitapta 'pıhtılaşma', bazı kaynaklarda 'koagülasyon' ya da 'topaklaşma' denir."],"tanim_en":"Coagulation is the joining of small suspended particles into larger particles through collisions, which reduces particle number while enlarging particle size.","bag":{"kavram":["boyut-modlari"],"soru":[],"hesap":[]}},{"id":"nucleation","tr":"Çekirdeklenme (nükleasyon)","en":"nucleation","kisa":"","tur":"surec","es":["nükleasyon","yeni parçacık oluşumu","new particle formation"],"tanim":["Gaz fazından yeni parçacık doğma sürecidir; buhar, özel parçacıklar ('çekirdekler') üzerinde ya da kendiliğinden sıvı ya da katı faza geçer.","Atmosferde örneğin H₂SO₄ ve H₂O buharlarının bir araya gelmesiyle yeni parçacıklar oluşur; gazdan parçacığa dönüşümün ilk basamağıdır.","Parçacık sayısını artırır; gazdan dönüşen aerosollerin ince modda yer almasının nedenidir."],"tanim_en":"Nucleation is the formation of new particles from the vapour phase, in which a substance goes to the liquid or solid phase with or without the aid of special nuclei.","bag":{"kavram":["boyut-modlari"],"soru":["S14","S15","S17","S23"],"hesap":[]}},{"id":"cirrus","tr":"Sirrus","en":"cirrus","kisa":"Ci","tur":"kavram","es":["sirüs bulutu","siriform bulut","cirrus cloud","yüksek bulut","Cirrus cloud","Ci"],"tanim":["Troposferin üst katmanlarında (genellikle > 5–7 km) bulunan, bütünüyle buz kristallerinden oluşan, lifsi ve ince yüksek bulut cinsi.","Bulut tepesi oldukça soğuktur (tipik 220 K); güneş albedosunu az artırırken yüzeyden gelen kızılötesi ışınımı kuvvetle tutar.","Geri yaydığı sera etkisi güneş yansıtma etkisini aştığı için Dünya yüzeyinde net ısınmaya yol açar."],"tanim_en":"A high atmospheric cloud composed of ice crystal particles that yields a net warming impact at the Earth's surface.","bag":{"kavram":["bulut-isinim"],"soru":["S7","S10","S11","S12"],"hesap":[]}},{"id":"high-cloud","tr":"Yüksek bulut","en":"high cloud","kisa":"","tur":"kavram","es":["yüksek seviye bulutu","high-level clouds","sirrüs tipi bulut","high-level cloud","üst seviye bulutu"],"tanim":["Troposferin üst katmanında (genellikle 5–7 km üzerinde) yer alan sirrus, sirrokümülüs ve sirrostratus bulutları grubu.","Bütünüyle buz kristallerinden meydana gelir ve tepe sıcaklığı yüzey sıcaklığına göre oldukça düşüktür.","Atmosfer modelinde ilave bir sera katmanı gibi davranarak uzaya giden uzun dalga ışınımı engeller ve yüzeyi net olarak ısıtır."],"tanim_en":"A cloud belonging to the upper tropospheric level that typically exerts a net warming influence on the Earth's surface.","bag":{"kavram":["bulut-isinim"],"soru":["S7","S10","S11","S12"],"hesap":[]}},{"id":"ice-crystal","tr":"Buz kristali","en":"ice crystal","kisa":"","tur":"kavram","es":["bulut buz parçacığı","atmospheric ice crystal","atmosferik buz kristali"],"tanim":["Üst troposferde ya da soğuk bulutlarda su buharının doğrudan katıya geçmesi (depozisyon) veya aşırı soğumuş damlacıkların donmasıyla oluşan katı su parçacığı.","Sıcaklığa ve neme bağlı olarak altıgen prizma, levha veya iğne gibi çeşitli kristal geometrilerinde gelişir.","Sirrus bulutlarının temel yapı taşıdır; karışık fazlı bulutlarda buhar basıncı farkı nedeniyle aşırı soğumuş sıvı damlaların aleyhine hızla büyür."],"tanim_en":"A solid macroscopic particle of frozen water formed in the cold atmosphere that constitutes cirrus and mixed-phase cloud formations.","bag":{"kavram":["bulut-isinim"],"soru":[],"hesap":[]}},{"id":"low-cloud","tr":"Alçak bulut","en":"low cloud","kisa":"","tur":"kavram","es":["alçak seviye bulutu","low-level clouds","low-level cloud","alt seviye bulutu"],"tanim":["Tabanı genellikle 2 km altında yer alan, stratus ve stratokümülüs gibi sıvı su damlalarından oluşan bulut cinsi grubu.","Bulut tepe sıcaklığı yüzey sıcaklığına çok yakındır (tipik 280 K) ve uzaya kaçan kızılötesi ışınımı pek değiştirmez.","Güneş ışınımını yüksek albedosuyla uzaya geri yansıtarak Dünya yüzeyinde net soğutma etkisi meydana getirir."],"tanim_en":"A cloud situated below two kilometers altitude that reflects incoming solar radiation and cools the Earth's surface.","bag":{"kavram":["bulut-isinim"],"soru":["S10","S11","S12"],"hesap":[]}},{"id":"mixed-phase-cloud","tr":"Karışık fazlı bulut","en":"mixed-phase cloud","kisa":"","tur":"kavram","es":["sıvı-buz karışık bulut","karışık bulut"],"tanim":["Sıvı su damlacıkları ile buz kristallerinin atmosferde aynı hava hacminde bir arada bulunduğu bulut türü.","Genellikle 0 °C ile yaklaşık −38 °C arasındaki sıcaklık aralığında varlığını sürdürür.","Buz üzerindeki doymuş buhar basıncı sıvı sudan daha düşük olduğundan buz kristalleri sıvı damlaların buharlaşmasıyla hızla büyür."],"tanim_en":"A cloud containing both supercooled liquid water droplets and ice crystal particles concurrently in the atmosphere.","bag":{"kavram":["bulut-isinim"],"soru":[],"hesap":[]}},{"id":"stratus","tr":"Stratus","en":"stratus","kisa":"St","tur":"kavram","es":["stratus bulutu","katman bulut","stratiform bulut","stratus cloud","alçak bulut","Stratus cloud"],"tanim":["Yer yüzeyine yakın seviyede (< 2 km) tekdüze yatay bir tabaka oluşturan, gri renkli alçak bulut cinsi.","Tepe sıcaklığı yüzeye yakındır (tipik 280 K) ve optik olarak kalın yapısıyla güneş ışığını kuvvetle geri yansıtır.","Yüzeye yakın sıcaklıkta ışıma yaptığından sera etkisi zayıf kalır ve yüksek yansıtma oranıyla iklimi net olarak soğutur."],"tanim_en":"A low uniform grey cloud layer composed of liquid water droplets that strongly reflects sunlight and cools the surface.","bag":{"kavram":["bulut-isinim"],"soru":["S10"],"hesap":[]}},{"id":"warm-cloud","tr":"Sıcak bulut","en":"warm cloud","kisa":"","tur":"kavram","es":["yalnız sıvı bulut","sıvı fazlı bulut","liquid-only cloud"],"tanim":["Sıcaklığı donma noktasının (0 °C) üstünde olan ve bu yüzden yalnız sıvı su damlası içeren bulut; yükselen nemli havada yoğuşmayla oluşur.","Meteorolojide «sıcak» donma noktasının üstü demektir; bulut içinde buz kristali yoktur, yağış damlaların çarpışıp birleşmesiyle oluşur.","Kitapta karışık fazlı buluttan (sıvı + buz) ayırmak için kullanılır; ışınım hesabında alçak ve sıcak tepeli bulutlar bu gruba girer."],"tanim_en":"A warm cloud is a cloud at a temperature above 0 °C that therefore contains only liquid water droplets, formed by condensation in ascending moist air.","bag":{"kavram":["bulut-isinim"],"soru":["S10"],"hesap":[]}},{"id":"cloud-cover","tr":"Bulut örtüsü","en":"cloud cover","kisa":"","tur":"olcu","es":["bulut kapalılığı","bulutluluk","cloud fraction","cloud amount"],"tanim":["Gökyüzünün bulutla kaplı kesri; okta ya da yüzde olarak verilir. Model ve uydu dilinde aynı anlamda «cloud fraction» denir.","Gözlemle (okta) ya da uydu görüntüsünden hesaplanan boyutsuz bir kesirdir; bulutun kalınlığını ya da yüksekliğini göstermez.","Kitapta ısınmayla su buharı artınca örtünün nasıl değişeceği iklimin en büyük belirsizliği olarak ele alınır; örtü artarsa albedo artar ve soğutucu geri besleme beklenir."],"tanim_en":"Cloud cover is the fraction of the sky covered by clouds, expressed in oktas or as a percentage.","bag":{"kavram":["bulut-isinim"],"soru":["S12"],"hesap":["tek-katman"]}},{"id":"cloud-top-temperature","tr":"Bulut tepesi sıcaklığı","en":"cloud-top temperature","kisa":"T_tepe","tur":"olcu","es":["Ttepe","bulut tepe sıcaklığı","T_tepe","Tc"],"tanim":["Bulut tepesinin ya da o seviyeye yakın havanın sıcaklığı.","Kelvin cinsinden verilir; kitapta tipik değerler sirrus için 220 K, stratus için 280 K'dir. Opak bulut uzaya bu sıcaklıkta kara cisim gibi yayar: σT⁴.","Soğuk tepe (yüksek bulut) az yayar, yüzeyden gelen IR'nin çoğunu tutar ve ısıtır; sıcak tepe (alçak bulut) çok yayar ve az IR tutar."],"tanim_en":"Cloud-top temperature is the temperature of a cloud top or of the air near that level.","bag":{"kavram":["bulut-isinim"],"soru":["S10"],"hesap":["bulut-net"]}},{"id":"dobson-unit","tr":"Dobson birimi","en":"Dobson unit","kisa":"DU","tur":"birim","es":["DU","Dobson","toplam ozon birimi","Dobson units"],"tanim":["Toplam ozon sütununun birimi: sütundaki bütün ozon 0 °C ve 1 atm'de sıkıştırılsaydı oluşacak tabakanın kalınlığı; 1 DU = 0,01 mm.","1 DU = 2,69 × 10¹⁶ ozon molekülü/cm²; dünya ortalaması ≈ 300 DU, yani bütün sütun yalnız ≈ 3 mm saf ozona denktir.","Ozon deliği toplam ozonun 220 DU'nun altına indiği bölge olarak tanımlanır; uydu ve yer ölçerleri toplam ozonu bu birimle verir."],"tanim_en":"The Dobson unit (DU) is the unit of total column ozone: 1 DU corresponds to a 0.01 mm thick layer of pure ozone at standard temperature and pressure (2.69 × 10¹⁶ molecules cm⁻²).","bag":{"kavram":["chapman","katalitik"],"soru":[],"hesap":[]}},{"id":"unit-rate-constant-termolecular","tr":"Üç cisimli hız sabiti birimi","en":"termolecular rate-constant unit","kisa":"cm⁶ molekül⁻² s⁻¹","tur":"birim","es":["cm⁶ s⁻¹","cm⁶ molekül⁻² s⁻¹"],"tanim":["Üç ayrı kimyasal türün aynı anda çarpışarak tek bir ürün verdiği üç cisimli tepkimelerin hız sabitinin birimidir.","Standart atmosfer kimyası gösteriminde cm⁶ molekül⁻² s⁻¹ veya kısaca cm⁶ s⁻¹ birimiyle ifade edilir.","Chapman çevriminde atomik oksijen ile moleküler oksijenin üçüncü bir cisim (M) eşliğinde ozon oluşturduğu R2 tepkimesinin hızını belirler."],"tanim_en":"The unit of the rate constant for a termolecular chemical reaction, expressed as cm⁶ molecule⁻² s⁻¹.","bag":{"kavram":["chapman"],"soru":["S41"],"hesap":[]}},{"id":"oxygen-atom","tr":"Oksijen atomu","en":"oxygen atom","kisa":"O","tur":"kavram","es":["O atomu","O(³P)","atomik oksijen","atomic oxygen"],"tanim":["Tek bir oksijen atomu, O; radikal gibi tepkimeye giren çok etkin bir türdür. «Oxygen molecule» O₂'dir.","Taban durum O(³P) ozon yapar (O + O₂ + M → O₃ + M); uyarılmış O(¹D) suyla OH üretir. Stratosferde çok kısa yaşar (30 km'de yaklaşık 0,03 s).","Kitapta O₃ fotolizinden (R3) ve O₂ fotolizinden (R1) oluşur; üst stratosferde bol bulunur. Troposferde NO₂ fotolizi O(³P) sağlayıp ozon üretimini başlatır."],"tanim_en":"An oxygen atom is a single oxygen atom, O, which in its ground state O(³P) combines with O₂ to form ozone and in its excited state O(¹D) reacts with water vapour to form OH.","bag":{"kavram":["chapman","psc","fotoliz"],"soru":["S40","S41"],"hesap":[]}},{"id":"ozone-layer","tr":"Ozon tabakası","en":"ozone layer","kisa":"","tur":"kavram","es":["ozonosfer","stratosferik ozon tabakası","iyi ozon"],"tanim":["Stratosferde O₃'ün en yoğun olduğu kuşak; kabaca 15–35 km arasındadır ve sayı yoğunluğu tepesi yaklaşık 20–25 km'de.","Toplam ozon sütunu ortalama yaklaşık 300 DU'dur. Karışım oranı yaklaşık 30–35 km'de en yüksektir (yaklaşık 8–10 ppm), mutlak molekül sayısı ise hava yoğunluğu aşağı doğru katlanarak arttığından daha alçakta zirve yapar.","Zararlı morötesi (UV-C ve büyük ölçüde UV-B) ışınımı soğurur. Yer seviyesindeki ozon ayrı bir olgudur ve kirleticidir: «iyi ozon – kötü ozon» ayrımı."],"tanim_en":"The ozone layer is the region of the stratosphere, roughly 15 to 35 km above the surface, where ozone concentration is greatest and which absorbs most harmful ultraviolet radiation.","bag":{"kavram":["chapman","katalitik"],"soru":["S1"],"hesap":[]}},{"id":"odd-oxygen","tr":"Tek oksijen","en":"odd oxygen","kisa":"Oₓ","tur":"kod","es":["Ox","tek sayılı oksijen","tekil oksijen","tek oksijen korunumu","Oₓ korunumu","Odd oxygen conservation"],"tanim":["Atmosfer kimyasında hızlı birbirine dönüşen oksijen türlerini bir arada sayan aile; Oₓ simgesiyle gösterilir. «Odd» burada «tek» demektir.","Stratosferde Oₓ = O + O₃: R2 ve R3 O ile O₃'ü saniyeler içinde birbirine çevirir, toplam korunur. Kent havasında Oₓ = O₃ + NO₂ diye başka bir aile tanımlanır; bağlama bakmak gerekir.","Oₓ'i yalnız R1 üretir, R4 ve katalitik döngüler yok eder; stratosferde O₃ baskın olduğundan Oₓ pratikte O₃'tür."],"tanim_en":"Odd oxygen is the family of rapidly interconverting oxygen species, in the stratosphere O plus O₃, whose total is conserved by the fast cycling reactions.","bag":{"kavram":["chapman","titrasyon"],"soru":["S40","S41"],"hesap":[]}},{"id":"fast-cycle","tr":"Hızlı çevrim (O ⇄ O₃)","en":"fast cycling of O and O₃","kisa":"","tur":"surec","es":["hızlı döngü","O–O₃ hızlı dönüşümü","[O]/[O₃] oranı","oksijen–ozon oranı"],"tanim":["Stratosferde ozon fotolizi ile atomik oksijenin ve moleküler oksijenin yeniden birleşmesi arasında saniyeler içinde gerçekleşen hızlı karşılıklı dönüşümdür.","Bu denge sürecinde tek oksijen ailesi (Oₓ = O + O₃) miktarı korunur ve fotokimyasal [O]/[O₃] oranını J₃ / (k₂[O₂][M]) bağıntısı tayin eder.","Döngüde soğurulan morötesi foton enerjisi ısıya dönüşür; stratosferin ısınmasını sağlayan başlıca süreçtir."],"tanim_en":"The rapid photochemical interconversion between atomic oxygen and ozone in the stratosphere on a timescale of seconds.","bag":{"kavram":["chapman"],"soru":[],"hesap":[]}},{"id":"stratospheric-heating","tr":"Stratosferik ısınma","en":"stratospheric heating","kisa":"","tur":"surec","es":["stratosferin ısınması"],"tanim":["Ozonun güneşten gelen morötesi ışınımı veya stratosferik aerosollerin yer ve güneş kaynaklı kızılötesi ışınımı soğurmasıyla katman sıcaklığının yükselmesidir.","Doğal koşullarda ozon fotolizi ve hızlı çevrim sayesinde stratosfer boyunca sıcaklığın yükseklikle artmasını sağlayarak tabakalı kararlı yapıyı kurar.","Ani stratosferik ısınmadan (kış kutup girdabının dinamik olarak bozulup birkaç günde onlarca derece ısınması) farklıdır; burada söz konusu olan ışınım soğurmasıyla oluşan ısınmadır."],"tanim_en":"The heating of the stratosphere driven by the absorption of solar ultraviolet radiation by ozone and infrared radiation by aerosol particles.","bag":{"kavram":["chapman","isinim-dengesi"],"soru":["S30"],"hesap":[]}},{"id":"monsoon","tr":"Muson","en":"monsoon","kisa":"","tur":"kavram","es":["muson dolaşımı","monsoon circulation","muson rüzgârları","Asya musonu","muson yağışları","muson rüzgârı"],"tanim":["Genel dolaşımda mevsimsel kalıcı rüzgâr yönüyle ve bir mevsimden ötekine belirgin yön değişimiyle tanınan rüzgâr. Ana nedeni kara ile komşu okyanusun mevsime göre değişen ısınma farkıdır.","Yön değişimine geniş çaplı sıcaklık ve yağış değişimleri eşlik eder; özellikle yarı tropik bölgelerde yaz musonu yağışının ana kaynağıdır.","Kitapta volkanik soğumanın dolaşıma etkisi olarak geçer: deniz soğuyunca buharlaşma azalır, Hadley hücresi zayıflar ve muson yağışı düşer."],"tanim_en":"A monsoon is a seasonally persistent wind that changes direction markedly from one season to another, driven mainly by the differential heating between a continent and the adjacent ocean.","bag":{"kavram":["clausius","volkan-aerosol"],"soru":["S33"],"hesap":[]}},{"id":"relative-humidity","tr":"Bağıl nem","en":"relative humidity","kisa":"RH","tur":"olcu","es":["nisbi nem","oransal nem","RH","göreli nem"],"tanim":["Havadaki buhar basıncının, aynı sıcaklık ve basınçta doymuş buhar basıncına oranı yüzde olarak: RH = e / eₛ × 100 (%).","Boyutsuzdur ve havadaki buhar miktarının kendisi değildir; sıcaklık artınca eₛ arttığı için aynı buhar miktarında RH düşer.","Kitapta ısınmayla eₛ yaklaşık %7/K arttığında RH kabaca sabit kalırsa buharın da aynı oranda artacağı, bunun da en güçlü pozitif geri beslemeyi (su buharı) verdiği kullanılır."],"tanim_en":"Relative humidity is the ratio, expressed as a percentage, of the actual vapour pressure of the air to the saturation vapour pressure at the same temperature and pressure.","bag":{"kavram":["clausius","geri-besleme"],"soru":["S11","S13"],"hesap":["zorlama"]}},{"id":"saturation-vapour-pressure","tr":"Doymuş buhar basıncı","en":"saturation vapour pressure","kisa":"eₛ","tur":"olcu","es":["es","es(T)","doyma buhar basıncı","denge buhar basıncı","eₛ","eₛ(T)"],"tanim":["Düz su yüzeyi üstünde buharın sıvıyla dengede olduğu basınçtır; yalnız sıcaklığa bağlıdır.","Birimi hPa; 15 °C'de ≈ 17,0 hPa. Sıcaklık her 1 K arttığında ≈ %7 büyür (üstel artış).","Hava eₛ'den fazla buhar taşıyamaz, fazlası yoğuşur. Bağıl nem RH = e/eₛ ile bulunur; LCL ve su buharı geri beslemesinde eₛ(T) belirleyicidir."],"tanim_en":"Saturation vapour pressure is the pressure of water vapour in equilibrium with a plane surface of liquid water at a given temperature.","bag":{"kavram":["clausius"],"soru":["S4","S13","S15","S19","S33","S34"],"hesap":["clausius"]}},{"id":"vapour-pressure","tr":"Buhar basıncı","en":"vapour pressure","kisa":"e","tur":"olcu","es":["kısmi buhar basıncı","water vapour pressure","su buharı basıncı","vapor pressure","e"],"tanim":["Havadaki su buharının kısmi basıncıdır (e); toplam basıncın yalnız buhar payıdır.","Birimi hPa; bağıl nem RH = e/eₛ ile bulunur. Buhar miktarı korunurken basınç düşerse e de azalır.","Kitapta yükselen parselde çiy noktasının ≈ 1,8 K/km düşmesini ve LCL hesabını anlamak için kullanılır; ısınma sorusunda e ile eₛ(T) karşılaştırılır."],"tanim_en":"Vapour pressure is the partial pressure exerted by water vapour in a mixture of air and water vapour.","bag":{"kavram":["clausius","lcl"],"soru":["S13","S33"],"hesap":["clausius"]}},{"id":"magnus-formula","tr":"Magnus formülü","en":"Magnus formula","kisa":"eₛ(T)","tur":"yontem","es":["Magnus-Tetens bağıntısı","Magnus denklemi","Magnus equation","Magnus-Tetens formula"],"tanim":["Doymuş buhar basıncını sıcaklığın fonksiyonu olarak veren ampirik bağıntıdır: eₛ = 6,112 exp[17,67 T/(T + 243,5)] hPa.","Bağıntıda T Celsius cinsindendir; T'yi kelvin yazmak sık yapılan hatadır. Sonuç hPa çıkar.","Clausius–Clapeyron denkleminin integraline uydurulmuş bir yaklaşımdır; kitapta ısınmadan sonra eₛ'nin yüzde artışını hesaplamak için kullanılır."],"tanim_en":"The Magnus formula is an empirical expression that gives saturation vapour pressure over liquid water as an exponential function of temperature in degrees Celsius.","bag":{"kavram":["clausius"],"soru":["S13"],"hesap":["clausius"]}},{"id":"anomaly","tr":"Anomali","en":"anomaly","kisa":"","tur":"kavram","es":["normalden sapma","sapma","departure from the mean","deviation"],"tanim":["Bir değerin uzun dönem ortalamasından (iklimsel normalinden) farkıdır; işareti olan sayısal bir fark.","Birimi büyüklüğün kendi birimidir (°C, hPa); standartlaştırılırsa boyutsuz olur. Güney Salınımı indeksi (SOI) tipik −2…+2 aralığında standartlaştırılmış basınç farkı anomalisidir.","Kitapta ENSO fazını belirlemek için kullanılır; deniz yüzeyi sıcaklığı anomalisi pozitifse El Niño, negatifse La Niña. 'Anormal' sözcüğüyle karıştırılmamalı."],"tanim_en":"An anomaly is the departure of a value of a variable from its long-term average for the same location and time of year.","bag":{"kavram":["enso"],"soru":["S35"],"hesap":[]}},{"id":"bjerknes-feedback","tr":"Bjerknes geri beslemesi","en":"Bjerknes feedback","kisa":"","tur":"kavram","es":["Bjerknes döngüsü","Bjerknes eşleşmesi"],"tanim":["Tropikal Pasifik'te okyanus yüzey sıcaklığı gradyanı ile atmosferik ticaret rüzgârları arasındaki pozitif eşleşme mekanizmasıdır.","Doğu Pasifik ısındığında doğu–batı sıcaklık farkı azalır, ticaret rüzgârları zayıflar, soğuk su yükselimi durur ve doğu daha çok ısınır.","El Niño ve La Niña olaylarının gelişimini ve güçlenmesini yönlendiren temel dinamik süreçtir."],"tanim_en":"Bjerknes feedback is a positive coupled ocean-atmosphere feedback where weakened trade winds reduce equatorial upwelling and amplify eastern Pacific warming.","bag":{"kavram":["enso","geri-besleme"],"soru":[],"hesap":[]}},{"id":"el-nino","tr":"El Niño","en":"El Niño","kisa":"","tur":"kavram","es":["El Nino olayı","sıcak ENSO fazı","sıcak faz","El Niño olayı","ENSO sıcak evresi","warm phase of ENSO"],"tanim":["Doğu ve orta tropik Pasifik'te deniz yüzeyinin normalden sıcak olduğu ENSO evresidir; atmosferdeki eşi negatif Güney Salınımıdır.","NOAA ölçütü Niño 3.4 bölgesinde 3 aylık ortalama SST anomalisinin ≥ +0,5 °C olmasıdır (ONI). Tahiti − Darwin basınç farkı azalır, SOI negatif olur.","Kitapta mekanizma şöyle kurulur: ticaret rüzgârları zayıflar, sıcak su doğuya yayılır, yağış doğuya kayar; Peru'da sel, Endonezya ve Avustralya'da kuraklık görülür."],"tanim_en":"El Niño is the warm phase of the El Niño–Southern Oscillation, in which sea surface temperatures in the central and eastern tropical Pacific are above normal.","bag":{"kavram":["enso"],"soru":["S34","S35"],"hesap":[]}},{"id":"hadley-cell","tr":"Hadley hücresi","en":"Hadley cell","kisa":"","tur":"kavram","es":["Hadley dolaşımı","tropikal hücre","Hadley circulation","Hadley sirkülasyonu","tropikal dolaşım hücresi"],"tanim":["Ekvatorda ısınarak yükselen havanın üst troposferde kutuplara doğru akıp yaklaşık 30° enlemlerde alçalmasıyla oluşan meridyenel tropikal dolaşım hücresi.","Yüzey kolunda ekvatora yönelen ticaret rüzgârlarını, subtropikal kurak yüksek basınç kuşaklarını ve tropikal yağış bandını belirler.","Kitapta Pinatubo sonrası yüzey soğumasının tropikal yükselmeyi ve Asya musonu yağışını zayıflatması bu dolaşım üzerinden açıklanır."],"tanim_en":"The Hadley cell is a thermally driven tropical atmospheric circulation cell with rising air near the equator, poleward flow aloft, and descending air around 30 degrees latitude.","bag":{"kavram":["enso","volkan-aerosol"],"soru":["S33"],"hesap":[]}},{"id":"la-nina","tr":"La Niña","en":"La Niña","kisa":"","tur":"kavram","es":["La Nina olayı","soğuk ENSO fazı","soğuk faz","La Niña olayı","ENSO soğuk evresi","cold phase of ENSO"],"tanim":["Doğu ve orta tropik Pasifik'te deniz yüzeyinin normalden soğuk olduğu ENSO evresidir; El Niño'nun tersidir.","NOAA ölçütü Niño 3.4 bölgesinde 3 aylık SST anomalisinin ≤ −0,5 °C olmasıdır. Kitaba göre 2–7 yılda bir görülür ve 9–12 ay sürer.","Ticaret rüzgârları normalden güçlüdür, doğuda soğuk su yükselimi artar; Peru daha kurak, Endonezya daha yağışlı olur. El Niño'yu 'soğuma' sanmak tipik hatadır."],"tanim_en":"La Niña is the cold phase of the El Niño–Southern Oscillation, in which sea surface temperatures in the central and eastern tropical Pacific are below normal.","bag":{"kavram":["enso"],"soru":["S34","S35"],"hesap":[]}},{"id":"thermocline","tr":"Termoklin","en":"thermocline","kisa":"","tur":"kavram","es":["termoklin katmanı","sıcaklık sıçrama tabakası","termoklin tabakası","oceanic thermocline"],"tanim":["Okyanusta sıcaklığın derinlikle hızla düştüğü, sıcaklık gradyanının en büyük olduğu tabakadır.","Üstte sıcak karışık tabaka, altında soğuk derin su bulunur; derinliği metre cinsinden verilir ve bölgeye göre değişir.","Normalde doğu Pasifik'te sığdır, bu yüzden soğuk su yükselebilir. El Niño'da doğuda derinleşir; yükselen su artık sıcaktır ve besin getirmez."],"tanim_en":"The thermocline is the layer of a thermally stratified body of water across which the temperature gradient is at a maximum.","bag":{"kavram":["enso"],"soru":["S35"],"hesap":[]}},{"id":"trade-winds","tr":"Ticaret rüzgârları","en":"trade winds","kisa":"","tur":"kavram","es":["alize rüzgârları","alizeler","ticaret rüzgârı","trades","trade wind"],"tanim":["Subtropikal yüksek basınç merkezlerinden ekvatora doğru esen sürekli alçak seviye rüzgârlardır; Kuzey Yarıküre'de kuzeydoğulu, Güney'de güneydoğulu.","Tropik Pasifik'te doğudan batıya eser ve yüzeydeki sıcak suyu batıya iter. Türkçe meteorolojide 'alize' daha yaygındır; kitap 'ticaret rüzgârları' der.","ENSO'nun anahtarıdır; El Niño'da zayıflar (sıcak su doğuya yayılır), La Niña'da güçlenir (doğuda soğuk su yükselimi artar)."],"tanim_en":"Trade winds are persistent winds in the lower atmosphere that blow from the subtropical anticyclones towards the equatorial regions, from the north-east in the Northern Hemisphere and from the south-east in the Southern Hemisphere.","bag":{"kavram":["enso"],"soru":["S34","S35"],"hesap":[]}},{"id":"walker-circulation","tr":"Walker dolaşımı","en":"Walker circulation","kisa":"","tur":"kavram","es":["Walker hücresi","Walker dolaşım hücresi","Walker cell","doğu–batı Pasifik dolaşımı"],"tanim":["Ekvator Pasifik'inde ısıyla yönlenen doğu–batı dolaşım hücresi: sıcak batıda (Endonezya) hava yükselir, soğuk doğuda çöker.","Alt düzeyde ticaret rüzgârları doğudan batıya eser; yükselme bölgesinde bulut ve yağış oluşur. Hadley hücresi ise kuzey–güney yönlüdür.","Kitapta ENSO'nun atmosfer kolu olarak geçer; El Niño sırasında zayıflar, Tahiti–Darwin basınç farkı da bu değişimi izler."],"tanim_en":"The Walker circulation is a direct, thermally driven zonal circulation of the tropical Pacific in which air ascends over the warm western Pacific and sinks over the cold eastern Pacific.","bag":{"kavram":["enso"],"soru":[],"hesap":[]}},{"id":"southern-oscillation-index","tr":"Güney Salınımı indeksi","en":"Southern Oscillation Index","kisa":"SOI","tur":"kod","es":["Güney salınım indeksi","Tahiti–Darwin basınç farkı","SOI"],"tanim":["Tahiti ile Darwin arasındaki yüzey deniz seviyesi basıncı farkının standartlaştırılmış anomalisini temsil eden atmosferik salınım göstergesi.","Boyutsuz bir büyüklüktür; tipik olarak −2 ile +2 aralığında değerler alır.","Sürekli negatif değerler ticaret rüzgârlarının zayıflayarak El Niño evresine girildiğini, pozitif değerler ise La Niña evresini gösterir."],"tanim_en":"A standardized index based on the sea level pressure anomaly difference between Tahiti and Darwin used to monitor the atmospheric component of ENSO.","bag":{"kavram":["enso"],"soru":["S35"],"hesap":[]}},{"id":"sea-surface-temperature","tr":"Deniz yüzeyi sıcaklığı","en":"sea surface temperature","kisa":"SST","tur":"olcu","es":["deniz suyu sıcaklığı","deniz yüzey sıcaklığı","SST","deniz yüzey suyu sıcaklığı","DYS","okyanus yüzey sıcaklığı"],"tanim":["Okyanusun üst birkaç metresinin sıcaklığıdır (SST).","Birimi °C ya da K; uydu ve şamandıra ölçümleriyle izlenir. ENSO evresi SST anomalisinin işaretiyle belirlenir.","Buharlaşmayı ve atmosfere giden nem miktarını belirler; soğuk deniz daha az buharlaşır. Kitapta hem El Niño hem Pinatubo sonrası soğumada anahtar değişkendir."],"tanim_en":"Sea surface temperature is the temperature of the upper few metres of the ocean.","bag":{"kavram":["enso","volkan-aerosol"],"soru":["S33","S35"],"hesap":["sonum"]}},{"id":"upwelling","tr":"Soğuk su yükselimi","en":"upwelling","kisa":"","tur":"surec","es":["derin su yükselimi","kıyı yükselimi","yükselim","su yükselimi","coastal upwelling"],"tanim":["Derindeki soğuk ve besin tuzlarınca zengin suyun yüzeye çıkmasıdır.","Peru kıyısında ticaret rüzgârlarının yüzey suyunu açığa itmesiyle olur; yüzeyi soğutur ve plankton ile balık üretimini besler.","El Niño'da rüzgârlar zayıflar, termoklin derinleşir ve sıcak yüzey suyu yükselimi bastırır; balık azalır. La Niña'da yükselim artar."],"tanim_en":"Upwelling is the vertical movement of cold, nutrient-rich water from depth towards the ocean surface.","bag":{"kavram":["enso"],"soru":["S34","S35"],"hesap":[]}},{"id":"photoionization","tr":"Fotoiyonlaşma","en":"photoionization","kisa":"","tur":"kavram","es":["foto-iyonlaşma","photoionisation","ışıkla iyonlaşma"],"tanim":["Bir fotonun molekülden ya da atomdan elektron koparması: AB + hν → AB⁺ + e⁻.","Çok kısa dalga boyu gerekir (≲ 100 nm; uç morötesi, X ışını); bu yüzden yalnız yüksek atmosferde olur.","Kitapta iyonosferi (≈ 60 km üstü) oluşturan süreçtir; ozon kimyasının parçası değildir."],"tanim_en":"Photoionization is the process in which a photon ejects an electron from an atom or molecule, leaving a positively charged ion.","bag":{"kavram":["fotoliz"],"soru":[],"hesap":[]}},{"id":"absorption-cross-section","tr":"Soğurma kesiti","en":"absorption cross section","kisa":"σₐ","tur":"olcu","es":["soğurma tesir kesiti","absorpsiyon kesiti","σ (fotoliz)"],"tanim":["Bir molekülün ya da parçacığın belirli dalga boyunda fotonu yakalama 'alanı'; simgesi σₐ (fotolizde σ), birimi cm².","Beer–Lambert yasasında τ = (σₛ + σₐ) n L ile optik derinliğe girer; saçılma kesiti σₛ ile toplanıp yok olma katsayısı K = (σₛ + σₐ) n verir.","Fotolizde σ(λ) J integralinde yer alır; aerosolde σₐ büyükse (is gibi koyu parçacık) tek saçılma albedosu ω küçülür. Stefan–Boltzmann sabiti σ ile aynı harftir, birime bakılmalıdır."],"tanim_en":"The absorption cross section is the effective area, in cm², of a molecule or particle for absorbing photons of a given wavelength.","bag":{"kavram":["fotoliz","beer-lambert","aerosol-dogrudan"],"soru":["S24","S25","S40"],"hesap":["beer-kesit"]}},{"id":"actinic-flux","tr":"Aktinik akı","en":"actinic flux","kisa":"F(λ)","tur":"olcu","es":["aktinik ışınım akısı","küresel aktinik akı","actinic radiation flux","spherical irradiance"],"tanim":["Bir noktaya her yönden gelen fotonların toplamı; birimi foton cm⁻² s⁻¹ nm⁻¹.","Molekül ışığı yönden bağımsız soğurduğu için fotolizde yatay yüzeye gelen ışınım (irradiance) değil aktinik akı kullanılır.","Kitapta F(λ) simgesiyle J integralinde σ(λ) ve φ(λ) ile çarpılır; güneş yüksekken büyük, gece sıfırdır."],"tanim_en":"Actinic flux is the total number of photons per unit area, time and wavelength arriving at a point from all directions, which is the quantity that drives photolysis.","bag":{"kavram":["fotoliz"],"soru":[],"hesap":["fotoliz"]}},{"id":"bond-dissociation-energy","tr":"Bağ ayrışma enerjisi","en":"bond dissociation energy","kisa":"D","tur":"olcu","es":["bağ entalpisi","bağ koparma enerjisi","bond energy","bağ enerjisi"],"tanim":["Bir kimyasal bağı koparmak için gereken enerji; birimi kJ/mol.","Foton enerjisiyle karşılaştırılarak eşik dalga boyu bulunur: λ_max = hcN_A/D. O₂ için 498 kJ/mol → 240 nm; O₃ için 105 kJ/mol → 1140 nm.","Hangi molekülün hangi dalga boyunda fotolize uğrayacağını belirler; O₂ yalnız çok kısa dalgada, O₃ görünür dalgaya yakın bölgede bölünür."],"tanim_en":"Bond dissociation energy is the energy required to break a specified chemical bond, usually expressed in kJ/mol.","bag":{"kavram":["fotoliz"],"soru":[],"hesap":["fotoliz"]}},{"id":"photolysis-frequency","tr":"Fotoliz frekansı","en":"photolysis frequency","kisa":"J","tur":"olcu","es":["fotoliz hızı","fotoliz katsayısı","J sembolü","fotoliz hız katsayısı","J katsayısı","J3"],"tanim":["Birim zamanda foton soğurarak bölünen molekül kesri; simgesi J, birimi s⁻¹ (birinci mertebe hız sabiti).","J = ∫ σ(λ) φ(λ) F(λ) dλ; hız = J[AB], ömür τ = 1/J. Gece sıfırdır.","NO₂ için öğlen J ≈ 8 × 10⁻³ s⁻¹ olduğundan τ = 125 s ≈ 2 dk; kitapta Chapman ve fotodurağan denge hesaplarında kullanılır."],"tanim_en":"The photolysis frequency is the first-order rate coefficient (in s⁻¹) for the photodissociation of a molecule, equal to the fraction of molecules photolysed per unit time.","bag":{"kavram":["fotoliz","chapman","leighton"],"soru":["S40","S41","S44"],"hesap":["fotoliz","chapman-o","leighton"]}},{"id":"quantum-yield","tr":"Kuantum verimi","en":"quantum yield","kisa":"φ(λ)","tur":"olcu","es":["bölünme verimi","kuantum etkinliği","kuantum randımanı","quantum efficiency","φ"],"tanim":["Soğurulan bir fotonun belirli bir ürünü (ör. bölünmeyi) verme olasılığı; simgesi φ, değeri 0–1 arasındadır.","Birimsizdir ve dalga boyuna bağlıdır, φ(λ). φ < 1 ise soğurulan fotonların bir kısmı ısıya ya da ışımaya gider.","Kitapta J integralinde σ(λ) ve aktinik akı F(λ) ile çarpılan üçüncü çarpandır."],"tanim_en":"Quantum yield is the number of molecules undergoing a given photochemical event per photon absorbed, a dimensionless quantity between 0 and 1.","bag":{"kavram":["fotoliz"],"soru":[],"hesap":["fotoliz"]}},{"id":"solar-zenith-angle","tr":"Güneş zenit açısı","en":"solar zenith angle","kisa":"θ","tur":"olcu","es":["zenit açısı","güneş başucu açısı","başucu","Zenit","zenith","zenith angle"],"tanim":["Güneşin tepe (zenit) doğrultusundan açısı; 0° tam tepede demektir. Güneş yükseklik açısı 90° − θ'dır.","Işığın atmosferdeki yolu ≈ 1/cos θ kat uzar (hava kütlesi): 60° → 2 kat, 80° → 5,8 kat. θ ≳ 75°'te Dünya'nın eğriliği önem kazanır.","θ büyüdükçe geçen ışık, J ve yüzeyin ısınması azalır; kitapta Beer–Lambert eğik ışın hesabında kullanılır."],"tanim_en":"The solar zenith angle is the angle between the local vertical (zenith) and the direction to the centre of the Sun.","bag":{"kavram":["fotoliz","beer-lambert"],"soru":["S24"],"hesap":["egik-isin"]}},{"id":"threshold-wavelength","tr":"Eşik dalga boyu","en":"threshold wavelength","kisa":"λ_max","tur":"olcu","es":["eşik dalga boyu λ_max","kesim dalga boyu","photodissociation threshold"],"tanim":["Bir bağı koparabilen en uzun dalga boyu; daha uzun dalganın fotonu (düşük enerji) bağı koparamaz.","λ_max = hcN_A/D; birimi nm. O₂ için ≈ 240 nm, O₃ için ≈ 1140 nm.","Kitapta hangi ışığın hangi molekülü böleceğini gösterir; O₂ yalnız morötesinde, O₃ görünür ve yakın kızılötesinde bölünür."],"tanim_en":"The threshold wavelength is the longest wavelength of radiation whose photons carry enough energy to break a given chemical bond.","bag":{"kavram":["fotoliz"],"soru":[],"hesap":["fotoliz"]}},{"id":"cloud-feedback","tr":"Bulut geri beslemesi","en":"cloud feedback","kisa":"","tur":"kavram","es":["bulut geri bildirimi","cloud radiative feedback"],"tanim":["Isınmayla bulut örtüsü, yüksekliği ve kalınlığının değişmesi ve bunun ışınım dengesini yeniden etkilemesi; ısınmayı artırırsa pozitif, azaltırsa negatiftir.","Bulutun net ışınım etkisi ΔF_net (W/m²) ile gösterilir; + ısıtır, − soğutur. Yüksek bulut ısıtma, alçak bulut soğutma eğiliminde.","İşareti ve büyüklüğü belirsizdir; iklim tahmininin en büyük belirsizlik kaynağıdır (IPCC AR6: büyük olasılıkla küçük pozitif)."],"tanim_en":"Cloud feedback is the change in the climate system's radiative balance caused by cloud changes that are themselves a response to surface warming.","bag":{"kavram":["geri-besleme","bulut-isinim"],"soru":["S9","S12"],"hesap":[]}},{"id":"negative-feedback","tr":"Negatif geri besleme","en":"negative feedback","kisa":"(−)","tur":"kavram","es":["olumsuz geri besleme","dengeleyici geri besleme","damping feedback"],"tanim":["İlk değişikliği küçülten ve sistemi dengeye çeken geri besleme; ısınma sonucunda ortaya çıkan bir süreç ısınmayı frenler.","İklim geri besleme çarpanı f negatif olduğunda toplam ısınma ΔT, geri beslemesiz ısınma ΔT₀'dan küçük kalır.","Temel örnek Planck tepkisidir; sıcak yüzey σT⁴ ile daha çok yayar. Kitapta alçak bulutlar (stratus) da güneşi yansıtıp ısınmayı frenleyen bir negatif geri besleme olarak ele alınır."],"tanim_en":"A negative feedback is a process in which an initial change triggers a response that reduces that change and stabilizes the system.","bag":{"kavram":["geri-besleme","bulut-isinim"],"soru":["S8","S10","S12","S13"],"hesap":[]}},{"id":"positive-feedback","tr":"Pozitif geri besleme","en":"positive feedback","kisa":"(+)","tur":"kavram","es":["olumlu geri besleme","büyütücü geri besleme","amplifying feedback"],"tanim":["İlk değişikliği büyüten geri besleme; bir zorlamanın yarattığı ısınmayı başka bir değişken aracılığıyla daha da artırır.","İklim geri besleme çarpanı f pozitif olduğunda ΔT = ΔT₀ / (1 − f) ifadesi ΔT₀'dan büyük çıkar; f → 1 olursa ısınma sınırsız büyür.","«Pozitif» iyi anlamına gelmez; su buharı ve buz–albedo geri beslemeleri ısınmayı artıran pozitif geri beslemelerdir."],"tanim_en":"A positive feedback is a process in which an initial change triggers a response that amplifies that change and moves the system further from its starting state.","bag":{"kavram":["geri-besleme"],"soru":["S8","S9","S10","S12","S13"],"hesap":[]}},{"id":"water-vapour-feedback","tr":"Su buharı geri beslemesi","en":"water vapour feedback","kisa":"","tur":"kavram","es":["su buharı geri bildirimi","water vapor feedback","su buharı geribeslemesi"],"tanim":["Isınmanın atmosferdeki su buharını artırması ve artan buharın daha çok kızılötesi tutarak ısınmayı güçlendirmesi.","Doymuş buhar basıncı Clausius–Clapeyron ilişkisine göre her 1 K'de yaklaşık %7 artar; bağıl nem kabaca sabit kalırsa buhar aynı oranda artar.","En güçlü pozitif iklim geri beslemesidir. Su buharı doğrudan insan salımıyla birikmediği için zorlama değil, geri besleme sayılır."],"tanim_en":"Water vapour feedback is the amplification of warming that occurs because a warmer atmosphere holds more water vapour, a greenhouse gas that absorbs additional infrared radiation.","bag":{"kavram":["geri-besleme","clausius"],"soru":["S9","S13"],"hesap":[]}},{"id":"sym-feedback-gain","tr":"Geri besleme çarpanı","en":"feedback factor","kisa":"f","tur":"olcu","es":["geri besleme kazancı","feedback gain","f çarpanı"],"tanim":["f: iklim sisteminin toplam geri besleme çarpanı (faktörü); boyutsuz bir sayıdır ve su buharı, buz–albedo ile bulut katkılarının toplamıdır.","λ = λ₀ / (1 − f) ilişkisinden f = 1 − λ₀/λ bulunur; ΔT/ΔT₀ = 1/(1 − f) oranı ise geri besleme kazancıdır. Kitaptaki değerler λ₀ = 0,27 ve λ = 0,8 için f ≈ 0,67 çıkar.","f → 1 olursa ısınma sınırsız büyür; f negatifse geri besleme ısınmayı küçültür."],"tanim_en":"The feedback factor f is the dimensionless net factor of climate feedbacks, defined by ΔT = ΔT₀ / (1 − f), so that f approaching 1 implies runaway warming.","bag":{"kavram":["geri-besleme"],"soru":["S9"],"hesap":["zorlama"]}},{"id":"ice-albedo-feedback","tr":"Buz–albedo geri beslemesi","en":"ice–albedo feedback","kisa":"","tur":"surec","es":["kar-buz albedo geri beslemesi","albedo geri beslemesi","kar/buz–albedo geri beslemesi","snow-ice albedo feedback"],"tanim":["Isınmanın kar ve buzu eritip yüzeyi koyulaştırması, albedoyu düşürmesi ve daha çok güneş ışınımının soğurulmasıyla ısınmayı artırması.","Zincir şöyledir: ısınma → kar ve buz erir → albedo azalır → soğurulan güneş ışınımı artar → daha çok ısınma.","Pozitif bir geri beslemedir; kar ve buzun çok olduğu kutup bölgelerinde özellikle güçlüdür."],"tanim_en":"Ice–albedo feedback is the amplification of warming caused by melting snow and ice, which lowers the surface albedo so that more solar radiation is absorbed.","bag":{"kavram":["geri-besleme"],"soru":[],"hesap":[]}},{"id":"planck-feedback","tr":"Planck geri beslemesi","en":"Planck feedback","kisa":"","tur":"surec","es":["Planck soğuma geri beslemesi","Planck response","Planck tepkisi"],"tanim":["Isınan yüzeyin ve atmosferin Stefan–Boltzmann yasasına göre σT⁴ ile daha çok ışınım yayması; ısınmayı sınırlayan temel negatif geri besleme.","Geri beslemesiz duyarlılık λ₀ = 1/(4σTₑ³) ≈ 0,27 K/(W m⁻²) buradan gelir; Tₑ ≈ 255 K alınır.","Kitapta öteki geri beslemeler Planck tepkisinin üstüne eklenir; tek başına CO₂ ikiye katlanınca yaklaşık 1 K ısınma verir."],"tanim_en":"The Planck feedback is the increase in outgoing longwave emission, proportional to T⁴, that accompanies surface and atmospheric warming and thereby acts as the fundamental stabilizing response of the climate system.","bag":{"kavram":["geri-besleme","zorlama"],"soru":["S9"],"hesap":[]}},{"id":"unit-micrometer","tr":"Mikrometre","en":"micrometre","kisa":"µm","tur":"birim","es":["mikron","micron","micrometer","Micrometer","µm"],"tanim":["Uzunluk birimi; 1 µm = 10⁻⁶ m = 10⁻³ mm.","Kızılötesi dalga boylarını (Dünya ışınımı ≈ 10 µm) ve aerosol parçacık çaplarını (PM2.5 ve PM10) ifade etmek için kullanılır.","Kitapta soğurma bantlarını (15 µm CO₂), aerosol boyut modlarını ve PM sınırlarını (2,5 µm, 10 µm) göstermek için kullanılır."],"tanim_en":"The micrometre (µm) is a unit of length equal to one millionth of a metre, commonly used for infrared wavelengths and aerosol particle diameters.","bag":{"kavram":["ir-aktif","boyut-modlari","pm"],"soru":["S5","S14","S15","S16","S17","S19"],"hesap":[]}},{"id":"absorption-band","tr":"Soğurma bandı","en":"absorption band","kisa":"","tur":"kavram","es":["soğurma şeridi"],"tanim":["Bir molekülün ışınımı güçlü soğurduğu dalga boyu aralığı; moleküllerin titreşim ve/veya dönme enerji düzeyleri artar.","Kitapta bant şiddeti I, dipol momentinin titreşim koordinatına göre değişiminin karesiyle orantılıdır (N₂ için 0).","CO₂'nin 15 µm bandının merkezi doymuştur; ek CO₂ bant kanatlarında soğurur, bu yüzden zorlama logaritmik artar."],"tanim_en":"An absorption band is a range of wavelengths over which molecules strongly absorb radiation, raising their vibrational and/or rotational energy states.","bag":{"kavram":["ir-aktif"],"soru":["S5"],"hesap":[]}},{"id":"asymmetric-stretch","tr":"Asimetrik gerilme","en":"asymmetric stretch","kisa":"ν₃","tur":"kavram","es":["asimetrik gerilme kipi","asimetrik esneme","antisymmetric stretching","asymmetric stretching","ν₃"],"tanim":["Üç atomlu bir molekülde bir bağ uzarken öteki kısalan titreşim kipi; sembolü ν₃.","CO₂'de iki O aynı yöne, C ters yöne kayar; dipol momenti salındığı için kip IR aktiftir ve 4,3 µm'de güçlü soğurma verir.","Kitapta CO₂'nin üç titreşiminden biridir; simetrik gerilme IR aktif değildir, bükülme (15 µm) ise aktiftir."],"tanim_en":"The asymmetric stretch is a vibrational mode of a triatomic molecule in which one bond lengthens while the other shortens, producing an oscillating dipole in CO₂ that absorbs at 4.3 µm.","bag":{"kavram":["ir-aktif"],"soru":["S5"],"hesap":[]}},{"id":"atmospheric-window","tr":"Atmosfer penceresi","en":"atmospheric window","kisa":"8–12 µm","tur":"kavram","es":["atmosferik pencere","pencere bölgesi","IR penceresi","infrared window"],"tanim":["Atmosferin yeryüzünden yayılan uzun dalga ışınımı çok az soğurduğu spektral bölge.","Kitapta 8–12 µm aralığıdır; H₂O ve CO₂ burada zayıf soğurur, yüzey IR'si doğrudan uzaya kaçabilir.","Bu aralıkta soğuran O₃ (9,6 µm) ve CFC'ler molekül başına çok etkili sera gazlarıdır."],"tanim_en":"An atmospheric window is a spectral region in which the atmosphere absorbs very little terrestrial radiation, allowing it to escape to space.","bag":{"kavram":["ir-aktif","tek-katman"],"soru":[],"hesap":[]}},{"id":"molecular-nitrogen","tr":"Azot gazı","en":"molecular nitrogen","kisa":"N₂","tur":"kavram","es":["moleküler azot","diatomik azot","dinitrogen","nitrogen gas","N2","N₂"],"tanim":["Azot atomlarının üçlü bağla bağlandığı simetrik iki atomlu moleküldür (N₂); kuru havanın hacimce yaklaşık %78'ini oluşturur.","Simetrik olduğu için titreşirken dipol momenti hep sıfır kalır (∂μ/∂Q = 0); bu yüzden kızılötesi (IR) fotonu soğurmaz.","Sera etkisine katkı vermez; kimyada ise üç cisimli tepkimelerde fazla enerjiyi alan çarpışma ortağı M olarak görev yapar."],"tanim_en":"Molecular nitrogen (N₂) is the symmetric diatomic molecule that makes up about 78 % of dry air by volume and is not infrared-active.","bag":{"kavram":["ir-aktif","asit-yagmuru"],"soru":["S5","S22"],"hesap":["twomey"]}},{"id":"molecular-oxygen","tr":"Oksijen gazı","en":"molecular oxygen","kisa":"O₂","tur":"kavram","es":["moleküler oksijen","diatomik oksijen","dioxygen","oxygen gas","O2","Moleküler oksijen"],"tanim":["İki oksijen atomundan oluşan simetrik iki atomlu moleküldür (O₂); kuru havanın hacimce yaklaşık %21'idir.","Simetrik olduğundan IR aktif değildir; ama 240 nm'den kısa dalga boylu morötesi fotonla bölünür (O₂ + hν → 2 O).","Oluşan O atomu O₂ ile ve üçüncü cisimle birleşerek ozonu yapar; ozonun katalitik ve titrasyon tepkimelerinde de O₂ ürün olarak çıkar."],"tanim_en":"Molecular oxygen (O₂) is the diatomic molecule that makes up about 21 % of dry air, is infrared-inactive, and is photolysed by short-wave ultraviolet radiation to start ozone formation.","bag":{"kavram":["ir-aktif","asit-yagmuru","volkan-aerosol"],"soru":["S5","S32","S40","S41","S42","S43"],"hesap":["chapman-o"]}},{"id":"permanent-dipole","tr":"Kalıcı dipol","en":"permanent dipole","kisa":"μ₀","tur":"kavram","es":["kalıcı dipol momenti","permanent dipole moment","μ₀"],"tanim":["Bir molekülün denge geometrisinde var olan, titreşimden bağımsız sabit dipol momentidir (μ₀).","Sabit bir sayı olduğundan farklı titreşim durumları arasında geçiş vermez: ⟨v'|μ₀|v⟩ = μ₀⟨v'|v⟩ = 0 (v' ≠ v).","IR soğurma için ölçüt kalıcı dipol değil, titreşimle dipolün değişmesidir; CO₂'nin kalıcı dipolü yoktur ama IR aktiftir."],"tanim_en":"A permanent dipole is the fixed electric dipole moment a molecule has at its equilibrium geometry, which by itself cannot cause infrared absorption because it does not change during vibration.","bag":{"kavram":["ir-aktif"],"soru":["S5"],"hesap":[]}},{"id":"photon","tr":"Foton","en":"photon","kisa":"hν","tur":"kavram","es":["ışık kuantumu","light quantum","hν"],"tanim":["Elektromanyetik ışınımın enerji paketidir (kuantumu); enerjisi E = hν = hc/λ ile verilir.","Kısa dalga boylu foton yüksek enerjilidir; fotolizde tek bir fotonun enerjisi bağ enerjisini aşmalıdır, düşük enerjili fotonlar toplanmaz.","Kitapta IR fotonu titreşim geçişini, UV ve görünür foton ise NO₂, O₂, O₃ gibi moleküllerin fotolizini (hν) başlatır."],"tanim_en":"A photon is the quantum of electromagnetic radiation, carrying energy E = hν = hc/λ, which can be absorbed by a molecule to excite it or to break a bond.","bag":{"kavram":["ir-aktif","psc","fotoliz"],"soru":["S5","S21","S32","S40","S41","S42"],"hesap":["fotoliz","chapman-o","leighton"]}},{"id":"symmetric-stretch","tr":"Simetrik gerilme","en":"symmetric stretch","kisa":"ν₁","tur":"kavram","es":["simetrik gerilme kipi","simetrik esneme","symmetric stretching","ν₁"],"tanim":["İki bağın aynı anda uzayıp kısaldığı titreşim kipidir (ν₁).","CO₂'de iki O eşit uzaklaştığı için toplam dipol her an sıfır kalır; bu kip IR aktif değildir.","Bu nedenle CO₂'nin 4,3 µm ve 15 µm bantlarına katkı vermez; yalnız asimetrik gerilme ve bükülme soğurur."],"tanim_en":"The symmetric stretch is the vibrational mode in which bonds lengthen and shorten in phase, so in CO₂ the dipole moment stays zero and the mode is infrared-inactive.","bag":{"kavram":["ir-aktif"],"soru":["S5"],"hesap":[]}},{"id":"vibrational-mode","tr":"Titreşim kipi","en":"vibrational mode","kisa":"","tur":"kavram","es":["titreşim modu","molekül titreşimi","titreşim","moleküler titreşim","molecular vibration"],"tanim":["Molekülün atomlarının belirli bir düzenle birlikte salındığı titreşim biçimidir (kip).","CO₂'nin üç kipi vardır: simetrik gerilme, asimetrik gerilme ve iki katlı bükülme; her kipin titreşim koordinatı Q ile tanımlanır.","Bir kip yalnız titreşim sırasında elektrik dipol momenti değişiyorsa IR fotonu soğurur (seçim kuralı); ortak ölçüt budur."],"tanim_en":"A vibrational mode is a characteristic pattern of coordinated atomic motion in a molecule, and it absorbs infrared radiation only if the motion changes the molecule's electric dipole moment.","bag":{"kavram":["ir-aktif"],"soru":["S5"],"hesap":[]}},{"id":"dipole-moment","tr":"Dipol moment","en":"dipole moment","kisa":"μ","tur":"olcu","es":["elektrik dipol momenti","dipol momenti","electric dipole moment","μ"],"tanim":["Molekülün yük dağılımının asimetrisini gösteren ölçüdür (μ); birimi C·m ya da debye (D).","Kitapta tipik değerler H₂O için 1,85 D, CO₂ için 0'dır.","IR soğurma için μ'nun kendisi değil, titreşimle değişimi (∂μ/∂Q ≠ 0) belirleyicidir."],"tanim_en":"The electric dipole moment is a measure of the asymmetry of a molecule's charge distribution, and its change during vibration determines whether the molecule absorbs infrared radiation.","bag":{"kavram":["ir-aktif"],"soru":["S5"],"hesap":["stokes"]}},{"id":"wavelength","tr":"Dalga boyu","en":"wavelength","kisa":"λ","tur":"olcu","es":["ışık dalga boyu","λ"],"tanim":["Dalganın ardışık iki tepesi arasındaki uzaklıktır (λ; µm, nm).","Frekansla ters orantılıdır (λν = c); foton enerjisi E = hc/λ olduğundan kısa dalga boyu yüksek enerji demektir.","Sıcak cisim kısa, soğuk cisim uzun dalga boyunda yayar: Güneş ≈ 0,5 µm'de, Dünya ≈ 10 µm'de en güçlüdür. Kitapta λ aynı zamanda iklim duyarlılığı parametresi (≈ 0,8 K/(W m⁻²)) için de kullanılır."],"tanim_en":"Wavelength is the distance between successive crests of a wave, inversely proportional to frequency, so that shorter wavelength corresponds to higher photon energy.","bag":{"kavram":["ir-aktif","koschmieder","beer-lambert"],"soru":["S15","S23","S24"],"hesap":["zorlama","fotoliz"]}},{"id":"bending-mode","tr":"Bükülme kipi","en":"bending mode","kisa":"ν₂","tur":"surec","es":["bükülme","açısal titreşim","bükülme titreşimi","bükülme modu","bending vibration"],"tanim":["Bağ açısının değiştiği titreşim kipidir (ν₂).","CO₂'de bükülme sırasında dipol oluşur ve kip IR aktiftir; 15 µm bandını verir.","15 µm Dünya ışımasının tepesine (≈ 10 µm) yakın olduğundan sera etkisinde en önemli kip budur."],"tanim_en":"The bending mode is the vibration in which the bond angle oscillates, and in CO₂ it is infrared-active and produces the strong 15 µm absorption band.","bag":{"kavram":["ir-aktif"],"soru":["S5"],"hesap":[]}},{"id":"selection-rule","tr":"Seçim kuralı","en":"selection rule","kisa":"","tur":"yontem","es":["seçilim kuralı","kuantum seçim kuralı","selection rules"],"tanim":["Bir geçişin hangi koşullarda olabileceğini belirleyen kuantum kuralıdır.","IR soğurma için kural şudur: foton enerjisi bir titreşim ya da dönme geçişine eşit olmalı ve o titreşim elektrik dipol momentini değiştirmelidir.","Harmonik titreşici için ⟨v'|Q|v⟩ yalnız v' = v ± 1 için sıfırdan farklıdır; bu yüzden şiddet (∂μ/∂Q)² ile orantılı olur."],"tanim_en":"A selection rule is a quantum-mechanical condition stating which transitions are allowed, and for infrared absorption it requires the vibration to change the molecule's electric dipole moment.","bag":{"kavram":["ir-aktif"],"soru":["S5"],"hesap":[]}},{"id":"wiens-displacement-law","tr":"Wien yasası","en":"Wien's displacement law","kisa":"λ_max","tur":"yontem","es":["Wien kayma yasası","Wien yer değiştirme yasası","Wien displacement law","tepe dalga boyu"],"tanim":["Siyah cisim gibi ışıyan bir cismin en şiddetli yaydığı dalga boyu, mutlak sıcaklıkla ters orantılıdır.","λ_max = b/T; b ≈ 2898 µm·K, T kelvin cinsinden, λ_max µm cinsinden. Sıcak cisim kısa, soğuk cisim uzun dalga boyunda tepe verir.","Güneşin kısa dalga (tepe ≈ 0,5 µm), Dünyanın uzun dalga (tepe ≈ 10 µm) ışımasını açıklar; böylece sera gazı molekülleri yalnız Dünya ışınımını tutar."],"tanim_en":"Wien's displacement law states that the wavelength of peak blackbody emission is inversely proportional to the absolute temperature of the emitter.","bag":{"kavram":["ir-aktif","stefan-boltzmann"],"soru":[],"hesap":["etkin-sicaklik"]}},{"id":"unit-watt-per-square-meter","tr":"Watt bölü metrekare","en":"watt per square metre","kisa":"W/m²","tur":"birim","es":["W m⁻²","W/m2","watt per square meter"],"tanim":["Birim yüzeyden birim zamanda geçen enerjiyi (güç akısı) ölçen SI türetilmiş birimidir: 1 W/m² = 1 J s⁻¹ m⁻².","Işınım akısı, ışınımsal zorlama ve güneş sabiti bu birimle verilir; kitapta S₀ = 1361 W/m², σ = 5,67 × 10⁻⁸ W m⁻² K⁻⁴ içinde geçer.","Atmosfer enerji bütçesini (soğurulan güneş, giden uzun dalga, sera etkisi ≈ 150 W/m²) karşılaştırmak için ortak ölçü sağlar."],"tanim_en":"The watt per square metre is the SI unit of power flux, equal to one joule of energy passing through one square metre of surface each second.","bag":{"kavram":["isinim-dengesi","zorlama","stefan-boltzmann"],"soru":["S6","S8","S9","S10"],"hesap":[]}},{"id":"brightness-temperature","tr":"Parlaklık sıcaklığı","en":"brightness temperature","kisa":"","tur":"kavram","es":["radiance temperature","equivalent blackbody temperature","eşdeğer siyah cisim sıcaklığı"],"tanim":["Uydunun belirli bir dalga boyunda ölçtüğü ışımayı veren siyah cismin sıcaklığıdır.","Ölçülen ışıma Planck yasasına ters uygulanarak kelvin cinsinden hesaplanır; yüzeyin yayıcılığı 1 değilse gerçek sıcaklıktan düşük çıkar.","Kızılötesi uydu görüntülerinde bulut tepesi ve yüzey sıcaklığını kestirmek için kullanılır; etkin sıcaklıktan (bütün tayf, gezegen ortalaması) farklıdır."],"tanim_en":"Brightness temperature is the temperature of a blackbody that would emit the same radiance as the observed source at a given wavelength.","bag":{"kavram":["isinim-dengesi"],"soru":[],"hesap":[]}},{"id":"insolation","tr":"Güneşlenme","en":"insolation","kisa":"","tur":"kavram","es":["gelen güneş ışınımı","incoming solar radiation","güneş ışınımı girdisi"],"tanim":["Gelen güneş ışınımı; birim yatay yüzeye ulaşan güneş akısıdır.","W/m² cinsinden verilir; küresel ve yıllık ortalama S₀/4 ≈ 340 W/m² olur (1361 / 4).","Dünya enerji bütçesinin girdisidir; (1 − A) ile çarpılınca soğurulan kısmı bulunur. 'Insulation' (yalıtım) ile karıştırılmamalıdır."],"tanim_en":"Insolation is the rate at which solar radiation arrives at a unit horizontal surface at a given location or on average over the globe.","bag":{"kavram":["isinim-dengesi"],"soru":[],"hesap":[]}},{"id":"shortwave-radiation","tr":"Kısa dalga ışınım","en":"shortwave radiation","kisa":"SW","tur":"kavram","es":["güneş ışınımı","kısa dalga","kısa dalga ışınımı","solar radiation","SW"],"tanim":["Güneşten gelen ve yaklaşık 0,2–4 µm aralığındaki ışınımdır: morötesi, görünür ve yakın kızılötesi.","Albedo ve aerosol saçılması bu ışınımı yansıtır ya da geri saçar; yer ve atmosfer onun geri kalanını soğurur.","Kitapta bulutların kısa dalga etkisi ΔF_SW = −S̄ ΔA ile hesaplanır; S̄ = S₀/4 ≈ 340 W/m². Sera gazı molekülleri bu ışınımı büyük ölçüde geçirir."],"tanim_en":"Shortwave radiation is the radiant energy from the Sun, mostly at wavelengths of about 0.2 to 4 µm, covering ultraviolet, visible and near-infrared light.","bag":{"kavram":["isinim-dengesi"],"soru":["S8","S10","S12","S24","S30","S33"],"hesap":[]}},{"id":"top-of-the-atmosphere","tr":"Atmosferin üst sınırı","en":"top of the atmosphere","kisa":"","tur":"kavram","es":["TOA","atmosferin tepesi","üst sınır","atmosfer üst sınırı"],"tanim":["Işınım bütçesinin hesaplandığı hayali üst sınırdır (TOA); atmosferin uzayla buluştuğu yüzey olarak alınır.","Uydular burada gelen güneş akısını ve giden uzun dalga akısını (OLR) ölçer; uzun dönemde net akı ≈ 0 olmalıdır.","Enerji dengesi ve ışınımsal zorlama bu düzeyde tanımlanır; tropopoz (troposferin tepesi) ile karıştırılmamalıdır."],"tanim_en":"The top of the atmosphere is the upper boundary at which the radiation budget is evaluated, where incoming solar radiation and outgoing longwave radiation are measured by satellites.","bag":{"kavram":["isinim-dengesi"],"soru":[],"hesap":[]}},{"id":"outgoing-longwave-radiation","tr":"Uzaya giden uzun dalga ışınım","en":"outgoing longwave radiation","kisa":"OLR","tur":"olcu","es":["giden uzun dalga akı","uzaya giden IR","uzun dalga ışıma","giden uzun dalga akısı","uzaya giden uzun dalga boylu ışınım","uzaya giden uzun dalga ışınımı"],"tanim":["Atmosferin üst sınırından uzaya çıkan uzun dalga (kızılötesi) ışınım akısıdır.","W/m² cinsindendir; dengede soğurulan güneşe eşittir: OLR = S₀(1−A)/4 ≈ 238–240 W/m² ve OLR = σTₑ⁴.","Yüzeyin yaydığı ışınım (σT_s⁴ ≈ 390 W/m²) değildir; aradaki fark G = σT_s⁴ − OLR ≈ 150 W/m² sera etkisinin akı ölçüsüdür."],"tanim_en":"Outgoing longwave radiation is the flux of thermal infrared radiation leaving the top of the atmosphere and escaping to space.","bag":{"kavram":["isinim-dengesi","sera-etkisi"],"soru":["S6","S10"],"hesap":["etkin-sicaklik"]}},{"id":"solar-constant","tr":"Güneş sabiti","en":"solar constant","kisa":"S₀","tur":"olcu","es":["S0","gelen güneş akısı","toplam güneş ışınımı","total solar irradiance","TSI","güneş akısı"],"tanim":["Ortalama Güneş–Dünya uzaklığında, güneş ışınlarına dik birim alana atmosferin dışında gelen ışınım akısıdır.","Dünya için S₀ ≈ 1361 W/m² (Venüs için ≈ 2600); akı 1/d² ile azalır. Güneş etkinliğiyle binde bir düzeyinde değiştiği için 'sabit' tam sabit değildir.","Kitapta Tₑ = [S₀(1−A)/(4σ)]^¼ ile etkin sıcaklığı hesaplamanın girdisidir."],"tanim_en":"The solar constant is the solar radiative flux received at the mean Sun–Earth distance on a surface perpendicular to the Sun's rays, outside the atmosphere.","bag":{"kavram":["isinim-dengesi","tek-katman"],"soru":["S6","S8","S10"],"hesap":["etkin-sicaklik"]}},{"id":"sym-absorbed-solar-flux","tr":"Soğurulan güneş akısı","en":"absorbed solar radiation","kisa":"S₀(1−A)/4","tur":"olcu","es":["soğurulan güneş","S₀(1−A)/4","absorbed solar flux"],"tanim":["Yer ve atmosferin (bulut ve yüzey dahil) gelen güneş ışınımından soğurduğu kısımdır.","Kitapta küresel ortalama olarak S₀(1−A)/4 ile verilir; S₀ = 1361 W/m², A = 0,30 için ≈ 238 W/m².","Dengede uzaya giden uzun dalga ışınıma (OLR) eşittir; böylece etkin sıcaklık Tₑ ≈ 255 K bulunur ve sera etkisi G = σT_s⁴ − S₀(1−A)/4 olarak hesaplanır."],"tanim_en":"Absorbed solar radiation is the part of the incident solar radiation that is taken up by the atmosphere's constituent gas molecules, clouds, suspended material or the Earth's surface.","bag":{"kavram":["isinim-dengesi"],"soru":["S6","S8","S30"],"hesap":["etkin-sicaklik"]}},{"id":"parts-per-billion","tr":"Milyarda bir","en":"parts per billion","kisa":"ppb","tur":"birim","es":["ppb","ppbv","hacimce milyarda bir"],"tanim":["Karışım oranı birimi: bir gazın mol payı, 10⁻⁹ (mol/mol). Türkçe 'milyar' = İngilizce 'billion' (10⁹).","1 ppb = 10⁻⁹ ve 1 ppm = 1000 ppb. Kütle derişimine geçiş C = χ·M/24,45 (C: µg/m³, χ: ppb, M: g/mol).","Yerdeki ozon, NO₂ ve CH₄ gibi iz gazların derişimi bu birimle verilir; oran olduğu için basınç ve sıcaklıkla değişmez."],"tanim_en":"Parts per billion (ppb) is a unit of mixing ratio equal to one part in 10⁹, expressed as a mole fraction (mol/mol).","bag":{"kavram":["karisim-orani","kutle-derisimi"],"soru":["S1","S2","S44"],"hesap":["ppb-ugm3","ugm3-ppb"]}},{"id":"parts-per-million","tr":"Milyonda bir","en":"parts per million","kisa":"ppm","tur":"birim","es":["ppmv","hacimce milyonda bir","parts per million by volume"],"tanim":["Karışım oranı birimi: bir gazın mol payı, 10⁻⁶ (mol/mol). Gazlarda ppmv (hacimce) de yazılır; ideal gazda mol payı hacim payına eşit olduğu için ikisi aynıdır.","Kuru havada CO₂ ≈ 420 ppm, stratosferde O₃ ≈ 8 ppm. Sudaki ppm çoğunlukla kütlecedir (mg/kg); bağlama bak.","Oran olduğu için P ve T değişse de sabit kalır; ppm ↔ mg/m³ dönüşümü ppb ↔ µg/m³ ile aynı formüldür."],"tanim_en":"Parts per million (ppm) is a unit of mixing ratio equal to one part in 10⁶, expressed for a gas as a mole (or volume) fraction.","bag":{"kavram":["karisim-orani","zorlama","temiz-yagmur"],"soru":["S1","S2","S3","S4","S9","S26"],"hesap":[]}},{"id":"parts-per-trillion","tr":"Trilyonda bir","en":"parts per trillion","kisa":"ppt","tur":"birim","es":["ppt","pptv","hacimce trilyonda bir"],"tanim":["Karışım oranı birimi: bir gazın mol payı, 10⁻¹² (mol/mol). İngilizce 'trillion' = 10¹² = Türkçe 'trilyon'.","1 ppt = 10⁻¹² ve 1 ppb = 1000 ppt.","CFC'ler ve öteki halojenli gazlar bu düzeyde; örneğin CFC-12 yaklaşık 500 ppt düzeyinde bulunur."],"tanim_en":"Parts per trillion (ppt) is a unit of mixing ratio equal to one part in 10¹², expressed as a mole fraction (mol/mol).","bag":{"kavram":["karisim-orani"],"soru":[],"hesap":[]}},{"id":"carbon-dioxide","tr":"Karbon dioksit","en":"carbon dioxide","kisa":"CO₂","tur":"kavram","es":["CO2","karbondioksit","karbon dioksit gazı","carbonic acid gas","Karbondioksit","CO₂"],"tanim":["Doğrusal, simetrik üç atomlu molekül (CO₂); havada hacimce ≈ %0,042 (≈ 420 ppm) bulunur ve sera etkisinde büyük rol oynar.","Küresel ortalama karışım oranı 2023'te ≈ 420 ppm, sanayi öncesi ≈ 278 ppm; yüzeyde kısmi basıncı ≈ 42,5 Pa (420 ppm × 1013 hPa).","En önemli insan kaynaklı sera gazıdır; 15 µm bandında soğurur. OH ile tepkimez, okyanus ve biyosfer yavaşça alır; bu yüzden tek bir ömür değeri yoktur. Temiz yağmurun pH'ını ≈ 5,6'ya çeker."],"tanim_en":"Carbon dioxide (CO₂) is a well-mixed atmospheric gas, present at about 420 ppm, that absorbs infrared radiation and plays a central role in the greenhouse effect.","bag":{"kavram":["karisim-orani","kutle-derisimi","atmosfer-kutlesi"],"soru":["S3","S4","S5","S9","S13","S18"],"hesap":["zorlama","ph-temiz"]}},{"id":"nitrous-oxide","tr":"Diazot monoksit","en":"nitrous oxide","kisa":"N₂O","tur":"kavram","es":["N2O","azot protoksit","dinitrogen monoxide","güldürücü gaz","N₂O"],"tanim":["Formülü N₂O olan, kararlı ve IR aktif (dipol değişimi olan) bir sera gazıdır. NO ve NO₂ ile karıştırılmaz.","Küresel ortalama karışım oranı 2023'te ≈ 337 ppb (≈ 0,33 ppm), sanayi öncesi ≈ 270 ppb. Ömrü ≈ 110 yıl, GWP-100 değeri ≈ 273.","İyi karışmış gazdır; troposferde yutağı yoktur, stratosfere ulaşıp azot oksitlerin kaynağı olur."],"tanim_en":"Nitrous oxide (N₂O) is a long-lived, well-mixed greenhouse gas with a lifetime of about 110 years that is also a source of nitrogen oxides in the stratosphere.","bag":{"kavram":["karisim-orani","atmosfer-kutlesi","sera-etkisi"],"soru":["S5"],"hesap":[]}},{"id":"ozone","tr":"Ozon","en":"ozone","kisa":"O₃","tur":"kavram","es":["O3","trioksijen","stratospheric ozone","troposferik ozon","trioxygen","stratosferik ozon"],"tanim":["Üç oksijen atomlu (O₃) tepkimeye yatkın moleküldür; stratosferde UV'yi soğuran tabakayı, troposferde ise bir oksidan ve kirleticiyi oluşturur.","Toplam sütun ortalama ≈ 300 DU (1 DU = 2,69 × 10¹⁶ molekül/cm²). Yüzeyde arka plan ≈ 30–50 ppb; stratosferde karışım oranı ≈ 30–35 km'de en yüksek (≈ 8–10 ppm).","Stratosferde Chapman çevrimiyle üretilir ve katalitik döngülerle yok olur; troposferde NO₂ fotolizinden oluşur ve NO ile titrasyona uğrar. IR aktiftir (9,6 µm bandı)."],"tanim_en":"Ozone (O₃) is a reactive triatomic form of oxygen that absorbs ultraviolet radiation in the stratosphere and acts as an oxidant and pollutant near the surface.","bag":{"kavram":["karisim-orani","sayi-yogunlugu","sera-etkisi"],"soru":["S1","S5","S21","S32","S40","S41"],"hesap":["chapman-o","cfc-ozon","leighton"]}},{"id":"trace-gas","tr":"İz gaz","en":"trace gas","kisa":"","tur":"kavram","es":["eser gaz","eser gazlar","iz gazlar","trace gases"],"tanim":["Havanın çok küçük bir kesrini oluşturan gaz. N₂ (%78), O₂ (%21) ve Ar (%0,93) ana bileşendir, iz gaz değildir.","Karışım oranı ppm, ppb ya da ppt ile verilir; kitapta mol payı χ olarak ele alınır. Örneğin CO₂ ≈ 420 ppm, CH₄ ≈ 1,9 ppm, N₂O ≈ 0,33 ppm.","Miktarı küçük olsa da etkisi büyük olabilir: ozon bir iz gazdır ama UV'yi güçlü soğurur."],"tanim_en":"A trace gas is a gas present in the atmosphere in very small amounts, typically expressed in ppm, ppb or ppt, in contrast to the major constituents N₂, O₂ and Ar.","bag":{"kavram":["karisim-orani"],"soru":["S4","S5","S14","S38"],"hesap":[]}},{"id":"water-vapor","tr":"Su buharı","en":"water vapor","kisa":"H₂O","tur":"kavram","es":["su buharı gazı","water vapour","H₂O"],"tanim":["Gaz hâlindeki su. Bükük ve kalıcı dipolü olan, IR aktif bir moleküldür.","Havadaki miktarı sıcaklıkla belirlenir: doymuş buhar basıncı her 1 K'de ≈ %7 artar (Clausius–Clapeyron). Karışma oranı r (kg/kg) bir kütle oranıdır; iz gazların χ'si ise mol oranıdır.","En güçlü sera gazıdır, ama zorlama değil geri beslemedir: ısınma nemi artırır, nem ısınmayı pekiştirir (pozitif geri besleme)."],"tanim_en":"Water vapor is water in the gaseous phase; it is the strongest greenhouse gas, and its atmospheric amount is controlled by temperature, so it acts as a feedback rather than a forcing.","bag":{"kavram":["karisim-orani","sera-etkisi","geri-besleme"],"soru":["S5","S8","S9","S11","S12","S13"],"hesap":["clausius"]}},{"id":"partial-pressure","tr":"Kısmi basınç","en":"partial pressure","kisa":"p","tur":"olcu","es":["kısmi gaz basıncı","p_i","gaz kısmi basıncı","p_CO2","partial gas pressure"],"tanim":["Gaz karışımında bir bileşenin tek başına bütün hacmi doldursaydı yapacağı basınç. Toplam basınç, kısmi basınçların toplamıdır.","p_X = χ_X · P (Dalton) ve p_X = n_X k T; birimi Pa ya da hPa.","Karışım oranı χ'nin mol payı ile basınç payına eşit olduğunu gösterir; ayrıca çözünme dengesinde (Henry) ve su buharında kullanılır."],"tanim_en":"Partial pressure is the pressure that one gas in a mixture would exert if it alone occupied the whole volume at the same temperature.","bag":{"kavram":["karisim-orani","temiz-yagmur"],"soru":["S3","S26"],"hesap":["ph-temiz"]}},{"id":"volume-fraction","tr":"Hacim payı","en":"volume fraction","kisa":"","tur":"olcu","es":["hacim oranı","hacimce oran","ppmv"],"tanim":["Bir bileşenin hacminin toplam hacme oranı; boyutsuzdur ve yüzde ya da ppmv olarak yazılır.","İdeal gazda mol payı = hacim payı = basınç payıdır; bu yüzden gazlarda 'ppmv' ile 'ppm' aynı şeydir. Kuru hava: N₂ %78, O₂ %21, Ar %0,93.","Kitabın aerosol bölümünde hacim payı başka anlamda geçer: her modun parçacık hacmi, n·(4/3)πr³ ile µm³/cm³ cinsinden. Gaz karışım oranıyla karıştırma."],"tanim_en":"Volume fraction is the ratio of the volume of a component to the total volume of the mixture, which for an ideal gas equals its mole fraction.","bag":{"kavram":["karisim-orani"],"soru":["S15","S17"],"hesap":["sayi-yogunlugu"]}},{"id":"water-vapor-mixing-ratio","tr":"Su buharı karışma oranı","en":"water vapor mixing ratio","kisa":"r","tur":"olcu","es":["karışma oranı","mixing ratio of water vapor","water vapour mixing ratio"],"tanim":["Belirli bir hava hacmindeki su buharı kütlesinin kuru hava kütlesine oranıdır.","Birimi g/kg ya da kg/kg olan boyutsuz bir kütle oranıdır; r simgesiyle gösterilir.","Yoğuşma ve buharlaşma olmadığı sürece adyabatik dikey hareketlerde korunur, çiy noktası değişiminde temel parametredir."],"tanim_en":"Water vapor mixing ratio is the ratio of the mass of water vapor to the mass of dry air in a given air parcel.","bag":{"kavram":["karisim-orani"],"soru":[],"hesap":["sayi-yogunlugu"]}},{"id":"chemical-production","tr":"Kimyasal üretim","en":"chemical production","kisa":"P","tur":"surec","es":["kimyasal kaynak","chemical source"],"tanim":["Bir kimyasal türün atmosferin içinde kimyasal tepkimelerle oluşmasıdır; kutu modelinde kaynak tarafındaki P terimi.","Kutu modellerinde ve süreklilik denkleminde hacimsel üretim hızı veya toplam kütle akısı olarak yer alır.","İkincil kirleticilerin ve radikallerin atmosferdeki derişimini doğrudan artıran temel iç kaynaktır."],"tanim_en":"The formation of a chemical compound in the atmosphere through chemical reactions.","bag":{"kavram":["kutu-modeli","omur"],"soru":[],"hesap":["omur-denge"]}},{"id":"emission","tr":"Emisyon","en":"emission","kisa":"E","tur":"surec","es":["salım","salım hızı","emisyon akısı","emission rate"],"tanim":["Kirleticilerin veya kimyasal türlerin noktasal, çizgisel veya alansal kaynaklardan atmosfere doğrudan verilmesidir.","Kütle akısı olarak genellikle Tg/yıl, kg/s veya g/(m²·s) birimleriyle ifade edilir ve kutu modelinde E terimiyle gösterilir.","Işınım fiziğindeki ısıl yayım kavramından farklı olarak atmosfer kimyasında birincil kirleticilerin atmosfere giriş hızını temsil eder."],"tanim_en":"The direct discharge of pollutants into the atmosphere from a source.","bag":{"kavram":["karisim-orani","kutu-modeli","omur"],"soru":["S3","S5","S6","S9","S14","S18"],"hesap":["kutu-modeli","omur-denge"]}},{"id":"dalton-law","tr":"Dalton kısmi basınçlar yasası","en":"Dalton's law of partial pressures","kisa":"","tur":"yontem","es":["Dalton bağıntısı","Dalton yasası"],"tanim":["İdeal bir gaz karışımının toplam basıncının, karışımı oluşturan gazların bağımsız olarak uyguladıkları kısmi basınçların toplamına eşit olduğunu belirten yasadır.","Bir gazın kısmi basıncı, o gazın mol kesri ile toplam atmosfer basıncının çarpımına eşittir.","Atmosfer kimyasında iz gazların kısmi basıncını ve Henry yasası çözünürlük dengelerini hesaplamada temel oluşturur."],"tanim_en":"A physical law stating that the total pressure of an ideal gas mixture equals the sum of the partial pressures of all its components.","bag":{"kavram":["karisim-orani"],"soru":["S3"],"hesap":["sayi-yogunlugu"]}},{"id":"bromine-radical","tr":"Brom atomu","en":"bromine atom","kisa":"Br","tur":"kavram","es":["brom radikali","atomik brom","Br"],"tanim":["Stratosferik ozon tabakasında etkin bir katalizör olarak görev yapan, eşleşmemiş elektron içeren tek atomlu halojen radikalidir.","Ozon ile doğrudan tepkimeye girerek brom monoksit (BrO) üretir ve katalitik çevrimin sonunda yapısı bozulmadan tekrar açığa çıkar.","Rezervuar bileşiklerine klora kıyasla çok daha zor bağlandığından, atom başına ozon yok etme gücü klor radikalinden onlarca kat daha yüksektir."],"tanim_en":"A highly reactive single-atom halogen radical that acts as an efficient catalyst in stratospheric ozone depletion.","bag":{"kavram":["katalitik"],"soru":[],"hesap":[]}},{"id":"catalyst","tr":"Katalizör","en":"catalyst","kisa":"X","tur":"kavram","es":["katalitik tür","catalytic species"],"tanim":["Bir kimyasal tepkimenin hızını artıran, tepkime yolunun aktivasyon enerjisini düşüren ve net tepkimede harcanmadan açığa çıkan kimyasal türdür.","Atmosferde Cl, Br, NO ve OH gibi serbest radikaller katalizör rolü üstlenir.","Net tepkime denkleminde yer almaz; kapalı bir döngüde ara basamaklarda kullanılıp tekrar serbest kalır."],"tanim_en":"A substance that accelerates a chemical reaction without being consumed in the overall transformation.","bag":{"kavram":["katalitik"],"soru":["S42"],"hesap":[]}},{"id":"cfc-11","tr":"CFC-11","en":"CFC-11","kisa":"CFCl₃","tur":"kavram","es":["CFCl3","triklorflorometan","Freon-11","trichlorofluoromethane"],"tanim":["Triklorflorometan (CFCl₃): bir karbon, üç klor ve bir flor atomu içeren, troposferde tepkimeye girmeyen yapay bir kloroflorokarbon.","Mol kütlesi 137,37 g/mol, atmosferik ömrü ≈ 50 yıl; stratosferde morötesi ışınımla fotolize uğrayıp klor atomlarını serbest bırakır.","Molekül başına 3 Cl taşıdığı için kütle başına CFC-12'den (2 Cl) daha çok klor verir; üretimi Montreal Protokolü ile durdurulmuştur."],"tanim_en":"CFC-11 (trichlorofluoromethane, CFCl₃) is a synthetic chlorofluorocarbon with an atmospheric lifetime of about 50 years that yields ozone-depleting chlorine atoms in the stratosphere.","bag":{"kavram":["katalitik","stokiyometri"],"soru":["S42"],"hesap":[]}},{"id":"halogen","tr":"Halojen","en":"halogen","kisa":"","tur":"kavram","es":["halojen grubu","halojenler"],"tanim":["Periyodik tablonun 17. grubunda bulunan flor, klor, brom ve iyot elementlerinden oluşan ametal ailesidir.","İnsan kaynaklı halojenli gazlarla stratosfere taşınır ve serbest radikal oluşturduklarında katalitik ozon yıkımına neden olur.","Ozon bozumunda brom atom başına klordan çok daha etkilidir; flor ise kuvvetli HF bağı kurarak etkisiz rezervuarda kalır."],"tanim_en":"A group 17 chemical element, notably chlorine or bromine, capable of catalytic ozone destruction in the stratosphere.","bag":{"kavram":["katalitik"],"soru":[],"hesap":[]}},{"id":"halogen-monoxide-radical","tr":"Halojen monoksit radikali","en":"halogen monoxide radical","kisa":"XO","tur":"kavram","es":["XO radikali","halojen monoksit","XO"],"tanim":["Bir halojen atomunun ozondan bir oksijen atomu koparması sonucu oluşan eşleşmemiş elektronlu serbest radikal ara ürünüdür.","Katalitik ozon döngüsünün ilk basamağında (X + O₃ → XO + O₂) meydana gelir ve ikinci basamakta atomik oksijen ile tepkimeye girerek ana katalizör X atomunu serbest bırakır.","Stratosferde ClO ve BrO formunda bulunur ve katalitik ozon kaybının doğrudan göstergesi kabul edilir."],"tanim_en":"A reactive radical intermediate formed when a halogen atom strips an oxygen atom from ozone during catalytic ozone destruction.","bag":{"kavram":["katalitik"],"soru":[],"hesap":[]}},{"id":"methyl-radical","tr":"Metil radikali","en":"methyl radical","kisa":"CH₃","tur":"kavram","es":["CH₃","metil"],"tanim":["Merkezdeki bir karbon atomuna üç hidrojen atomunun bağlı olduğu, eşleşmemiş tek elektron taşıyan kısa ömürlü organik radikaldir.","Stratosferde klor atomunun metan ile tepkimesi (Cl + CH₄ → HCl + CH₃) veya troposferde metanın hidroksil radikaliyle karşılaşması sonucu açığa çıkar.","Atmosferde moleküler oksijen (O₂) ile hızla birleşerek metilperoksi radikaline (CH₃O₂) dönüşür ve hidrokarbon oksidasyon zincirini yürütür."],"tanim_en":"The methyl radical (CH₃) is a short-lived organic radical formed in methane oxidation by OH and by the reaction of Cl with CH₄.","bag":{"kavram":["katalitik"],"soru":[],"hesap":[]}},{"id":"null-cycle","tr":"Sıfır döngü","en":"null cycle","kisa":"","tur":"kavram","es":["net değişimsiz döngü"],"tanim":["Kimyasal türleri birbirine dönüştüren ancak ortamda net bir kimyasal üretim ya da tüketim yaratmayan tepkime dizisidir.","Radikaller ve ozon arasında hızlı bir döngü kurar; soğurulan foton enerjisini ısıya çevirir.","Net ozon kaybına yol açmaz; ozon miktarını doğrudan eksiltmeden türlerin fotodurağan dengesini belirler."],"tanim_en":"A reaction cycle that interconverts chemical species without producing any net chemical change in the atmosphere.","bag":{"kavram":["katalitik","leighton"],"soru":["S41"],"hesap":[]}},{"id":"radical","tr":"Radikal","en":"radical","kisa":"","tur":"kavram","es":["serbest radikal","free radical"],"tanim":["En dış kabuğunda bir veya daha fazla eşleşmemiş elektron bulunduran, kimyasal etkinliği çok yüksek kararsız kimyasal türdür.","Atmosferde fotoliz tepkimeleriyle oluşur ve derişimi çok düşük olmasına karşın zincirleme kimyasal dönüşümleri tetikler.","OH radikali troposferde birincil kirleticileri temizleyen ana yükseltgen iken, Cl radikali stratosferde ozonu katalitik olarak bozar."],"tanim_en":"A highly reactive chemical species containing one or more unpaired electrons that drives atmospheric oxidation chains.","bag":{"kavram":["katalitik","leighton","asit-yagmuru"],"soru":["S28","S32","S33","S38","S42","S44"],"hesap":[]}},{"id":"reaction-intermediate","tr":"Ara ürün","en":"reaction intermediate","kisa":"","tur":"kavram","es":["kimyasal ara ürün","ara tür","intermediate"],"tanim":["Çok basamaklı bir tepkime mekanizmasında ara basamakta oluşup sonraki basamakta harcanan, net denklemde yer almayan geçici moleküler tür.","Çoğu zaman kısa ömürlü ve çok etkin bir türdür (ör. radikal); derişimi düşük kalır.","Atmosferde ozon bozunum döngülerinde ClO ve NO₂ gibi moleküler yapılar ara ürün olarak işlev görür; net denklemde görünmeden katalitik çevrimi tamamlar."],"tanim_en":"A molecular entity that is formed from reactants in an elementary step and consumed in a subsequent step of a chemical mechanism.","bag":{"kavram":["katalitik"],"soru":["S42"],"hesap":[]}},{"id":"source-gas","tr":"Kaynak gaz","en":"source gas","kisa":"","tur":"kavram","es":["halojen kaynak gazı","halocarbon source gas"],"tanim":["Troposferde parçalanmadan stratosfere taşınan ve fotoliz yoluyla reaktif radikalleri salan uzun ömürlü başlangıç gazıdır.","CFC-11, CFC-12 gibi kloroflorokarbonlar ve halonlar onlarca yıllık atmosferik ömürleriyle başlıca halojen kaynak gazlarıdır.","Stratosferde yüksek enerjili morötesi ışınımı soğurarak klor ve brom radikallerini serbest bırakır ve katalitik ozon bozumunu başlatır."],"tanim_en":"A long-lived chemical compound transported to the stratosphere where photolysis liberates reactive halogen radicals.","bag":{"kavram":["katalitik","psc"],"soru":[],"hesap":[]}},{"id":"hox-catalytic-cycle","tr":"HOₓ katalitik döngüsü","en":"HOx catalytic cycle","kisa":"HOₓ","tur":"surec","es":["HOx döngüsü","HOₓ döngüsü","hidrojen oksit döngüsü","HOx cycle"],"tanim":["Hidroksil (OH) ve hidroperoksil (HO₂) radikallerinin (HOₓ = OH + HO₂) katalizör olarak ozonu oksijene çevirdiği tepkime döngüsü.","Alt stratosferdeki başlıca dalı: OH + O₃ → HO₂ + O₂ ve HO₂ + O₃ → OH + 2O₂; net 2O₃ → 3O₂. HOₓ, su buharı ve metanın O(¹D) ile tepkimesinden doğar.","Chapman çevriminin fazla verdiği ozonu NOₓ ve ClOₓ döngüleriyle birlikte azaltır; alt stratosferde ve stratosferin üst kesiminde en etkili döngüdür."],"tanim_en":"The HOₓ catalytic cycle is the destruction of ozone by the hydroxyl and hydroperoxyl radicals (HOₓ = OH + HO₂), which are regenerated in every turn; in the lower stratosphere its net result is 2O₃ → 3O₂.","bag":{"kavram":["katalitik","chapman"],"soru":[],"hesap":[]}},{"id":"nox-catalytic-cycle","tr":"NOₓ katalitik döngüsü","en":"NOₓ catalytic cycle","kisa":"","tur":"surec","es":["NOₓ döngüsü","NOx döngüsü","azot oksit katalitik döngüsü"],"tanim":["Stratosferde NO ve NO₂ radikallerinin ozon ve oksijen atomuyla tepkimeye girerek ozonu katalitik yoldan oksijene dönüştürdüğü zincirleme süreç.","Döngüde NO ozonla tepkimeye girip NO₂ oluşturur; NO₂ oksijen atomuyla tepkimeye girerek NO radikalini geri verir ve net tepkimede tek oksijen kaybı gerçekleşir.","Chapman çevriminin öngördüğü denge ozon miktarını doğal stratosferde sınırlayan en önemli katalitik yollardan biridir."],"tanim_en":"A catalytic cycle in which nitric oxide and nitrogen dioxide destroy stratospheric ozone without being consumed in the net reaction.","bag":{"kavram":["katalitik","chapman"],"soru":["S41","S42"],"hesap":[]}},{"id":"montreal-protocol","tr":"Montreal Protokolü","en":"Montreal Protocol","kisa":"","tur":"yontem","es":["Montreal Sözleşmesi","Montreal Anlaşması"],"tanim":["Ozon tabakasını incelten kloroflorokarbonlar ve ilgili kimyasalların üretimini aşamalı olarak durduran uluslararası çevre antlaşmasıdır.","1987 yılında kabul edilmiş, 1989 yılında yürürlüğe girmiş ve 2016 Kigali değişikliği ile hidroflorokarbonları da denetim altına almıştır.","Stratosferdeki halojen yükünün azalmasını sağlayarak küresel ozon tabakasının iyileşme sürecine girmesini sağlamıştır."],"tanim_en":"An international treaty designed to protect the stratospheric ozone layer by phasing out the production of ozone-depleting chemical compounds.","bag":{"kavram":["katalitik"],"soru":[],"hesap":["cfc-ozon"]}},{"id":"fog","tr":"Sis","en":"fog","kisa":"","tur":"kavram","es":["FG"],"tanim":["Yere yakın hava tabakasında mikroskobik su damlacıklarının asılı kalmasıyla oluşan ve yatay görüş mesafesini 1 km altına düşüren atmosfer olayıdır.","Bağıl nemin %100 değerine yaklaşması ve havanın çiy noktasına kadar soğumasıyla su buharının yoğuşması sonucu meydana gelir.","Işığı Mie saçılması yoluyla saçarak görüş mesafesini keskin biçimde azaltır ve hava ile kara ulaşımını doğrudan etkiler."],"tanim_en":"A suspension of microscopic water droplets in the air limiting horizontal visibility to under one kilometer.","bag":{"kavram":["koschmieder"],"soru":["S8","S9","S11","S13","S17","S20"],"hesap":[]}},{"id":"haze","tr":"Pus","en":"haze","kisa":"","tur":"kavram","es":["kuru pus","HZ","atmosferik pus","kuru duman"],"tanim":["Atmosferde asılı duran mikroskobik kuru aerosol parçacıklarının gökyüzüne opalsi bir görünüm vererek görüşü azaltması olayıdır.","Sönüm katsayısı tipik olarak K ≈ 0,3 km⁻¹ düzeyinde seyreder ve Koschmieder bağıntısına göre görüş mesafesini yaklaşık 13 km değerine düşürür.","Görüş mesafesini genellikle 1 km üzerinde tutar; higroskopik parçacıkların bağıl nem artışıyla su alıp şişmesi optik sönümü kuvvetlendirir."],"tanim_en":"A suspension of fine dry aerosol particles in the air that impairs visibility and imparts an opalescent appearance to the sky.","bag":{"kavram":["koschmieder","aerosol-dogrudan"],"soru":["S23","S25"],"hesap":[]}},{"id":"meteorological-optical-range","tr":"Meteorolojik optik menzil","en":"meteorological optical range","kisa":"MOR","tur":"kavram","es":["görüş uzaklığı","visual range","MOR"],"tanim":["Akkor bir kaynaktan çıkan paralel ışık demetinin atmosferde ilk değerinin %5 düzeyine indiği yol uzunluğudur.","Gözlemci kontrast eşiği 0,05 alınarak MOR = 2,996/σ bağıntısıyla aletsel olarak ölçülür.","Meteoroloji istasyonlarında ve havalimanlarında insan gözlemcinin görüş kestirimini nesnel kılmak amacıyla kullanılır."],"tanim_en":"The atmospheric path length along which the luminous flux of an optical beam attenuates to five percent of its initial value.","bag":{"kavram":["koschmieder"],"soru":["S23"],"hesap":[]}},{"id":"mist","tr":"Nemli pus","en":"mist","kisa":"","tur":"kavram","es":["BR","ıslak pus","pus (rasat dili)"],"tanim":["Yüksek bağıl nem altında havada asılı mikroskobik su damlacıklarının ya da ıslak higroskopik taneciklerin oluşturduğu hafif atmosferik örtüdür.","Bağıl nem yüksektir ama hava tam doygun değildir; görüş azalır, yine de 1 km ya da daha fazla kalır.","Havanın tam doygunluğa ulaşmadığı koşullarda sis öncesinde veya sis dağılırken oluşan geçiş evresini temsil eder."],"tanim_en":"A suspension of microscopic water droplets in the atmosphere that lowers horizontal visibility while keeping it at or above one kilometer.","bag":{"kavram":["koschmieder"],"soru":["S23","S25"],"hesap":[]}},{"id":"visible-light","tr":"Görünür ışık","en":"visible light","kisa":"VIS","tur":"kavram","es":["görünür ışınım","görünür bölge","görünür tayf","visible radiation"],"tanim":["İnsan gözünün algılayabildiği, dalga boyu yaklaşık 0,4 ile 0,7 µm arasında değişen elektromanyetik ışıma bandıdır.","Güneş ışımasının spektral tepe noktası Wien yasasına göre yaklaşık 0,5 µm dalga boyunda bu aralıkta yer alır.","Atmosferde birikme modu parçacıkları görünür ışığı Mie saçılmasıyla kuvvetle saçarak görüş mesafesini daraltır."],"tanim_en":"Visible light is the electromagnetic radiation band with wavelengths between 0.4 and 0.7 µm that can be perceived by the human eye.","bag":{"kavram":["koschmieder","beer-lambert","volkan-aerosol"],"soru":["S6","S11","S12","S15","S18","S22"],"hesap":[]}},{"id":"contrast-threshold","tr":"Kontrast eşiği","en":"contrast threshold","kisa":"ε","tur":"olcu","es":["eşik kontrast","kontrast eşik değeri","threshold contrast","visual contrast threshold"],"tanim":["Bir nesnenin ufuk arka planından insan gözüyle ayırt edilebilmesi için gereken en küçük bağıl parlaklık farkıdır.","Koschmieder eşitliğinde standart insan gözü için boyutsuz 0,02 (%2) sabit değeri kabul edilir.","Formüldeki 3,912 sabit pay değeri doğrudan ln(1/0,02) matematiksel işleminden kaynaklanır."],"tanim_en":"Contrast threshold is the minimum relative luminance contrast enabling an observer to distinguish an object from its background.","bag":{"kavram":["koschmieder"],"soru":["S23"],"hesap":["koschmieder"]}},{"id":"extinction-coefficient","tr":"Yok olma (sönüm) katsayısı","en":"extinction coefficient","kisa":"K","tur":"olcu","es":["sönüm katsayısı","yok olma katsayısı","b_ext","σ_ext","extinction"],"tanim":["Işığın atmosferde ilerlerken birim yol boyunca saçılma ve soğurma nedeniyle uğradığı toplam zayıflamanın ölçüsüdür.","Birimi km⁻¹ veya m⁻¹ olup saçılma ve soğurma kesitlerinin parçacık sayı yoğunluğuyla çarpımına eşittir; atmosferde tipik değeri 0,01–1 km⁻¹ aralığındadır.","Koschmieder formülünde paydada yer alır ve optik yol boyunca integrali optik derinliği (τ = K L) verir."],"tanim_en":"Extinction coefficient is the fractional attenuation of light per unit path length through scattering and absorption in the atmosphere.","bag":{"kavram":["koschmieder","beer-lambert"],"soru":["S23","S25","S41"],"hesap":["koschmieder","optik-derinlik","beer-kesit"]}},{"id":"hygroscopic-growth","tr":"Higroskopik büyüme","en":"hygroscopic growth","kisa":"","tur":"surec","es":["su çekme","higroskopik su alımı","nemle şişme","hygroscopic swelling"],"tanim":["Ortamdaki bağıl nem arttıkça aerosol parçacıklarının su alarak çaplarını ve optik kesitlerini büyütmesi olayıdır.","Büyüme oranı Köhler kuramına ve parçacığın kimyasal çözünürlüğüne bağlı olarak belirlenir.","Parçacıkların büyümesi ışık saçılmasını ve sönüm katsayısını artırarak Koschmieder bağıntısına göre görüş mesafesini önemli ölçüde kısaltır."],"tanim_en":"The process in which aerosol particles absorb water vapor from ambient air under elevated relative humidity and expand in diameter.","bag":{"kavram":["koschmieder"],"soru":[],"hesap":[]}},{"id":"mie-scattering","tr":"Mie saçılması","en":"Mie scattering","kisa":"","tur":"surec","es":["aerosol saçılması"],"tanim":["Işınımın, kendi dalga boyuna yakın boyutlardaki küresel aerosol parçacıkları ve bulut damlacıkları tarafından saçılması olayıdır.","Saçılma ileri yönde güçlüdür ve dalga boyuna zayıf bağlı olduğu için bulut ile pus tabakalarının beyaz veya gri görünmesini sağlar.","Birikme modundaki alt mikron sülfat ve nitrat parçacıkları güneş ışığını bu yolla uzaya saçarak doğrudan soğutma etkisi yapar."],"tanim_en":"Scattering of electromagnetic radiation by spherical particles with dimensions comparable to the incident wavelength.","bag":{"kavram":["koschmieder","beer-lambert"],"soru":["S33"],"hesap":[]}},{"id":"unit-atmosphere","tr":"Atmosfer","en":"atmosphere","kisa":"atm","tur":"birim","es":["atm","standart atmosfer","atmosfer (basınç birimi)","standard atmosphere"],"tanim":["Basınç birimi: 1 atm = 101 325 Pa = 1013,25 hPa (tanım gereği tam değer).","Kitapta ve kimya bağıntılarında (ideal gaz yasası, Henry yasası) standart basınç birimi olarak kullanılır.","25 °C ve 1 atm'de bir mol ideal gaz 24,45 L, 0 °C ve 1 atm'de 22,41 L hacim kaplar."],"tanim_en":"The standard atmosphere (atm) is a non-SI unit of pressure defined as exactly 101 325 Pa (1013.25 hPa).","bag":{"kavram":["kutle-derisimi","temiz-yagmur"],"soru":["S2","S3","S4","S5","S6","S7"],"hesap":["ppb-ugm3","ph-temiz","sayi-yogunlugu"]}},{"id":"unit-ug-m3","tr":"Mikrogram bölü metreküp","en":"microgram per cubic meter","kisa":"µg/m³","tur":"birim","es":["ug/m3","µg/m3","Metreküpte mikrogram","Metreküp başına mikrogram","µg m^-3","micrograms per cubic meter"],"tanim":["Bir metreküp hava hacminde asılı bulunan kirletici maddenin mikrogram (10⁻⁶ g) cinsinden kütlesini ifade eden derişim birimidir.","Sıcaklık ve basınca bağlı bir büyüklüktür; ideal gaz yasası kullanılarak ppb karışım oranından molar kütle ve molar hacimle çevrilir.","Hava kalitesi yönetmeliklerinde partikül madde (PM2.5, PM10) ve gaz kirleticilerin sınır değerlerini yasal olarak belirlemede temel birimdir."],"tanim_en":"Microgram per cubic meter is an atmospheric concentration unit quantifying pollutant mass within one cubic meter of air.","bag":{"kavram":["kutle-derisimi","pm","boyut-modlari"],"soru":["S2","S3","S4","S16","S19","S39"],"hesap":["ppb-ugm3","ugm3-ppb","aerosol-mod"]}},{"id":"aerosol","tr":"Aerosol","en":"aerosol","kisa":"","tur":"kavram","es":["havada asılı parçacık","partikül","atmosferik aerosol","parçacık","askıda parçacık","asılı tanecik"],"tanim":["Katı parçacıkların veya sıvı damlacıkların bir gaz ortamı içinde kararlı biçimde asılı kalmasıyla oluşan iki fazlı heterojen sistemdir.","Troposferdeki ömrü çökelme mekanizmaları nedeniyle yaklaşık 1 hafta iken, stratosfere ulaşan volkanik sülfat aerosolünün e-katlanma ömrü yaklaşık 1 yıldır.","Güneş ışığını saçıp soğurarak doğrudan ışınımsal zorlama üretir, bulut yoğuşma çekirdeği oluşturarak bulut albedosunu dolaylı yoldan etkiler."],"tanim_en":"An aerosol is a colloidal system of solid particles or liquid droplets suspended in a gaseous medium.","bag":{"kavram":["kutle-derisimi","aerosol-sinif","bulut-isinim"],"soru":["S12","S14","S15","S16","S17","S18"],"hesap":["aerosol-mod"]}},{"id":"carbon-monoxide","tr":"Karbon monoksit","en":"carbon monoxide","kisa":"CO","tur":"kavram","es":["karbonmonoksit","CO"],"tanim":["Fosil yakıtların ve biyokütlenin eksik yanması sonucu havaya salınan, kokusuz ve renksiz birincil kirletici gazdır.","Atmosferik ömrü yaklaşık 2 ay olup hidroksil radikali (OH) ile tepkimeye girerek karbondioksite (CO₂) yükseltgenir.","Troposferde birincil OH yutağı rolü üstlenir; OH radikalini tüketerek metan gibi sera gazlarının atmosferik ömrünü dolaylı yoldan artırır."],"tanim_en":"Carbon monoxide is a toxic trace gas produced by incomplete combustion that acts as the primary sink for tropospheric hydroxyl radical.","bag":{"kavram":["kutle-derisimi","atmosfer-kutlesi","ir-aktif"],"soru":["S2","S5","S18","S38"],"hesap":[]}},{"id":"standard-temperature-and-pressure","tr":"Standart sıcaklık ve basınç","en":"standard temperature and pressure","kisa":"STP","tur":"kavram","es":["standart koşullar","normal koşullar","standard conditions"],"tanim":["Fiziksel ve kimyasal büyüklüklerin karşılaştırılabilmesi için referans kabul edilen sıcaklık ve basınç durumudur.","Ders kitabında geleneksel olarak 0 °C (273,15 K) sıcaklık ve 1 atm (1013,25 hPa) basınç kabul edilir; bu koşullarda 1 mol ideal gaz 22,41 L hacim kaplar.","Kitaptaki ppb ↔ µg/m³ çevirilerinde ise 25 °C (298,15 K) ve 1 atm alınır; bu koşullarda molar hacim 24,45 L/mol olur."],"tanim_en":"Standard temperature and pressure (STP) is a reference state for comparing gas properties, conventionally 0 °C (273.15 K) and 1 atm; IUPAC now recommends 1 bar.","bag":{"kavram":["kutle-derisimi","sayi-yogunlugu"],"soru":["S2","S3"],"hesap":[]}},{"id":"sulfur-dioxide","tr":"Kükürt dioksit","en":"sulfur dioxide","kisa":"SO₂","tur":"kavram","es":["kükürtdioksit","sülfür dioksit","SO2","sulphur dioxide"],"tanim":["Kükürt içeren fosil yakıtların yanması ve volkanik patlamalarla atmosfere salınan, keskin kokulu birincil gaz kirleticidir.","Gaz fazında OH radikaliyle tepkimeye girerek sülfürik aside (H₂SO₄) ve ardından sülfat aerosolüne dönüşür.","Alt atmosferde asit yağmurlarına ve duman kirliliğine yol açarken stratosfere ulaştığında güneş ışığını yansıtan sülfat perdesi oluşturur."],"tanim_en":"Sulfur dioxide is a pungent primary pollutant emitted by combustion and volcanic eruption which undergoes oxidation to form sulfuric acid.","bag":{"kavram":["kutle-derisimi","aerosol-sinif","asit-yagmuru"],"soru":["S2","S14","S26","S28","S30","S31"],"hesap":[]}},{"id":"air-quality-standard","tr":"Hava kalitesi sınır değeri","en":"air quality standard","kisa":"","tur":"olcu","es":["hava kalitesi standardı","sınır değer","kılavuz değer","limit value"],"tanim":["İnsan sağlığını ve çevreyi korumak amacıyla havadaki kirletici derişimleri için yasal otoritelerce belirlenen en yüksek izin verilebilir değerdir.","Belirli bir maruziyet süresiyle (1 saat, 8 saat, 24 saat veya yıllık) ve çoğunlukla µg/m³ ya da ppm birimiyle tanımlanır.","Kimyasal modelleme ve ölçüm sonuçlarının insan sağlığı açısından değerlendirilmesinde bağlayıcı eşik görevi görür."],"tanim_en":"An air quality standard is a legally binding threshold concentration established over a specific averaging time to protect human health and the environment.","bag":{"kavram":["kutle-derisimi","pm"],"soru":["S2","S16","S19"],"hesap":["ppb-ugm3"]}},{"id":"molar-mass","tr":"Mol kütlesi","en":"molar mass","kisa":"M","tur":"olcu","es":["molar kütle","mol ağırlığı","molekül ağırlığı"],"tanim":["Bir kimyasal maddenin bir molünün kütlesi.","Birimi g/mol ya da kg/mol; kuru havanın ortalama mol kütlesi ≈ 28,97 g/mol (≈ 0,029 kg/mol).","İz gazların mol kesri (ppm, ppb) ile kütle derişimi (µg/m³) arasındaki dönüşümde ve atmosferik yük hesabında temel çarpandır."],"tanim_en":"The mass of one mole of a chemical element or chemical compound, typically measured in grams per mole.","bag":{"kavram":["kutle-derisimi","atmosfer-kutlesi","stokiyometri"],"soru":["S2","S4","S28","S29","S31","S42"],"hesap":["ppb-ugm3","ugm3-ppb","atmosfer-kutlesi","cfc-ozon"]}},{"id":"molar-volume","tr":"Molar hacim","en":"molar volume","kisa":"Vₘ","tur":"olcu","es":["mol hacmi","Vm","gaz molar hacmi","Vₘ"],"tanim":["Bir maddenin bir molünün belirli sıcaklık ve basınç altında kapladığı hacim.","İdeal gaz yasasından Vₘ = RT/P bağıntısıyla bulunur; 1 atm basınçta 0 °C sıcaklıkta 22,41 L/mol, 25 °C sıcaklıkta ise 24,45 L/mol değerini alır.","Hava kalitesi hesaplarında iz gazların hacimsel karışım oranı ile kütle derişimi arasındaki çevrimde hacim köprüsünü kurar."],"tanim_en":"The volume occupied by one mole of a substance at a specified temperature and pressure.","bag":{"kavram":["kutle-derisimi","karisim-orani"],"soru":["S2","S3"],"hesap":["ppb-ugm3","ugm3-ppb"]}},{"id":"atmospheric-boundary-layer","tr":"Atmosferik sınır tabaka","en":"atmospheric boundary layer","kisa":"ABL","tur":"kavram","es":["gezegensel sınır tabaka","sınır tabaka","PBL","planetary boundary layer","boundary layer"],"tanim":["Troposferin, yeryüzü ile doğrudan temas hâlinde olan ve yüzey zorlamalarına hızla yanıt veren en alt katmanı.","Kalınlığı günlük ısınma döngüsüne bağlı olarak gündüz yaklaşık 1–2 km seviyesine ulaşırken gece yüzey soğuması ve terselme etkisiyle birkaç yüz metreye kadar iner.","Yüzeyden salınan hava kirleticilerinin ve nemin türbülansla karıştığı ana atmosfer katmanıdır."],"tanim_en":"The lowest part of the troposphere that is directly influenced by the Earth's surface and subject to turbulent mixing.","bag":{"kavram":["kutu-modeli","omur"],"soru":[],"hesap":[]}},{"id":"mass-balance","tr":"Kütle dengesi","en":"mass balance","kisa":"","tur":"kavram","es":["kütle bütçesi","kütle korunumu","atmosferik bütçe","budget","mass conservation"],"tanim":["Belirli bir kontrol hacmine giren, çıkan, kimyasal olarak üretilen ve tüketilen madde miktarları arasındaki kütle korunumuna dayalı eşitlik.","Sistemdeki birikim dM/dt = kaynaklar − yutaklar denklemiyle ifade edilir; kararlı hâlde birikim sıfıra eşit olur.","Atmosfer kimyasında kutu modellerinin kurulmasında ve kirleticilerin denge derişimlerinin türetilmesinde temel ilkedir."],"tanim_en":"An accounting of mass conservation stating that system accumulation equals mass input minus mass output.","bag":{"kavram":["kutu-modeli","omur"],"soru":["S28","S39"],"hesap":[]}},{"id":"mixing-height","tr":"Karışma yüksekliği","en":"mixing height","kisa":"h","tur":"olcu","es":["karışım yüksekliği","karışım tabakası yüksekliği","mixing depth","mixed-layer height"],"tanim":["Yeryüzünden itibaren yüzey kökenli kirleticilerin ve türbülansın düşey doğrultuda serbestçe karışabildiği tabakanın yüksekliği.","Çoğunlukla sıcaklık terselmesinin tabanıyla sınırlıdır; gündüz ısınmayla genellikle 1–2 km'ye çıkar, gece ve kış terselmelerinde birkaç yüz metreye iner.","Şehir kutu modelinde kirleticilerin dağıldığı düşey hacmi belirler ve derişimle ters orantılıdır."],"tanim_en":"The vertical depth above the ground through which air pollutants undergo turbulent mixing.","bag":{"kavram":["kutu-modeli"],"soru":["S39"],"hesap":["kutu-modeli"]}},{"id":"ventilation","tr":"Havalandırma","en":"ventilation","kisa":"u·h","tur":"surec","es":["havalandırma katsayısı","havalanma","ventilation coefficient"],"tanim":["Sınır tabaka içindeki havanın yatay rüzgâr taşınımı ve düşey türbülanslı karışım mekanizmalarıyla yenilenmesi ve seyrelmesi süreci.","Havalandırma katsayısı rüzgâr hızı ile karışma yüksekliğinin çarpımı (u × h, m²/s) olarak hesaplanır.","Katsayının düşük olması kirleticilerin birikmesine yol açarken, yüksek değerler kirleticilerin hızla dağılmasını sağlar."],"tanim_en":"The rate at which clean air sweeps through an urban boundary layer by wind transport and turbulent mixing.","bag":{"kavram":["kutu-modeli"],"soru":["S39"],"hesap":[]}},{"id":"air-parcel","tr":"Hava parseli","en":"air parcel","kisa":"","tur":"kavram","es":["hava paketi","parsel","parcel"],"tanim":["Çevresindeki ortam havasıyla ısı ve kütle alışverişine girmediği varsayılan, sınırları belirli hayali küçük hava kütlesi.","Düşey hareketi boyunca adyabatik olarak genleşir veya sıkışır; kuru hava için yaklaşık 9,8 K/km adyabatik düşüş oranıyla soğur.","Termodinamik süreçlerin, bağıl nem değişiminin ve bulut oluşum seviyesinin (LCL) çözümlenmesinde temel modelleme birimidir."],"tanim_en":"An imaginary body of air assumed to retain its identity without mixing with surrounding air during vertical motion.","bag":{"kavram":["lcl"],"soru":["S3","S4","S11"],"hesap":[]}},{"id":"convective-condensation-level","tr":"Konvektif yoğuşma seviyesi","en":"convective condensation level","kisa":"CCL","tur":"kavram","es":["CCL"],"tanim":["Yeryüzünün güneş ışınımıyla ısınması sonucu yüzeyden yükselen konvektif hava akımlarının yoğuşmaya başladığı yükseklik.","Termodinamik diyagramlarda yüzey çiy noktası karışma oranı çizgisi ile çevre sıcaklık profilinin kesiştiği seviye olarak belirlenir.","Gündüz saatlerinde termal konveksiyonla gelişen kümüloform bulutların taban yüksekliğini temsil eder."],"tanim_en":"The atmospheric height where condensation begins in an air parcel rising purely through thermal buoyancy.","bag":{"kavram":["lcl"],"soru":[],"hesap":[]}},{"id":"environmental-lapse-rate","tr":"Ortam sıcaklık azalma oranı","en":"environmental lapse rate","kisa":"","tur":"kavram","es":["çevre sıcaklık azalma oranı","ELR"],"tanim":["Durgun çevre atmosferinde yükseklikle gerçekleşen gerçek sıcaklık azalma oranıdır.","Radyosonda ölçümleriyle saptanır; troposfer genelinde ortalama değeri yaklaşık 6,5 K/km düzeyinde seyreder.","Hava parselinin adyabatik azalma oranıyla kıyaslanarak atmosferin statik kararlılık durumu belirlenir."],"tanim_en":"The actual rate of ambient air temperature drop with height in the stationary atmosphere.","bag":{"kavram":["lcl"],"soru":[],"hesap":[]}},{"id":"level-of-free-convection","tr":"Serbest konveksiyon seviyesi","en":"level of free convection","kisa":"","tur":"kavram","es":["LFC"],"tanim":["Yükselen bir hava parselinin çevre havasından daha sıcak ve hafif hâle gelerek pozitif kaldırma kuvvetiyle kendiliğinden yükselmeye başladığı yüksekliktir.","Termodinamik diyagramlarda parselin doymuş adyabatik sıcaklık eğrisinin çevre sıcaklık profilini kestiği seviye olarak saptanır.","Çoğunlukla kaldırma yoğuşma seviyesinin üzerinde yer alır ve derin konvektif bulut gelişimini başlatır."],"tanim_en":"The altitude at which a lifted air parcel becomes warmer than the ambient environment and ascends spontaneously under positive buoyancy.","bag":{"kavram":["lcl"],"soru":[],"hesap":[]}},{"id":"saturated-adiabatic-lapse-rate","tr":"Doymuş adyabatik azalma oranı","en":"saturated adiabatic lapse rate","kisa":"","tur":"kavram","es":["nemli adyabatik azalma oranı","moist adiabatic lapse rate","SALR","MALR"],"tanim":["Doygunluktaki bir hava parselinin adyabatik olarak yükselirken genleşmeyle soğuma oranıdır.","Yoğuşmada açığa çıkan gizli ısı soğumayı yavaşlattığı için kuru adyabatik orandan küçüktür: ılık ve nemli havada ≈ 4 K/km, çok soğuk havada (su buharı azken) 9,8 K/km'ye yaklaşır.","Bulut içi düşey sıcaklık profilinin ve nemli konvektif kararsızlığın belirlenmesinde kullanılır."],"tanim_en":"The rate of temperature decrease with altitude for a saturated air parcel undergoing adiabatic ascent.","bag":{"kavram":["lcl"],"soru":[],"hesap":[]}},{"id":"dew-point","tr":"Çiy noktası","en":"dew point","kisa":"T_d","tur":"olcu","es":["çiğ noktası","çiy noktası sıcaklığı","çiğ noktası sıcaklığı","dew-point temperature","Td"],"tanim":["Sabit basınç ve sabit su buharı içeriğinde, havanın doygunluğa ulaşması için soğutulması gereken sıcaklıktır.","Birimi °C veya K olup, hava parseli yükseldikçe basınç düşüşüne bağlı olarak yaklaşık 1,8 K/km oranında azalır.","Ortam sıcaklığı ile arasındaki fark havanın nem açığını ve bulut tabanı yüksekliğini belirler."],"tanim_en":"The temperature to which moist air must cool at constant pressure and constant water vapor content to reach saturation.","bag":{"kavram":["lcl","clausius"],"soru":["S11"],"hesap":["lcl"]}},{"id":"dew-point-depression","tr":"Çiy noktası farkı","en":"dewpoint depression","kisa":"T − Td","tur":"olcu","es":["nem farkı","çiğ noktası farkı","çiğ noktası açığı","dew-point depression"],"tanim":["Ortam hava sıcaklığı ile çiy noktası sıcaklığı arasındaki farktır.","Sıcaklık biriminde (°C ya da K) ifade edilir; değerin sıfır olması havanın doymuş olduğunu gösterir.","Havanın kuruluk derecesini yansıtır; her 1 K fark bulut tabanı yüksekliğini yaklaşık 125 m yukarı taşır."],"tanim_en":"The difference between ambient air temperature and dew point temperature, indicating the degree of dryness of the air.","bag":{"kavram":["lcl"],"soru":["S11"],"hesap":["lcl"]}},{"id":"dewpoint-lapse-rate","tr":"Çiy noktası azalma oranı","en":"dewpoint lapse rate","kisa":"Γ_dp","tur":"olcu","es":["çiğ noktası azalma oranı","çiğ noktası düşüş hızı","dew-point lapse rate","Γdp"],"tanim":["Yükselen doymamış bir hava parselinde su buharı karışma oranı korunurken basınç azalması sebebiyle çiy noktasının düşme oranıdır.","Birimi K/km olup atmosferik koşullarda tipik değeri yaklaşık 1,8 K/km olarak hesaplanır.","Kuru adyabatik azalma oranıyla birlikte bulut tabanı formülünün paydasındaki 8 K/km farkı ve 125 m katsayısını belirler."],"tanim_en":"The rate of decrease of dew point temperature with height in a rising unsaturated air parcel at constant mixing ratio.","bag":{"kavram":["lcl"],"soru":["S11"],"hesap":["lcl"]}},{"id":"dry-adiabatic-lapse-rate","tr":"Kuru adyabatik azalma oranı","en":"dry adiabatic lapse rate","kisa":"Γd","tur":"olcu","es":["gamma d","kuru adyabatik soğuma oranı","kuru adyabatik dikey sıcaklık gradyanı","DALR","Γd"],"tanim":["Doymamış bir hava parselinin çevreyle ısı alışverişi yapmadan düşey doğrultuda yükselirken genleşmesi sonucu uğradığı sıcaklık azalma oranıdır.","Yerçekimi ivmesi ve kuru havanın sabit basınçtaki özgül ısısından g/cₚ bağıntısıyla hesaplanır ve yaklaşık 9,8 K/km değerini alır.","Atmosferik statik kararlılık analizlerinde ve bulut tabanı yüksekliği hesabında referans soğuma oranıdır."],"tanim_en":"The rate of temperature decrease with height for an unsaturated air parcel ascending dry-adiabatically.","bag":{"kavram":["lcl"],"soru":["S11"],"hesap":["lcl"]}},{"id":"sym-gas-constant-water-vapor","tr":"Su buharının gaz sabiti","en":"gas constant for water vapour","kisa":"R_v","tur":"olcu","es":["su buharı gaz sabiti","Rv","R_v"],"tanim":["Evrensel gaz sabitinin suyun mol kütlesine bölünmesiyle elde edilen özgül gaz sabitidir.","Değeri 461,5 J kg⁻¹ K⁻¹ olup kuru havanın özgül gaz sabitinden belirgin biçimde büyüktür.","Clausius–Clapeyron denkleminde ve atmosferdeki su buharı doygunluk basıncı ile çiy noktası değişim hesaplarında kullanılır."],"tanim_en":"The specific gas constant for water vapor, defined as the universal gas constant divided by the molar mass of water.","bag":{"kavram":["lcl","clausius"],"soru":[],"hesap":["clausius"]}},{"id":"peroxy-radical","tr":"Peroksi radikali","en":"peroxy radical","kisa":"HO₂, RO₂","tur":"kavram","es":["RO2","alkilperoksi","peroksil radikalleri","Organik peroksil radikalleri","Organic peroxy radicals","organik peroksi radikali"],"tanim":["Yapısında bir peroksi grubu taşıyan hidroperoksil (HO₂) ve organik peroksil (RO₂) yapılı serbest radikallerdir.","Uçucu organik bileşiklerin ve karbon monoksitin hidroksil radikaliyle yükseltgenmesi sürecinde oluşur.","NO türünü ozon harcamadan NO₂ türüne dönüştürerek fotodurağan dengedeki NO₂/NO oranını ve troposferik ozon üretimini artırır."],"tanim_en":"A radical species containing the peroxy functional group, generated by hydrocarbon oxidation and driving photochemical ozone production.","bag":{"kavram":["leighton"],"soru":["S44"],"hesap":[]}},{"id":"excited-atomic-oxygen","tr":"Uyarılmış oksijen atomu","en":"excited oxygen atom","kisa":"O(¹D)","tur":"kavram","es":["uyarılmış O atomu","singlet oksijen atomu","O(¹D)","O(1D)"],"tanim":["Ozonun morötesi ışınımla fotolizi sonucu oluşan, taban durumundaki oksijen atomundan daha yüksek elektronik enerjiye sahip kararsız reaktif oksijen türü.","Kimyasal sembolü O(¹D) olup atmosferde saniyenin küçük bir kesri kadar yaşar; ortamdaki gaz molekülleriyle çarpışarak söner ya da su buharıyla tepkir.","Su buharı (H₂O) ile tepkimeye girerek troposferin deterjanı sayılan hidroksil radikalini (OH) üreten temel kimyasal kaynaktır."],"tanim_en":"O(¹D) is an electronically excited oxygen atom formed by ozone photolysis at short UV wavelengths; its reaction with water vapor is the main source of tropospheric OH.","bag":{"kavram":["omur","fotoliz"],"soru":[],"hesap":[]}},{"id":"mixing-time","tr":"Karışma süresi","en":"mixing time","kisa":"","tur":"kavram","es":["karışma zaman ölçeği","yarımküreler arası karışma süresi","mixing timescale","interhemispheric mixing time"],"tanim":["Atmosfere salınan bir iz gazın ya da kirleticinin belirli bir atmosfer hacminde hava hareketleriyle homojen dağılıma ulaşması için gereken karakteristik zaman ölçeği.","Tipik değerleri sınır tabakasında saatler ile günler, yarımküre içinde 1–2 ay, yarımküreler arasında ise yaklaşık 1 yıldır.","Bir gazın ortalama ömrü bu süreyle karşılaştırılarak gazın homojen ya da bölgesel değişken olup olmadığı saptanır."],"tanim_en":"The characteristic timescale required for an emitted tracer to become uniformly distributed throughout an atmospheric domain.","bag":{"kavram":["omur","atmosfer-kutlesi"],"soru":["S38"],"hesap":[]}},{"id":"sink","tr":"Yutak","en":"sink","kisa":"L","tur":"kavram","es":["kayıp","kayıp süreci","giderim süreci","removal process","loss"],"tanim":["Bir kimyasal türü atmosferden kimyasal dönüşüm, kuru çökelme, ıslak çökelme ya da diğer küresel rezervuarlara aktarım yoluyla uzaklaştıran süreç veya mekanizma.","Kayıp hızı L = M/τ bağıntısıyla belirlenir; birden çok yutak varlığında toplam kayıp hızı bağımsız yutak hızlarının toplamına eşittir.","Bir kirleticinin ya da sera gazının atmosferdeki kalıcılığını ve denge yükünü doğrudan kontrol eder."],"tanim_en":"A sink is a process or mechanism by which a trace substance is removed from the atmosphere.","bag":{"kavram":["omur","kutu-modeli"],"soru":["S37","S39","S42"],"hesap":[]}},{"id":"source","tr":"Kaynak","en":"source","kisa":"E","tur":"kavram","es":["salım kaynağı","emisyon kaynağı","kaynak terimi","source term"],"tanim":["Atmosfere doğrudan salım (emisyon) veya atmosfer içi kimyasal tepkimeler yoluyla madde kazandıran süreç, alan veya mekanizma.","Doğal (biyojenik, volkanik, denizel) ve insan kaynaklı (antropojenik) olmak üzere ikiye ayrılır; kütle akısı kütle/zaman (Tg/yıl) birimiyle ölçülür.","Atmosferik kütle bütçesinde gaz ve aerosollerin birikimini başlatan temel girdidir."],"tanim_en":"A mechanism, area, or reaction adding a chemical constituent to the atmosphere.","bag":{"kavram":["omur","kutu-modeli"],"soru":["S2","S3","S5","S9","S11","S12"],"hesap":["omur-denge"]}},{"id":"steady-state","tr":"Kararlı hâl (denge)","en":"steady state","kisa":"","tur":"kavram","es":["kararlı durum","durağan hâl"],"tanim":["Açık bir sistemde toplam kaynak akısının toplam yutak akısına eşit olduğu ve toplam kütlenin zamanla değişmediği (dM/dt = 0) dinamik durum.","Bu dengede atmosferik yük M = E × τ formülüyle verilir ve kalış süresi sistemdeki ortalama ömre eşit olur.","Statik kimyasal dengeden farklı olarak madde girişi ve çıkışı devam ederken derişimin sabit kalmasını ifade eder."],"tanim_en":"A dynamic condition of an atmospheric system where total input rate equals total removal rate so that the total burden remains constant over time.","bag":{"kavram":["omur","kutu-modeli","kutle-derisimi"],"soru":["S5","S6","S7","S8","S9","S10"],"hesap":["omur-denge","kutu-modeli"]}},{"id":"variable-gas","tr":"Değişken gaz","en":"variable gas","kisa":"","tur":"kavram","es":["kısa ömürlü gaz","heterojen dağılımlı gaz","değişken bileşen","variable trace constituent"],"tanim":["Atmosferdeki ortalama ömrü atmosferik karışma süresinden daha kısa olan ve bu nedenle derişimi mekâna ve zamana göre büyük farklılık gösteren gaz türü.","Karışım oranı homojen değildir; emisyon kaynaklarının, kimyasal üretim bölgelerinin ve mevsimsel koşulların doğrudan izini taşır.","Karbon monoksit ve azot oksitler gibi türler bu sınıfta yer alır ve tek bir yüzey ölçümü tüm atmosfer sütununu temsil edemez."],"tanim_en":"An atmospheric trace constituent whose lifetime is shorter than the mixing timescale, resulting in strong spatial variability.","bag":{"kavram":["omur"],"soru":["S36","S38"],"hesap":[]}},{"id":"e-folding-time","tr":"E-katlanma süresi","en":"e-folding time","kisa":"τ","tur":"olcu","es":["e-katlanma zamanı","1/e süresi","karakteristik zaman","e-folding timescale"],"tanim":["Bir büyüklüğün genliğinin ya da miktarının e kat artması veya 1/e oranına (yaklaşık %37) inmesi için gereken süre.","Atmosfer kimyasında birinci mertebe üstel sönüm gösteren bir türün ömrüne (τ) eşittir: M = M₀ e^(−t/τ).","Birinci mertebe kimyasal kayıpta τ = 1/k bağıntısıyla ifade edilir ve yarı ömrün yaklaşık 1,44 katına karşılık gelir."],"tanim_en":"The e-folding time is the time in which an exponentially changing quantity changes by a factor of e; in decay it falls to 1/e (about 37 %) of its initial value.","bag":{"kavram":["omur","ustel","volkan-aerosol"],"soru":["S31","S36"],"hesap":["sonum","omur-denge"]}},{"id":"half-life","tr":"Yarı ömür","en":"half-life","kisa":"t₁/₂","tur":"olcu","es":["yarılanma süresi","yarılanma ömrü","t½"],"tanim":["Bir maddenin miktarının ya da radyoaktif aktivitesinin başlangıç değerinin yarısına (%50) inmesi için gereken süre.","Birinci mertebe kinetik bozunmada t½ = τ ln 2 ≈ 0,693 τ formülüyle hesaplanır.","Radyoaktif izleyicilerde yaygın kullanılırken, atmosfer kimyasında üstel azalmalar için çoğunlukla e-katlanma süresi (ömür) tercih edilir."],"tanim_en":"The time required for the amount or activity of a substance to decrease to one-half of its initial value.","bag":{"kavram":["ustel","omur","volkan-aerosol"],"soru":[],"hesap":["sonum"]}},{"id":"lifetime-against-oh","tr":"OH'ye karşı ömür","en":"lifetime against OH","kisa":"τ_OH","tur":"olcu","es":["OH ömrü","hidroksil ömrü","tau_OH","OH ile kayıp ömrü"],"tanim":["Atmosferdeki bir gaz türünün hidroksil radikali (OH) ile girdiği kimyasal tepkimeyle tüketilmesine karşılık gelen ortalama kalış süresi.","Sözde birinci mertebe kayıp yaklaşımıyla τ = 1/(k[OH]) formülüyle hesaplanır; zaman birimi olarak saniye veya yıl kullanılır.","Metan ve karbon monoksit gibi sera gazları ile kirleticilerin troposferden temizlenme hızını ve küresel yayılımını belirler."],"tanim_en":"The lifetime against OH is the chemical lifetime of a trace gas set by its reaction with the hydroxyl radical, τ = 1/(k[OH]).","bag":{"kavram":["omur","arrhenius"],"soru":["S37","S38"],"hesap":["arrhenius","omur-denge"]}},{"id":"loss-rate","tr":"Kayıp hızı","en":"loss rate","kisa":"L","tur":"olcu","es":["kayıp oranı","yutak hızı","giderim hızı","removal rate"],"tanim":["Bir kimyasal türün kimyasal tepkime, çökelme ya da taşınım yoluyla atmosferden birim zamanda uzaklaştırılan toplam miktarıdır.","Birinci mertebe uzaklaşma süreçlerinde L = M / τ bağıntısıyla verilir; birimi genellikle Tg/yıl olarak ifade edilir.","Kutu modellerinde kaynak terimiyle dengelenerek kararlı hâl atmosferik yükünü ve türün kalış süresini belirler."],"tanim_en":"The total amount of an atmospheric chemical constituent removed per unit time by chemical reaction or deposition.","bag":{"kavram":["omur","kutu-modeli"],"soru":["S36","S37","S38","S41"],"hesap":["omur-denge"]}},{"id":"parallel-sinks","tr":"Paralel yutaklar","en":"parallel sinks","kisa":"","tur":"surec","es":["birden çok yutak","çoklu yutak","eşzamanlı yutaklar","multiple sinks"],"tanim":["Atmosferdeki bir kimyasal türün aynı anda birden fazla bağımsız kayıp yoluyla (örneğin fotoliz, OH tepkimesi ve kuru çökelme) atmosferden uzaklaştırılması süreci.","Toplam kayıp hızı tekil kayıp hızlarının toplamına eşit olup toplam ömür terslerin toplamı kuralıyla 1/τ = Σ (1/τᵢ) şeklinde hesaplanır.","Sisteme eklenen her yeni paralel kayıp kanalı toplam temizlenme hızını artırdığı için türün atmosferdeki toplam ömrünü kısaltır."],"tanim_en":"Parallel sinks are independent loss pathways acting at the same time on a species; their loss rates add, so 1/τ = Σ 1/τᵢ.","bag":{"kavram":["omur"],"soru":["S37"],"hesap":[]}},{"id":"second-order-reaction","tr":"İkinci mertebe tepkime","en":"Second-order reaction","kisa":"","tur":"surec","es":["ikinci mertebe kinetik","bimoleküler tepkime","ikinci dereceden tepkime"],"tanim":["Tepkime hızının iki ayrı türün derişimlerinin çarpımıyla veya tek bir türün derişiminin karesiyle orantılı olduğu kimyasal tepkime.","Hız ifadesi hız = k[A][B] şeklinde olup ikinci mertebe hız sabitinin birimi cm³ molekül⁻¹ s⁻¹ veya L mol⁻¹ s⁻¹ olarak verilir.","Troposferde CH₄ + OH ve CO + OH gibi hidroksil radikalinin yönlendirdiği temel gaz fazı arınma döngülerinin kinetiğini açıklar."],"tanim_en":"A chemical reaction whose rate is proportional to the product of the concentrations of two reacting chemical species.","bag":{"kavram":["omur","arrhenius"],"soru":[],"hesap":[]}},{"id":"pseudo-first-order","tr":"Sözde birinci mertebe","en":"pseudo-first-order reaction","kisa":"k'","tur":"yontem","es":["yalancı birinci mertebe","pseudo-first-order kinetics","sözde birinci derece","sözde birinci mertebe tepkime"],"tanim":["İkinci veya daha yüksek mertebeden bir tepkimede tepkenlerden birinin derişiminin sabit kalmasıyla tepkimenin matematiksel olarak birinci mertebe gibi davrandığı kinetik yaklaşım.","İkinci mertebe hız sabiti k ile sabit kabul edilen reaktifin derişimi çarpılarak k' = k[X] şeklinde s⁻¹ biriminde yalancı hız sabiti elde edilir.","Atmosferde hidroksil radikali veya ozon derişimi sabit kabul edildiğinde iz gazların ömrünü τ = 1/k' biçiminde analitik olarak hesaplamayı sağlar."],"tanim_en":"A pseudo-first-order reaction is a bimolecular reaction treated as first order because one reactant (e.g. OH) stays nearly constant, giving k' = k[X] in s⁻¹.","bag":{"kavram":["omur","titrasyon"],"soru":[],"hesap":["omur-denge","arrhenius"]}},{"id":"alveolar-region","tr":"Alveol bölgesi","en":"alveolar region","kisa":"","tur":"kavram","es":["alveoller","hava kesecikleri","alveoli","pulmonary region"],"tanim":["İnsan solunum sisteminde gaz alışverişinin gerçekleştiği, alveol adı verilen kılcal hava keseciklerinden oluşan en derin pulmoner bölge.","Üst solunum yollarında tutulamayan aerodinamik çapı 2,5 µm altındaki ince parçacıklar ve difüzyon ile taşınan nano parçacıklar buraya ulaşır.","En ince parçacıklar alveol çeperinden kana geçebilir; bu yüzden buraya ulaşan ince ve çok ince parçacıklar en yüksek sağlık riskini taşır."],"tanim_en":"The deepest pulmonary zone containing tiny air sacs where blood oxygenation occurs and fine inhaled particles can penetrate.","bag":{"kavram":["pm"],"soru":["S19","S20"],"hesap":[]}},{"id":"exceedance","tr":"Sınır aşımı","en":"exceedance","kisa":"","tur":"kavram","es":["eşik aşımı","standart aşımı","limit aşımı","threshold exceedance"],"tanim":["Bir hava kirleticisinin ölçülen derişiminin yasal olarak belirlenmiş çevre ve hava kalitesi sınır değerini veya eşiğini geçtiği durum.","Belirli bir zaman aralığı (örneğin 24 saatlik ya da yıllık ortalama) için tanımlanır ve mevzuat standartlarına göre olay sayısı olarak sayılır.","Toplum sağlığını koruma hedefiyle kirlilik düzeyini denetlemek, erken uyarı yayımlamak ve mevzuat uyumunu izlemek amacıyla takip edilir."],"tanim_en":"An event wherein the measured concentration of an atmospheric pollutant is higher than a legally established air quality limit.","bag":{"kavram":["pm"],"soru":["S19"],"hesap":[]}},{"id":"london-smog","tr":"Londra tipi smog","en":"London smog","kisa":"","tur":"kavram","es":["Londra dumanı","kükürtlü duman","kış tipi smog","dumanlı sis","Büyük Londra Dumanı","sulfurous smog"],"tanim":["Kömür yanmasından çıkan kükürt dioksit (SO₂) ile is parçacıklarının kış aylarında sis ve sıcaklık terselmesi altında birikmesiyle oluşan asidik kirlilik tabakasıdır.","Birincil kirleticiler SO₂ ve is olup, atmosferik nemle sülfürik asit (H₂SO₄) aerosollerine dönüşerek asitliği artırır ve görüş mesafesini düşürür.","Durgun hava koşullarında karışma yüksekliğinin düşmesiyle kirletici derişimi katlanarak ciddi solunum yolu sorunlarına yol açar."],"tanim_en":"A type of air pollution formed during cold winter conditions when sulfur dioxide and soot from coal combustion accumulate under a temperature inversion with fog.","bag":{"kavram":["pm","asit-yagmuru","kutu-modeli"],"soru":["S39"],"hesap":[]}},{"id":"photochemical-smog","tr":"Fotokimyasal duman (smog)","en":"photochemical smog","kisa":"","tur":"kavram","es":["smog","fotokimyasal sis","Los Angeles tipi duman","yaz dumanı","oxidizing smog"],"tanim":["Güneşten gelen morötesi ışınımın azot oksitler (NOₓ) ve uçucu organik bileşiklerle (VOC) tepkimeye girmesi sonucu oluşan yükseltgeyici hava kirliliği karışımıdır.","VOC yükseltgenmesinden doğan peroksi radikalleri NO'yu ozon harcamadan NO₂'ye çevirir, böylece ozon birikir; başlıca bileşenleri O₃, PAN ve ikincil aerosollerdir.","Güneşli ve sıcak yaz günlerinde sıcaklık terselmesi altında birikerek görüşü azaltır, göz ve solunum yolu tahrişine yol açar."],"tanim_en":"An atmospheric pollution mixture formed when solar ultraviolet radiation drives photochemical reactions between nitrogen oxides and volatile organic compound molecules to produce ozone and peroxyacetyl nitrate.","bag":{"kavram":["pm","titrasyon","kutu-modeli"],"soru":["S43","S44"],"hesap":[]}},{"id":"temperature-inversion","tr":"Sıcaklık terselmesi","en":"temperature inversion","kisa":"","tur":"kavram","es":["inversiyon","enverziyon","terselme tabakası","inversion"],"tanim":["Troposferde normalde yükseklikle azalan hava sıcaklığının, belirli bir katmanda yükseklikle artması durumudur.","Düşey kararlılığı artırarak düşey karışmayı engeller; terselmenin tabanı şehir kutu modelindeki karışma yüksekliğini (h) belirler.","Yüzeyden salınan kirleticilerin dar bir hacme hapsolmasına ve hava kalitesinin hızla bozulmasına yol açar."],"tanim_en":"An atmospheric layer wherein air temperature climbs with altitude, suppressing vertical mixing and trapping air pollutants near the ground.","bag":{"kavram":["pm","kutu-modeli","aerosol-dogrudan"],"soru":["S25","S39"],"hesap":[]}},{"id":"aerodynamic-diameter","tr":"Aerodinamik çap","en":"aerodynamic diameter","kisa":"D_a","tur":"olcu","es":["aerodinamik parçacık çapı","aerodinamik eşdeğer çap","aerodynamic equivalent diameter"],"tanim":["Bir parçacıkla aynı çökelme hızına sahip, yoğunluğu 1 g/cm³ olan küresel parçacığın çapıdır.","Durgun havada yerçekimi etkisiyle Stokes çökelme hızı bağıntısı üzerinden tanımlanır ve parçacığın geometrik çapı ile yoğunluğunun kareköküne bağlıdır.","Hava kalitesi standartlarında PM2.5 ve PM10 sınır değerleri ile solunum sisteminde tutulum bölgeleri doğrudan bu çap büyüklüğüyle belirlenir."],"tanim_en":"The diameter of a standard sphere of unit density that has the same settling velocity as the given particle.","bag":{"kavram":["pm","stokes"],"soru":["S16"],"hesap":["stokes"]}},{"id":"impaction","tr":"Eylemsizlikle çarpma","en":"inertial impaction","kisa":"","tur":"surec","es":["ataletsel çarpma","eylemsizlik çarpması"],"tanim":["Hava akım çizgilerinin yön değiştirdiği kıvrımlarda, yüksek eylemsizliğe sahip parçacıkların akımı izleyemeyip bir yüzeye çarparak tutulması süreci.","Parçacığın aerodinamik çapı ve akış hızı büyüdükçe çarpma verimi yükselir; solunum sisteminde özellikle 5 µm üzerindeki parçacıklarda baskındır.","Kaba parçacıkların burun ve üst solunum yolunda tutulmasını sağlayarak derin akciğer dokularına ulaşmasını sınırlar."],"tanim_en":"A deposition mechanism where aerosol particles with high inertia fail to follow curved streamlines and collide with an obstacle or airway surface.","bag":{"kavram":["pm"],"soru":["S20"],"hesap":[]}},{"id":"respiratory-deposition","tr":"Solunum yolunda birikme","en":"respiratory deposition","kisa":"","tur":"surec","es":["akciğerde birikme","solunumsal tutulma","solunum yolu tutulumu","lung deposition"],"tanim":["Solunan havadaki aerosol parçacıklarının aerodinamik çaplarına bağlı olarak burun, trakea, bronşlar ve alveol bölgelerinde tutulup birikmesi sürecidir.","İri parçacıklar (çap > 2,5 µm) burun ve üst yolda eylemsizlikle tutulur; çok ince parçacıklar (≈ 0,02 µm) difüzyonla alveollere çöker; ≈ 0,5 µm çevresindekiler en az tutulur, çoğu geri solunur.","Tutulum derinliği parçacığın toksik etkisini ve hava kalitesi sınır değerlerinin belirlenmesini doğrudan denetler."],"tanim_en":"The process by which inhaled aerosol particles are retained within different regions of the human respiratory tract depending on aerodynamic diameter.","bag":{"kavram":["pm"],"soru":["S16","S19","S20"],"hesap":[]}},{"id":"active-chlorine","tr":"Aktif klor","en":"active chlorine","kisa":"ClOₓ","tur":"kavram","es":["reaktif klor","reactive chlorine","ClOx","klor radikalleri","reaktif klor ailesi","reactive chlorine family"],"tanim":["Stratosferde ozonu katalitik olarak doğrudan parçalama yeteneğine sahip klor atomu (Cl) ve klor monoksit (ClO) radikallerinin ortak sınıfı.","Kutup kışında rezervuar klorun heterojen tepkimelerle dönüştüğü öncüllerin, ilkbaharda güneş ışığı altında fotolize uğramasıyla ortaya çıkar.","Tek bir aktif radikal, kararlı bir rezervuara bağlanana kadar binlerce ozon molekülünü yok ederek ozon tabakasında belirgin incelmeye neden olur."],"tanim_en":"Highly reactive stratospheric chlorine radicals, predominantly atomic chlorine and chlorine monoxide, that catalytically break down ozone.","bag":{"kavram":["psc","katalitik"],"soru":["S32","S42"],"hesap":[]}},{"id":"chlorine-monoxide","tr":"Klor monoksit","en":"chlorine monoxide","kisa":"ClO","tur":"kavram","es":["ClO","ClO radikali","klor monoksit radikali","chlorine monoxide radical"],"tanim":["Kimyasal formülü ClO olan ve stratosferik klor döngüsünde anahtar ara ürün rolü üstlenen eşleşmemiş elektronlu bir radikaldir.","Klor atomunun ozonla tepkimesinden meydana gelir ve atomik oksijen veya ikinci bir ClO molekülüyle tepkimeye girerek döngüyü sürdürür.","Kutup ilkbaharında stratosferde yüksek derişimlerde saptanması klor aktivasyonunun ve ozon incelmesinin doğrudan kanıtıdır."],"tanim_en":"A reactive radical intermediate with formula ClO that plays a key role in stratospheric ozone destruction.","bag":{"kavram":["psc","katalitik"],"soru":["S32","S42"],"hesap":[]}},{"id":"chlorine-nitrate","tr":"Klor nitrat","en":"chlorine nitrate","kisa":"ClONO₂","tur":"kavram","es":["ClONO2","ClONO₂","klor mononitrat","chlorine(I) nitrate"],"tanim":["Stratosferde klor monoksit (ClO) ile azot dioksitin (NO₂) üç cisimli tepkimesiyle oluşan kararlı bir rezervuar moleküldür (ClONO₂).","Klor radikalini bağlı tutarak ozon tüketimini geçici olarak durdurur ve HCl ile birlikte stratosferdeki pasif klor deposunu oluşturur.","Kutup kışında kutup stratosfer bulutları üzerinde hidrojen klorürle heterojen tepkimeye girerek serbest klor (Cl₂) oluşumunu sağlar."],"tanim_en":"A stable stratospheric reservoir molecule with chemical formula ClONO₂ formed by the reaction of chlorine monoxide with nitrogen dioxide.","bag":{"kavram":["psc","katalitik"],"soru":["S32","S42"],"hesap":[]}},{"id":"hydrogen-chloride","tr":"Hidrojen klorür","en":"hydrogen chloride","kisa":"HCl","tur":"kavram","es":["hidroklorik asit gazı","HCl"],"tanim":["Klor radikalinin metanla (CH₄) tepkimesi sonucu oluşan ve stratosferdeki toplam inorganik klorun en büyük bölümünü tutan temel rezervuar gaz molekülüdür (HCl).","Gaz fazında ozona karşı kimyasal olarak etkisizdir ve kloru bağlı tutarak katalitik ozon bozum döngüsünü sonlandırır.","Kutup kışında kutup stratosfer bulutlarının buz ve NAT yüzeylerinde klor nitratla heterojen tepkimeye girerek aktif kloru açığa çıkarır."],"tanim_en":"The predominant inorganic chlorine reservoir molecule in the stratosphere with chemical formula HCl, formed primarily by the reaction of atomic chlorine with methane.","bag":{"kavram":["psc","katalitik"],"soru":["S32","S42"],"hesap":[]}},{"id":"molecular-chlorine","tr":"Moleküler klor","en":"molecular chlorine","kisa":"Cl₂","tur":"kavram","es":["klor gazı","Cl2","diklor","Cl₂"],"tanim":["İki klor atomunun kovalent bağla birleştiği, standart koşullarda sarımsı yeşil renkli gaz hâlinde bulunan diatomik molekül (Cl₂).","Kutup kışında kutup stratosfer bulutları üzerinde HCl ve ClONO₂ arasındaki heterojen tepkimeyle gaz fazında üretilir ve karanlıkta birikir.","İlkbaharda güneşin doğuşuyla birlikte görünür ve yakın morötesi ışığı soğurarak hızla fotoliz olur ve serbest klor atomları üretir."],"tanim_en":"A diatomic halogen molecule that accumulates during the dark polar winter and undergoes photolysis in spring to form reactive chlorine atoms.","bag":{"kavram":["psc","fotoliz","katalitik"],"soru":["S32"],"hesap":[]}},{"id":"nitric-acid-trihydrate","tr":"Nitrik asit trihidrat","en":"nitric acid trihydrate","kisa":"","tur":"kavram","es":["NAT","HNO₃·3H₂O","tip I PSC parçacığı","nitric acid hydrate"],"tanim":["Kutup stratosferinde yaklaşık 195 K (−78 °C) sıcaklık eşiğinde nitrik asit ve su buharının birlikte yoğuşmasıyla oluşan kristal bileşiktir (HNO₃·3H₂O).","Tip I kutup stratosfer bulutlarının (PSC) başlıca katı bileşenidir; buz PSC'lerinin (tip II) oluştuğu sıcaklıktan birkaç derece daha yüksekte kararlıdır.","Kristal yüzeyinde klor rezervuarlarını aktifleştiren heterojen tepkimelere zemin hazırlar ve yerçekimsel çökelmeyle denitrifikasyona yol açar."],"tanim_en":"A crystalline solid compound with chemical formula HNO₃·3H₂O that forms the primary constituent of Type I polar stratospheric cloud particles at temperatures below approximately 195 K.","bag":{"kavram":["psc"],"soru":[],"hesap":[]}},{"id":"reservoir-species","tr":"Rezervuar tür","en":"reservoir species","kisa":"","tur":"kavram","es":["klor deposu","depo tür","chlorine reservoir","rezervuar molekül","klor rezervuarı","rezervuar moleküller"],"tanim":["Atmosferdeki etkin radikalleri bünyesine bağlayarak geçici süreyle etkisiz tutan nispeten kararlı ve uzun ömürlü moleküldür.","Stratosferde klorun büyük bölümü gaz fazında birbiriyle yavaş tepkiyen HCl ve ClONO₂ rezervuarları içinde bulunur.","Kutup stratosfer bulutlarının yüzeyinde gerçekleşen heterojen tepkimeler bu depoları kırarak aktif klor gazına dönüştürür."],"tanim_en":"A relatively stable atmospheric compound that temporarily binds reactive radicals into an unreactive form.","bag":{"kavram":["psc","katalitik","kutu-modeli"],"soru":["S32","S42"],"hesap":[]}},{"id":"catalytic-cycle","tr":"Katalitik döngü","en":"catalytic cycle","kisa":"","tur":"surec","es":["katalitik ozon bozumu","katalitik çevrim","katalitik zincir","katalitik zincir uzunluğu","Zincir uzunluğu","Chain length"],"tanim":["Bir katalizörün ardışık kimyasal tepkime basamaklarıyla reaktantları dönüştürüp başlangıçtaki etkin hâline geri döndüğü kapalı tepkime dizisidir.","Stratosferde X + O₃ → XO + O₂ ve XO + O → X + O₂ adımlarıyla net olarak O₃ + O → 2O₂ yıkımını gerçekleştirir.","Zincir uzunluğu, katalizör bir rezervuar türe (HCl, ClONO₂) bağlanmadan önce döngünün kaç kez döndüğüdür; tek bir Cl atomu ≈ 10⁵ O₃ molekülü bozabilir."],"tanim_en":"A catalytic cycle is a closed sequence of reaction steps in which a catalyst is regenerated while reactants are converted into products; in the stratosphere its net result is O₃ + O → 2O₂.","bag":{"kavram":["psc","katalitik","chapman"],"soru":["S32","S41","S42"],"hesap":[]}},{"id":"clo-dimer-cycle","tr":"ClO dimer döngüsü","en":"ClO dimer cycle","kisa":"","tur":"surec","es":["ClO dimer mekanizması","Cl₂O₂ döngüsü","dimer cycle","Molina döngüsü"],"tanim":["Kutup alt stratosferinde atomik oksijene gereksinim duymadan iki ozon molekülünü parçalayan katalitik fotokimyasal mekanizma.","İki ClO radikalinin birleşerek Cl₂O₂ dimerini oluşturması, dimerin morötesi ışıkla fotolizi ve ardından ClOO yapısının bozunması adımlarıyla işler.","Kutup girdabı içindeki düşük sıcaklıklarda Antarktika ozon deliğindeki net ozon yıkımının büyük bölümünden sorumludur."],"tanim_en":"A catalytic cycle involving the formation and photolysis of a Cl₂O₂ dimer that enables rapid ozone destruction in the polar stratosphere without atomic oxygen.","bag":{"kavram":["psc"],"soru":[],"hesap":[]}},{"id":"denitrification","tr":"Denitrifikasyon","en":"denitrification","kisa":"","tur":"surec","es":["azot uzaklaşması","stratosferik denitrifikasyon","azot yitimi","stratospheric denitrification"],"tanim":["Stratosferde nitrik asit trihidrat (NAT) içeren kutup stratosfer bulutu parçacıklarının yerçekimiyle çökerek reaktif azotu alt katmanlara taşıması ve ortamdan uzaklaştırması sürecidir.","Biyogeokimyada nitratın bakterilerce gaz hâlindeki N₂O ve N₂'ye indirgenmesini ifade ederken, atmosfer kimyasında gaz fazı reaktif azot (NOy) kaybını anlatır.","Ortamdaki NO₂ derişimini düşürerek serbest klor radikallerinin yeniden ClONO₂ rezervuarına bağlanmasını engeller ve ilkbaharda ozon bozum süresini uzatır."],"tanim_en":"The irreversible removal of reactive nitrogen from the polar stratosphere through gravitational sedimentation of nitric acid trihydrate cloud particles.","bag":{"kavram":["psc"],"soru":[],"hesap":[]}},{"id":"heterogeneous-reaction","tr":"Heterojen tepkime","en":"heterogeneous reaction","kisa":"","tur":"surec","es":["heterojen yüzey tepkimesi","yüzey tepkimesi","heterojen reaksiyon","heterojen tepkime","heterojen kimyasal tepkime","heterogeneous chemical reaction"],"tanim":["Farklı fiziksel fazlardaki bileşenler arasında, özellikle katı veya sıvı aerosol parçacıklarının yüzeyinde ya da içinde gerçekleşen kimyasal tepkimedir.","Gaz fazında aktivasyon enerjisi çok yüksek olan ve yavaş ilerleyen tepkimeler, aerosol yüzeyinin katalitik etkisiyle kat kat hızlanır.","Stratosferde PSC ve volkanik sülfat parçacıkları üzerinde klor rezervuarlarını aktif klora dönüştürerek ozon incelmesini hızlandırır."],"tanim_en":"A chemical reaction that occurs between reactants of differing physical phase, particularly on the surface or interior of atmospheric aerosol particles.","bag":{"kavram":["psc","volkan-aerosol"],"soru":["S32"],"hesap":[]}},{"id":"ozone-depletion","tr":"Ozon incelmesi","en":"ozone depletion","kisa":"","tur":"surec","es":["ozon kaybı","ozon tahribatı","ozone loss"],"tanim":["Stratosferik ozon tabakasındaki ozon derişiminin insan kaynaklı halojenli bileşikler ve katalitik tepkimelerle azalması olayıdır.","Kutup bölgelerinde kış ve ilkbahar aylarında heterojen kimyasal tepkimelerle hızlanır; küresel ölçekte sütun ozon miktarını düşürür.","Zararlı morötesi (UV-B) ışınımın yeryüzüne ulaşmasını artırarak biyosfer ve iklim sistemi üzerinde olumsuz etkiler doğurur."],"tanim_en":"The reduction of stratospheric ozone concentration caused by anthropogenic halogen compounds and catalytic reaction cycles.","bag":{"kavram":["psc","volkan-aerosol","katalitik"],"soru":["S32","S41","S42","S43"],"hesap":[]}},{"id":"unit-hectopascal","tr":"Hektopaskal","en":"hectopascal","kisa":"hPa","tur":"birim","es":["hPa","milibar","mbar"],"tanim":["100 paskala (10² Pa) eşit basınç birimidir; SI birimi paskalın bir katıdır.","CGS sistemindeki 1 milibara (mbar) eşittir; standart atmosfer basıncı 1013,25 hPa olarak kabul edilir.","Meteorolojide ve atmosfer kimyasında gaz yasası hesaplarında 100 ile çarpılarak paskala dönüştürülür."],"tanim_en":"A unit of atmospheric pressure equal to 100 pascals or one millibar.","bag":{"kavram":["sayi-yogunlugu","clausius","enso"],"soru":["S1","S3","S13","S35"],"hesap":[]}},{"id":"unit-kelvin","tr":"Kelvin","en":"kelvin","kisa":"K","tur":"birim","es":["K","mutlak sıcaklık birimi","kelvin unit"],"tanim":["Termodinamik ve mutlak sıcaklığın SI temel birimidir; simgesi K harfidir.","2019'dan beri Boltzmann sabitinin tam değeriyle (k_B = 1,380649 × 10⁻²³ J/K) tanımlanır; 0 °C = 273,15 K.","Atmosfer kimyası ve ışınım hesaplarında mutlak sıcaklık ölçeğidir; gaz yasası ve Stefan–Boltzmann denklemine doğrudan girer."],"tanim_en":"The kelvin is the SI base unit of thermodynamic temperature, defined since 2019 by fixing the Boltzmann constant at exactly 1.380649 × 10⁻²³ J K⁻¹.","bag":{"kavram":["sayi-yogunlugu","isinim-dengesi","stefan-boltzmann"],"soru":["S6","S7","S10","S13","S37","S40"],"hesap":[]}},{"id":"unit-molecule-cm3","tr":"Molekül bölü santimetreküp","en":"molecules per cubic centimeter","kisa":"molekül/cm³","tur":"birim","es":["molekül/cm3","molecules/cm3","molekül cm⁻³","cm⁻³"],"tanim":["Bir santimetreküp hacimdeki molekül sayısını belirten sayı yoğunluğu birimidir.","Gaz fazı atmosfer kimyası tepkimelerinde derişim birimi olarak kullanılır; kinetik hız yasalarında santimetreküp tercih edilir.","Basınç ve sıcaklığa bağlıdır; yüzeyde temiz havada sayı yoğunluğu yaklaşık 2,5 × 10¹⁹ molekül/cm³ düzeyinde bulunur."],"tanim_en":"A unit of number density expressing the number of molecules present in one cubic centimeter of air.","bag":{"kavram":["sayi-yogunlugu","boyut-modlari","twomey"],"soru":["S1"],"hesap":[]}},{"id":"hydroxyl-radical","tr":"Hidroksil radikali","en":"hydroxyl radical","kisa":"OH","tur":"kavram","es":["OH radikali","hidroksil","atmosferin deterjanı","hydroxyl"],"tanim":["Bir oksijen ve bir hidrojen atomundan oluşan, eşleşmemiş elektron taşıyan, son derece etkin yüksüz bir serbest radikaldir.","Troposferde küresel ortalama derişimi yaklaşık 10⁶ molekül/cm³ olup fotokimyasal tepkimelerle gündüz saatlerinde üretilir.","Atmosferin temel temizleyicisi olarak işlev görür; metan (CH₄), karbon monoksit (CO), SO₂ ve NO₂ gazlarının ana yutağıdır."],"tanim_en":"A highly reactive uncharged radical that acts as the primary daytime oxidizing agent in the troposphere.","bag":{"kavram":["sayi-yogunlugu","aerosol-sinif","asit-yagmuru"],"soru":["S14","S28","S33","S36","S37","S38"],"hesap":["arrhenius","omur-denge"]}},{"id":"molar-concentration","tr":"Molar derişim","en":"molar concentration","kisa":"","tur":"kavram","es":["molarite","mol/L derişimi","molarity"],"tanim":["Bir çözeltinin birim hacminde (genellikle bir litresinde) çözünmüş maddenin mol sayısını veren kimyasal derişim ölçüsüdür.","Birimi mol/L veya molarite (M) simgesiyle ifade edilir; sulu çözelti dengelerinde ve asitlik hesaplarında kullanılır.","Atmosfer kimyasında bulut, sis ve yağmur damlalarındaki sulu faz kimyasında yer alır; gaz fazındaki sayı yoğunluğundan farklıdır."],"tanim_en":"The amount of a solute in moles divided by the volume of the solution in liters.","bag":{"kavram":["sayi-yogunlugu"],"soru":[],"hesap":[]}},{"id":"stratosphere","tr":"Stratosfer","en":"stratosphere","kisa":"","tur":"kavram","es":["stratosfer tabakası","stratospheric layer"],"tanim":["Tropopoz ile stratopoz arasında yer alan, sıcaklığın yükseklikle arttığı kararlı atmosfer katmanıdır.","Yüksekliği orta enlemlerde yaklaşık 10–12 km civarından başlayıp 50 km yüksekliğe kadar uzanır.","Ozon tabakasını barındırarak zararlı morötesi güneş ışınımını soğurur; dikey hava hareketleri zayıf olduğu için buraya ulaşan volkanik aerosoller bir yılı aşan süreyle asılı kalır."],"tanim_en":"The atmospheric layer above the troposphere characterized by an increase in temperature with altitude.","bag":{"kavram":["sayi-yogunlugu","volkan-aerosol","omur"],"soru":["S1","S17","S30","S31","S32","S33"],"hesap":[]}},{"id":"bracket-concentration","tr":"Köşeli parantez derişim gösterimi","en":"bracket concentration notation","kisa":"[X]","tur":"kod","es":["sayı derişimi gösterimi","[A]","[X]"],"tanim":["Kimyasal kinetikte bir tepkimeye giren türün derişimini veya sayı yoğunluğunu simgelemek için kullanılan sembolik gösterimdir.","Gaz fazı atmosfer kinetiğinde doğrudan santimetreküpteki molekül sayısını (molekül/cm³) temsil eder; sulu çözelti kimyasında ise molar derişimi (mol/L) gösterir.","Kimyasal tepkime hız denklemlerinde çarpışma frekansını ve kinetik hız yasalarını doğrudan molekül yoğunluğu üzerinden kurmayı sağlar."],"tanim_en":"A chemical notation in which square brackets around a chemical formula denote its concentration or number density.","bag":{"kavram":["sayi-yogunlugu"],"soru":[],"hesap":[]}},{"id":"avogadro-constant","tr":"Avogadro sayısı","en":"Avogadro constant","kisa":"N_A","tur":"olcu","es":["Avogadro sabiti","Avogadro number","N_A"],"tanim":["Bir mol maddede bulunan temel tanecik (atom veya molekül) sayısını belirten temel fizikokimyasal sabittir.","SI sistemindeki değeri 6,022 × 10²³ mol⁻¹ olarak tanımlanır.","Makroskopik mol miktarları ile mikroskopik molekül sayıları arasında köprü kurar; evrensel gaz sabiti ile Boltzmann sabiti arasındaki R = N_A k_B bağıntısını sağlar."],"tanim_en":"The fundamental physical constant defining the number of constituent particles per mole of substance, equal to 6.022 × 10²³ mol⁻¹.","bag":{"kavram":["sayi-yogunlugu","fotoliz"],"soru":[],"hesap":["fotoliz"]}},{"id":"boltzmann-constant","tr":"Boltzmann sabiti","en":"Boltzmann constant","kisa":"k_B","tur":"olcu","es":["k","kB","Boltzmann katsayısı","k_B"],"tanim":["Bir gaz molekülünün ortalama termal kinetik enerjisi ile mutlak sıcaklığı arasındaki ilişkiyi kuran temel fiziksel sabittir.","SI birimi J/K olup değeri yaklaşık 1,381 × 10⁻²³ J/K olarak kabul edilir; evrensel gaz sabitinin Avogadro sabitine bölünmesiyle (k_B = R/N_A) türetilir.","Atmosfer kimyasında molekül sayı yoğunluğu (n = P / (k_B T)) hesaplarında ve kimyasal çarpışma kuramında doğrudan yer alır."],"tanim_en":"A fundamental physical constant relating the average kinetic energy of gas molecules to thermodynamic temperature.","bag":{"kavram":["sayi-yogunlugu","stefan-boltzmann"],"soru":["S1","S8"],"hesap":["sayi-yogunlugu"]}},{"id":"gas-constant","tr":"Gaz sabiti","en":"gas constant","kisa":"R","tur":"olcu","es":["evrensel gaz sabiti","ideal gaz sabiti","molar gaz sabiti","universal gas constant"],"tanim":["İdeal gaz durum denkleminde basınç, hacim, sıcaklık ve madde miktarı arasındaki bağıntıyı kuran evrensel orantı sabitidir.","Evrensel gaz sabiti (R) mol başına 8,314 J mol⁻¹ K⁻¹ olarak tanımlanır; meteorolojide birim kütle için tanımlanan kuru havanın özgül gaz sabiti ise yaklaşık 287 J kg⁻¹ K⁻¹ olarak alınır.","Atmosfer kimyasında molar hacim hesaplarında, ideal gaz dönüşümlerinde ve Arrhenius tepkime hızı denkleminde yer alır."],"tanim_en":"The fundamental proportionality constant in the ideal gas equation of state, equal to 8.314 J mol⁻¹ K⁻¹.","bag":{"kavram":["sayi-yogunlugu","kutle-derisimi","arrhenius"],"soru":["S40"],"hesap":["sayi-yogunlugu"]}},{"id":"rate-constant","tr":"Hız sabiti","en":"rate constant","kisa":"k","tur":"olcu","es":["tepkime hız sabiti","hız katsayısı","rate coefficient","k(T)"],"tanim":["Kimyasal tepkimenin hız denkleminde reaktif derişimleri ile tepkime hızı arasındaki orantı katsayısı.","Arrhenius bağıntısı uyarınca sıcaklıkla değişir; birimi tepkime mertebesine bağlı olarak s⁻¹, cm³ molekül⁻¹ s⁻¹ veya cm⁶ molekül⁻² s⁻¹ olur.","Atmosfer kimyasında iz gazların kimyasal kayıp hızını ve atmosferik ömrünü belirler."],"tanim_en":"A proportionality coefficient in a chemical rate equation that depends on temperature and relates the reaction rate to reactant concentrations.","bag":{"kavram":["sayi-yogunlugu","arrhenius","omur"],"soru":["S37","S38","S40","S41","S44"],"hesap":["arrhenius","chapman-o","leighton"]}},{"id":"reaction-rate","tr":"Tepkime hızı","en":"reaction rate","kisa":"v","tur":"olcu","es":["reaksiyon hızı","rate of reaction"],"tanim":["Kimyasal tepkimede birim zamanda ve birim hacimde harcanan reaktif ya da oluşan ürün miktarı.","Birim olarak genellikle molekül cm⁻³ s⁻¹ kullanılır; hız sabiti ile reaktif derişimlerinin çarpımından elde edilir.","Troposferde kirleticilerin kimyasal ömrünü ve fotokimyasal ozon üretim hızını doğrudan belirler."],"tanim_en":"The speed at which reactants convert into products in a chemical reaction per unit volume.","bag":{"kavram":["sayi-yogunlugu","arrhenius"],"soru":["S38","S40","S44"],"hesap":["sayi-yogunlugu"]}},{"id":"ideal-gas-law","tr":"İdeal gaz yasası","en":"ideal gas law","kisa":"PV = nRT","tur":"yontem","es":["ideal gaz denklemi","ideal gas equation","ideal gaz bağıntısı","ideal gaz eşitliği","PV = nRT"],"tanim":["Gaz moleküllerinin kendi hacimleri ve moleküller arası çekim kuvvetleri ihmal edildiğinde basınç, hacim, sıcaklık ve madde miktarını bağlayan durum denklemi.","PV = nRT veya sayı yoğunluğu cinsinden P = n k_B T olarak yazılır; standart koşullarda hava için yüksek doğruluk sağlar.","Atmosfer kimyasında hava yoğunluğu, molar hacim ve derişim birim dönüşümlerinin (µg/m³ ↔ ppb) temelini oluşturur."],"tanim_en":"The equation of state of a hypothetical ideal gas relating pressure, volume, temperature, and amount of substance.","bag":{"kavram":["sayi-yogunlugu","kutle-derisimi"],"soru":["S1","S2","S3"],"hesap":["sayi-yogunlugu"]}},{"id":"chlorofluorocarbon","tr":"Kloroflorokarbon","en":"chlorofluorocarbon","kisa":"CFC","tur":"kavram","es":["CFC","freon","kloroflorokarbonlar","CFC'ler"],"tanim":["Yalnız klor, flor ve karbon içeren, troposferde tepkime vermeyen ve uzun ömre sahip sentetik organik bileşik sınıfı.","Soğutucu akışkan, köpük şişirici ve itici gaz olarak üretilmiş olup atmosferik ömrü 50 ile 100 yılı bulur.","Stratosfere ulaştığında morötesi ışınımla fotolize uğrayıp klor radikalleri salarak ozon tabakasını katalitik yolla tüketir ve sera etkisi yapar."],"tanim_en":"A synthetic organic compound containing chlorine, fluorine, and carbon that depletes stratospheric ozone and acts as a potent greenhouse agent.","bag":{"kavram":["katalitik","sera-etkisi","stokiyometri"],"soru":["S42"],"hesap":["cfc-ozon"]}},{"id":"enhanced-greenhouse-effect","tr":"Artırılmış sera etkisi","en":"enhanced greenhouse effect","kisa":"","tur":"kavram","es":["insan kaynaklı sera etkisi","anthropogenic greenhouse effect"],"tanim":["Fosil yakıt tüketimi, sanayi ve arazi kullanımı değişimleriyle atmosfere salınan ek sera gazlarının doğal sera etkisini güçlendirmesi.","Yeryüzünden uzaya kaçan ısıl kızılötesi ışınımın daha büyük bölümünün atmosferce tutularak yere geri yayılmasına yol açar.","İklim sisteminde pozitif ışınımsal zorlama yaratarak küresel yüzey sıcaklığının artışına neden olur."],"tanim_en":"The additional radiative warming of Earth's surface resulting from human-induced accumulation of greenhouse gas molecules.","bag":{"kavram":["sera-etkisi"],"soru":[],"hesap":[]}},{"id":"global-warming","tr":"Küresel ısınma","en":"global warming","kisa":"","tur":"kavram","es":["küresel iklim ısınması","global climate warming"],"tanim":["Atmosferde artan sera gazı derişimlerinin yol açtığı, Dünya genelinde uzun dönemli ortalama yüzey sıcaklığı artışı.","Karasal ve denizel yüzey gözlem istasyonlarıyla ölçülür; ışınımsal zorlama ile iklim duyarlılık parametresinin çarpımından modellenir.","Buzul erimesi, deniz seviyesi yükselmesi ve ekstrem meteorolojik olayların sıklığının değişmesi gibi küresel iklim etkilerini doğurur."],"tanim_en":"The long-term upward trend in Earth's global mean surface temperature driven by human greenhouse gas emissions.","bag":{"kavram":["sera-etkisi","zorlama"],"soru":["S13"],"hesap":[]}},{"id":"greenhouse-gas","tr":"Sera gazı","en":"greenhouse gas","kisa":"GHG","tur":"kavram","es":["sera gazları","GHG","greenhouse gases"],"tanim":["Dünya yüzeyinin yaydığı ısıl kızılötesi ışınımı soğuran ve her yöne yeniden yayarak troposferin ısınmasını sağlayan atmosfer gazı.","Titreşimi sırasında dipol momenti değişen (IR aktif) moleküllerdir: H₂O, CO₂, CH₄, N₂O, O₃ ve CFC'ler; simetrik iki atomlu N₂ ve O₂ değildir.","Doğal bileşimde yeryüzünün yaşanabilir sıcaklıkta kalmasını sağlarken, insan kaynaklı artışı küresel ısınmaya yol açar."],"tanim_en":"An atmospheric gas component that absorbs and emits thermal infrared radiation within the wavelengths emitted by Earth's surface.","bag":{"kavram":["sera-etkisi","ir-aktif","omur"],"soru":["S5","S7","S13","S30","S38"],"hesap":[]}},{"id":"infrared-radiation","tr":"Kızılötesi ışınım","en":"infrared radiation","kisa":"IR","tur":"kavram","es":["IR ışınım","kızılötesi","enfraruj","IR radiation"],"tanim":["Elektromanyetik tayfta görünür ışıktan daha uzun ve mikrodalgadan daha kısa dalga boyuna sahip ışınım türü.","Dünya yüzeyi ve atmosferi tarafından tepe noktası yaklaşık 10 µm dalga boyunda yayılan ısıl ışınımdır.","Sera gazlarının titreşim kipleriyle soğurularak atmosferik sera etkisinin ve enerji bütçesinin temel bileşenini oluşturur."],"tanim_en":"Electromagnetic radiation with wavelengths between visible light and microwaves that governs planetary thermal emission.","bag":{"kavram":["sera-etkisi","ir-aktif","volkan-aerosol"],"soru":["S5","S6","S7","S8","S10","S11"],"hesap":["etkin-sicaklik","tek-katman","bulut-net"]}},{"id":"longwave-radiation","tr":"Uzun dalga ışınım","en":"longwave radiation","kisa":"LW","tur":"kavram","es":["yer ışınımı","karasal ışınım","termal kızılötesi","terrestrial radiation"],"tanim":["Dünya yüzeyi, atmosfer ve bulutlar tarafından salınan, dalga boyu genellikle 4 ile 100 µm arasında değişen ısıl kızılötesi ışınım.","Akısı Stefan–Boltzmann yasasına göre yüzey sıcaklığının dördüncü kuvvetiyle orantılıdır; uzaya giden bileşeni uydularla OLR olarak izlenir.","Gezegenin uzay ile olan ışınım dengesini kurar; atmosferdeki sera gazları ve bulutlar tarafından soğurularak yüzeyi ısıtır."],"tanim_en":"Thermal infrared radiation emitted by Earth's surface and atmosphere within the wavelength range of approximately 4 to 100 micrometers.","bag":{"kavram":["sera-etkisi","isinim-dengesi","stefan-boltzmann"],"soru":["S6","S10"],"hesap":[]}},{"id":"ozone-hole","tr":"Ozon deliği","en":"ozone hole","kisa":"","tur":"kavram","es":["Antarktika ozon deliği","Antarctic ozone hole"],"tanim":["Antarktika üzerinde güney yarım küre ilkbaharında (Eylül–Ekim) toplam sütun ozon miktarının 220 Dobson biriminin altına indiği şiddetli azalma bölgesi.","Kutup girdabı içindeki aşırı soğukta kutup stratosfer bulutları üzerinde klorun etkinleşmesi ve güneş ışığıyla başlayan katalitik tepkimelerle oluşur.","Biyolojik olarak zararlı morötesi ışınımın yeryüzüne ulaşmasını artırır; sera etkisiyle değil, stratosferik morötesi koruma kaybıyla ilgilidir."],"tanim_en":"A severe seasonal depletion of stratospheric ozone over Antarctica below 220 Dobson units driven by active chlorine radicals.","bag":{"kavram":["psc","katalitik"],"soru":["S32"],"hesap":[]}},{"id":"troposphere","tr":"Troposfer","en":"troposphere","kisa":"","tur":"kavram","es":["troposfer tabakası","troposfer katmanı","alt atmosfer"],"tanim":["Yeryüzünden başlayıp kutuplarda yaklaşık 9 km, ekvatorda yaklaşık 17 km yüksekliğe kadar uzanan ve sıcaklığın yükseklikle düzenli azaldığı alt atmosfer katmanı.","Su buharı ve sera gazlarının büyük bölümünü barındırır; uyduların algıladığı 255 K etkin ışıma sıcaklığı yaklaşık 5 km yüksekliğe denk gelir.","Hava olaylarının ve dikey karışımın gerçekleştiği alandır; aerosol parçacıkları burada gün ile hafta arasında kalır."],"tanim_en":"The troposphere is the lowest layer of the atmosphere, extending from the surface to about 9–17 km, in which temperature generally falls with height.","bag":{"kavram":["sera-etkisi","isinim-dengesi","omur"],"soru":["S3","S9","S16","S17","S30","S32"],"hesap":[]}},{"id":"ultraviolet","tr":"Morötesi (UV) ışınım","en":"ultraviolet radiation","kisa":"UV","tur":"kavram","es":["morötesi","ultraviyole","UV radiation","UV","morötesi ışınım"],"tanim":["Görünür ışıktan daha kısa, X ışınlarından daha uzun dalga boyuna (yaklaşık 100–400 nm) sahip yüksek enerjili elektromanyetik ışınım.","Güneş spektrumunun kısa dalga bölgesinde yer alır; fotokimyasal tepkimeleri ve atmosferik fotoliz süreçlerini yürütür.","Stratosferdeki ozon tabakası tarafından kuvvetle soğurularak yeryüzüne ulaşması engellenir."],"tanim_en":"High-energy electromagnetic radiation with wavelengths shorter than visible light, primarily absorbed by stratospheric ozone.","bag":{"kavram":["fotoliz","chapman"],"soru":["S42"],"hesap":[]}},{"id":"absorption-process","tr":"Soğurma","en":"absorption","kisa":"","tur":"surec","es":["absorpsiyon","ışınım soğurması","ışık soğurması","light absorption"],"tanim":["Işık enerjisinin madde ile etkileşerek ısı enerjisine ya da kimyasal potansiyel enerjiye dönüştürülmesi süreci.","Beer–Lambert bağıntısına göre soğurma kesiti ve ortamdaki molekül sayısı arttıkça geçen ışınım şiddetini üstel olarak zayıflatır.","Sera gazlarının kızılötesi ışınımı tutmasında temel süreçtir; hidrolojideki katı gözeneklerine su alma tanımından farklı olarak ışınım soğurmasını ifade eder."],"tanim_en":"The transformation of radiant energy into thermal or chemical energy through interaction with matter.","bag":{"kavram":["sera-etkisi","ir-aktif","beer-lambert"],"soru":["S5","S7","S8","S9","S10","S12"],"hesap":["optik-derinlik","beer-kesit"]}},{"id":"re-emission-process","tr":"Yeniden yayma","en":"re-emission","kisa":"","tur":"surec","es":["tekrar yayma","yeniden ışıma"],"tanim":["Soğurulan ışınım enerjisinin madde tarafından kendi sıcaklığına bağlı olarak her yöne tekrar termal ışıma biçiminde salınması süreci.","Atmosferdeki sera gazları yeryüzünden soğurdukları kızılötesi ışınımı izotropik olarak hem yukarı uzaya hem aşağı yere doğru yayar.","Yansıtma sürecinden farklı olarak foton yönü korunmaz ve salınan akı yerel termodinamik denge sıcaklığına göre belirlenir."],"tanim_en":"The isotropic release of previously absorbed radiant energy as thermal radiation determined by local temperature.","bag":{"kavram":["sera-etkisi"],"soru":[],"hesap":[]}},{"id":"runaway-greenhouse-effect","tr":"Kaçak sera etkisi","en":"runaway greenhouse effect","kisa":"","tur":"surec","es":["durdurulamayan sera etkisi","kaçak sera","kontrolden çıkan sera etkisi","runaway greenhouse"],"tanim":["Yüzey ısındıkça buharlaşan suyun (su buharı bir sera gazıdır) ışınımı daha çok tutup sıcaklığı yeniden artırdığı, durdurulamayan pozitif geri besleme döngüsüdür.","Geri besleme çarpanı f bire yaklaştığında sıcaklık artışı matematiksel olarak sonsuza yönelir ve okyanuslar bütünüyle buharlaşır.","Bugünkü Dünya'da yoğuşma ve yağış suyu yüzeye geri döndürdüğü için f < 1 kalır ve süreç kontrolden çıkmaz."],"tanim_en":"An extreme positive feedback state where greenhouse warming leads to complete ocean evaporation without reaching radiative equilibrium.","bag":{"kavram":["sera-etkisi","geri-besleme"],"soru":["S8"],"hesap":[]}},{"id":"blackbody","tr":"Siyah cisim","en":"blackbody","kisa":"","tur":"kavram","es":["kara cisim","ideal yayıcı","black body","siyah cisim ışıması"],"tanim":["Üzerine gelen her dalga boyundaki, yöndeki ve kutuplanmadaki ışınımı bütünüyle soğuran ve yayıcılığı bire (ε = 1) eşit olan ideal termal yayıcı.","Verilen bir sıcaklıkta termodinamik dengedeyken birim alandan kuramsal olarak mümkün olan en yüksek ışınım akısını yayar (F = σT⁴).","Atmosfer fiziğinde yeryüzü ve kalın bulut katmanları kızılötesi dalga boylarında siyah cisme çok yakın kabul edilir."],"tanim_en":"An ideal thermal radiator that completely absorbs all incident radiation and emits the maximum possible radiant flux at any given temperature.","bag":{"kavram":["stefan-boltzmann","isinim-dengesi"],"soru":["S5","S6","S7","S9","S10"],"hesap":[]}},{"id":"gray-body","tr":"Gri cisim","en":"gray body","kisa":"","tur":"kavram","es":["gri gövde","grey body","gri cisim ışıması"],"tanim":["Yayıcılığı ve soğurganlığı birden küçük olan ve tüm dalga boylarında sabit kalan kuramsal termal ışıyıcı.","Birim alandan yaydığı ışınım akısı Stefan–Boltzmann bağıntısına yayıcılık katsayısı eklenerek F = εσT⁴ eşitliğiyle hesaplanır.","Atmosferik katmanların dalga boyu ayrımı yapılmayan kaba ışınım dengesi hesaplarında yaklaşık model olarak kullanılır."],"tanim_en":"A theoretical radiator whose emissivity is less than unity and independent of wavelength.","bag":{"kavram":["stefan-boltzmann"],"soru":[],"hesap":[]}},{"id":"kirchhoff-s-law","tr":"Kirchhoff ışınım yasası","en":"Kirchhoff's law","kisa":"","tur":"kavram","es":["Kirchhoff yasası","Kirchhoff's law of thermal radiation","Kirchhoff ışınım ilkesi"],"tanim":["Termodinamik dengedeki bir maddenin belirli bir dalga boyu ve sıcaklıktaki yayıcılığının soğurganlığına eşit olduğunu (ε = a) belirten ilke.","Elektrik devrelerindeki akım ve gerilim yasalarından farklı olarak termal ışıma dengesini tanımlar; iyi soğurucuların aynı zamanda iyi yayıcı olduğunu gösterir.","Tek katman sera modelinde atmosferin kızılötesi soğurma kesri f ile yayıcılığının eşit (ε = f) kabul edilmesini sağlar."],"tanim_en":"A physical principle stating that for matter in thermodynamic equilibrium, spectral emissivity is equal to spectral absorptivity.","bag":{"kavram":["stefan-boltzmann","tek-katman"],"soru":[],"hesap":[]}},{"id":"radiative-flux","tr":"Işınım akısı","en":"radiative flux","kisa":"F","tur":"kavram","es":["ışınım akı yoğunluğu","radyatif akı","radiative flux density","irradiance"],"tanim":["Birim alandan birim zamanda geçen veya birim alana ulaşan elektromanyetik ışınım enerjisi büyüklüğü.","Birimi watt bölü metrekaredir (W/m²); Stefan–Boltzmann yasasında mutlak sıcaklığın dördüncü kuvvetiyle orantılı olarak belirlenir.","Atmosferin enerji dengesinde, sera etkisinin belirlenmesinde ve iklim zorlaması hesaplarında temel ölçüttür."],"tanim_en":"The amount of radiant energy transferred across a unit area per unit time, expressed in watts per square meter.","bag":{"kavram":["stefan-boltzmann"],"soru":["S6","S7"],"hesap":[]}},{"id":"emissivity","tr":"Yayıcılık","en":"emissivity","kisa":"ε","tur":"olcu","es":["emisivite","salıcılık"],"tanim":["Bir yüzeyin belirli bir sıcaklıkta yaydığı termal ışınımın, aynı sıcaklıktaki bir siyah cismin yaydığı ışınıma oranı.","Sıfır ile bir arasında boyutsuz bir değerdir; su yüzeyleri için yaklaşık 1, bitki örtüsü için 0,95–1,00 ve topraklar için 0,90–0,95 aralığında bulunur.","Kirchhoff yasası gereğince termodinamik dengede aynı dalga boyundaki soğurganlığa eşittir ve gezegenin uzun dalga enerji bütçesini kontrol eder."],"tanim_en":"The ratio of the radiant energy emitted by a surface to that emitted by a blackbody at the same temperature.","bag":{"kavram":["stefan-boltzmann","tek-katman","aerosol-dogrudan"],"soru":[],"hesap":["tek-katman"]}},{"id":"stefan-boltzmann-constant","tr":"Stefan–Boltzmann sabiti","en":"Stefan–Boltzmann constant","kisa":"σ","tur":"olcu","es":["sigma","σ"],"tanim":["Siyah cismin birim yüzeyinden yayılan toplam ışınım akısı ile mutlak sıcaklığın dördüncü kuvveti arasındaki orantı katsayısıdır.","Değeri σ ≈ 5,67 × 10⁻⁸ W m⁻² K⁻⁴ olup temel fizik sabitlerinden türer.","Atmosferik ışınım dengesi ve gezegen etkin sıcaklığı hesaplarında yüzey ile atmosferden yayılan uzun dalga akısını belirlemek için kullanılır."],"tanim_en":"A fundamental physical constant relating the total radiant flux emitted by a blackbody to the fourth power of its absolute temperature.","bag":{"kavram":["stefan-boltzmann","isinim-dengesi"],"soru":["S6","S8","S9","S10","S24","S25"],"hesap":["etkin-sicaklik"]}},{"id":"sym-planck-constant","tr":"Planck sabiti","en":"Planck constant","kisa":"h","tur":"olcu","es":["Planck katsayısı","h"],"tanim":["Elektromanyetik dalgalarda bir fotonun enerjisi ile frekansı arasındaki orantıyı kuran temel kuantum mekaniği sabitidir.","Değeri h ≈ 6,626 × 10⁻³⁴ J·s olup Planck ışınım yasasında ve Stefan–Boltzmann sabitinin türetiminde yer alır.","Atmosfer kimyasında moleküllerin fotoliz eşik dalga boylarının ve foton enerjilerinin belirlenmesinde temel rol oynar."],"tanim_en":"A fundamental physical constant that relates the energy of a single photon to its electromagnetic frequency.","bag":{"kavram":["stefan-boltzmann","fotoliz"],"soru":[],"hesap":["fotoliz"]}},{"id":"plancks-law","tr":"Planck yasası","en":"Planck's law","kisa":"B_λ(T)","tur":"yontem","es":["Planck ışınım yasası","Planck radiation formula","Planck radiation law","B_λ(T)"],"tanim":["Termodinamik dengedeki bir siyah cismin belirli bir sıcaklıkta her dalga boyunda yaydığı spektral ışınım şiddetini açıklayan temel fizik yasasıdır.","B_λ(T) spektral parlaklıktır (radyans): dalga boyuna ve mutlak sıcaklığa bağlıdır, birimi W m⁻² sr⁻¹ m⁻¹.","Tüm dalga boyları üzerinden integrali Stefan–Boltzmann yasasını, tepe noktasının türevi ise Wien kayma yasasını verir."],"tanim_en":"A physical law describing the spectral radiance emitted by a blackbody in thermal equilibrium at a given temperature.","bag":{"kavram":["stefan-boltzmann"],"soru":[],"hesap":["etkin-sicaklik"]}},{"id":"deposition-velocity","tr":"Kuru çökelme hızı","en":"deposition velocity","kisa":"v_d","tur":"kavram","es":["kuru birikme hızı","v_d"],"tanim":["Atmosferik bir kirleticinin yağış olmaksızın yeryüzüne taşınma akısının yüzey üzerindeki derişimine oranıdır.","Birimi m/s olup yerçekimsel çökmenin yanı sıra atmosferik türbülans, moleküler difüzyon ve yüzey tutunma direncini de kapsar.","Troposferdeki aerosol parçacıklarının ve iz gazların kuru yolla temizlenme hızını ve atmosferik kalış süresini hesaplamakta kullanılır."],"tanim_en":"The ratio of the downward dry deposition flux of an atmospheric pollutant to its concentration at a specified height.","bag":{"kavram":["stokes"],"soru":[],"hesap":[]}},{"id":"drag-force","tr":"Sürükleme kuvveti","en":"drag force","kisa":"","tur":"kavram","es":["sürüklenme kuvveti","direnç kuvveti","aerodinamik direnç kuvveti"],"tanim":["Akışkan içinde hareket eden bir cisme akışkan tarafından hareket doğrultusuna karşı yönde uygulanan sürtünme ve basınç kuvvetidir.","Düşük Reynolds sayılarındaki küresel aerosol parçacıkları için F_d = 3πμDv formülüyle dinamik viskozite, çap ve hız ile orantılı hesaplanır.","Düşen aerosol parçacıklarında ve damlalarda yerçekimi kuvvetini dengeleyerek ivmelenmeyi sıfırlar ve terminal hıza ulaşılmasını sağlar."],"tanim_en":"A resistive mechanical force exerted by a fluid on an object opposing its motion relative to the surrounding flow.","bag":{"kavram":["stokes"],"soru":[],"hesap":[]}},{"id":"dynamic-viscosity","tr":"Dinamik viskozite","en":"dynamic viscosity","kisa":"μ","tur":"kavram","es":["viskozite","hava viskozitesi","havanın dinamik viskozitesi","dynamic viscosity of air"],"tanim":["Bir akışkanın kayma gerilimi altında deformasyona ve akmaya karşı gösterdiği iç sürtünme direncinin katsayısıdır.","SI birimi Pa·s olup standart atmosfer koşullarında havanın dinamik viskozitesi yaklaşık 1,8 × 10⁻⁵ Pa·s değerini alır.","Aerosol parçacıklarına etki eden sürükleme kuvvetini belirleyerek Stokes çökelme hızını ve atmosferik kalış süresini doğrudan kontrol eder."],"tanim_en":"A measure of the internal resistance of a fluid to flow when subjected to an applied shear stress.","bag":{"kavram":["stokes"],"soru":["S17"],"hesap":["stokes"]}},{"id":"rainout","tr":"Bulut içi yıkanma","en":"rainout","kisa":"","tur":"kavram","es":["in-cloud scavenging","bulut içi süpürülme","bulut içi yıkama"],"tanim":["Aerosol parçacıklarının ve çözünür gazların bulut oluşumu sırasında damlacıklara çekirdek oluşturarak ya da bulut içinde damlacıklar tarafından yakalanarak yağışla yeryüzüne inmesi sürecidir.","Islak çökelmenin ana bileşeni olup özellikle sülfat gibi ince aerosol parçacıklarının atmosferden temizlenmesinde en verimli yoldur.","Bulut yoğuşma çekirdeği görevi gören parçacıklar yoğuşmayla büyür ve yağış damlasına dönüşerek troposferden uzaklaştırılır."],"tanim_en":"The removal of aerosol particles and soluble gas species from the atmosphere through their incorporation into cloud droplets during formation and subsequent precipitation.","bag":{"kavram":["stokes"],"soru":[],"hesap":[]}},{"id":"terminal-velocity","tr":"Terminal hız","en":"terminal velocity","kisa":"v","tur":"kavram","es":["çökme hızı","Stokes düşme hızı","Stokes hızı","v_s","çökelme hızı","settling velocity"],"tanim":["Düşen bir parçacığa etki eden yerçekimi ağırlık kuvveti ile akışkanın sürükleme direnç kuvveti eşitlendiğinde ulaşılan sabit limit düşme hızıdır.","Stokes rejimindeki küresel parçacıklar için hız parçacık çapının karesiyle ve yoğunluğuyla doğru orantılı olarak v = ρ g D² / (18μ) ile hesaplanır.","Aerosollerin atmosferde havada kalma süresini ve yeryüzüne yerçekimsel çökme sürelerini belirleyen temel büyüklüktür."],"tanim_en":"The constant speed achieved by an object falling through a fluid when the upward drag force balances the downward gravitational force.","bag":{"kavram":["stokes"],"soru":["S17"],"hesap":[]}},{"id":"washout","tr":"Bulut altı yıkanma","en":"washout","kisa":"","tur":"kavram","es":["below-cloud scavenging","bulut altı süpürülme","bulut altı yıkama"],"tanim":["Buluttan düşen yağmur ya da kar damlacıklarının bulut tabanı altındaki hava sütununda bulunan parçacık ve gazları çarpışarak toplaması ve yere indirmesi sürecidir.","Islak çökelmenin bulut altı evresidir; özellikle iri parçacıkların ve yüksek çözünürlüklü gazların yüzey tabakasından temizlenmesinde etkilidir.","Yağış sırasında yüzey yakınındaki kirletici derişimini hızla düşürerek görüş mesafesini artırır ve hava kalitesini iyileştirir."],"tanim_en":"The scavenging and removal of airborne particles and soluble trace gas species beneath clouds by falling precipitation.","bag":{"kavram":["stokes"],"soru":[],"hesap":[]}},{"id":"reynolds-number","tr":"Reynolds sayısı","en":"Reynolds number","kisa":"Re","tur":"olcu","es":["Re"],"tanim":["Bir akışkan içindeki atalet kuvvetlerinin viskoz sürtünme kuvvetlerine oranını temsil eden boyutsuz bir sayıdır.","Re = ρ v D / μ bağıntısıyla hesaplanır; Re < 1 koşulunda laminer akış geçerli olup Stokes sürtünme yasası uygulanır.","Aerosol parçacıklarının ve küçük bulut damlalarının (D ≲ 60 µm) Stokes rejiminde çöküp çökmediğini belirlemekte temel ölçüttür."],"tanim_en":"A dimensionless number expressing the ratio of inertial force to viscous force within a flowing fluid.","bag":{"kavram":["stokes"],"soru":[],"hesap":["stokes"]}},{"id":"sym-surface-tension","tr":"Yüzey gerilimi","en":"surface tension","kisa":"γ","tur":"olcu","es":["sıvı yüzey gerilimi","yüzey enerjisi"],"tanim":["İki faz arasındaki ara yüzde birim yeni yüzey alanı oluşturmak için gereken enerji ya da ara yüz boyunca etkiyen birim uzunluk başına teğetsel çekim kuvveti.","Birimi N/m ya da J/m² cinsinden ifade edilir; saf su için oda sıcaklığında yaklaşık 0,072 N/m olarak ölçülür.","Parçacık boyutu küçüldükçe alan/hacim oranını artırdığından, 1 µm altındaki ince aerosollerin mekanik yolla parçalanmasını zorlaştırır."],"tanim_en":"The surface force per unit length or free energy per unit area acting at the interface between two media.","bag":{"kavram":["stokes","aerosol-sinif"],"soru":["S17"],"hesap":["stokes"]}},{"id":"stokes-law","tr":"Stokes yasası","en":"Stokes' law","kisa":"","tur":"yontem","es":["Stokes bağıntısı","Stokes denklemi"],"tanim":["Düşük Reynolds sayısında (Re ≪ 1) akışkan içinde çökelen küçük küresel taneciklere etkiyen sürtünme direncini ve buna bağlı terminal çökme hızını belirleyen fiziksel yasa.","Direnç kuvveti F_d = 3πμDv olup yerçekimi kuvvetiyle dengelendiğinde terminal hız v = (ρ_p g D²)/(18μ) eşitliğiyle hesaplanır; havanın dinamik viskozitesi μ ≈ 1,8 × 10⁻⁵ Pa·s alınır.","Atmosferde özellikle iri aerosol modundaki taneciklerin ve bulut damlacıklarının kuru yerçekimsel çökelme hızını hesaplamada temel alınır."],"tanim_en":"Stokes' law describes the frictional drag force exerted on small spherical particles moving through a fluid at low Reynolds numbers and defines their terminal settling velocity.","bag":{"kavram":["stokes"],"soru":["S17"],"hesap":["stokes"]}},{"id":"megatonne","tr":"Megaton","en":"megatonne","kisa":"Mt","tur":"birim","es":["milyon ton","Mt","Tg"],"tanim":["Bir milyon metrik tona (10⁶ t), 10¹² grama veya 1 teragrama (1 Tg) eşit olan büyük ölçekli kütle birimi.","Sembolü Mt; atmosferin kütlesi ≈ 5,1 × 10⁹ Mt (5,1 × 10¹⁸ kg) eder, küresel gaz yükleri çoğunlukla Tg (= Mt) ile verilir.","Büyük volkanik patlamalarda atmosfere püskürtülen gaz miktarını ve küresel sera gazı salımlarını ifade etmekte yaygın olarak kullanılır."],"tanim_en":"A megatonne is a metric unit of mass equal to one million metric tonnes or one teragram.","bag":{"kavram":["stokiyometri","volkan-aerosol","ustel"],"soru":["S31"],"hesap":[]}},{"id":"mole","tr":"Mol (madde miktarı)","en":"mole","kisa":"mol","tur":"birim","es":["mol sayısı","madde miktarı","mol miktarı","amount of substance"],"tanim":["Avogadro sayısı kadar (6,022 × 10²³) temel tanecik (atom, molekül ya da iyon) içeren madde miktarını belirten temel SI birimi.","Sembolü mol olup gazların karışım oranı (mol/mol), molar hacmi (25 °C ve 1 atm altında 24,45 L/mol) ve atmosfer kütlesi hesaplarında temel alınır.","Atmosfer kimyasında hava bileşenlerinin derişimlerini bağıl mol kesri (ppm, ppb) cinsinden tanımlamayı ve kimyasal tepkimelerdeki stokiyometrik madde dengesini kurmayı sağlar."],"tanim_en":"The mole is the SI base unit of amount of substance, containing exactly 6.02214076 × 10²³ elementary entities.","bag":{"kavram":["stokiyometri","karisim-orani","sayi-yogunlugu"],"soru":["S1","S2","S3","S4","S5","S9"],"hesap":["ppb-ugm3","ugm3-ppb","atmosfer-kutlesi","stokiyometri"]}},{"id":"ammonium-sulfate","tr":"Amonyum sülfat","en":"ammonium sulfate","kisa":"(NH₄)₂SO₄","tur":"kavram","es":["(NH4)2SO4","ammonium sulphate","diamonyum sülfat","(NH₄)₂SO₄"],"tanim":["Atmosferde gaz halindeki amonyağın sülfürik asit damlacıklarını nötrlemesiyle oluşan inorganik bir tuz bileşiği ((NH₄)₂SO₄).","Tam nötrleme için 1 mol H₂SO₄ başına 2 mol NH₃ gerekir; suda yüksek çözünürlüğe sahip olup ince parçacık kütlesinin önemli bölümünü oluşturur.","İnce aerosol (PM2.5) fraksiyonunun ana bileşeni olup bulut yoğuşma çekirdeği işlevi görür ve güneş ışığını saçarak soğumaya katkı verir."],"tanim_en":"Ammonium sulfate is an inorganic salt formed by the neutralization of sulfuric acid with ammonia, serving as a major constituent of fine atmospheric aerosol.","bag":{"kavram":["stokiyometri","aerosol-sinif","asit-yagmuru"],"soru":["S28"],"hesap":[]}},{"id":"balanced-equation","tr":"Denkleştirilmiş tepkime denklemi","en":"balanced equation","kisa":"","tur":"kavram","es":["denkleşmiş tepkime","denkleştirilmiş denklem"],"tanim":["Kimyasal bir tepkimede giren ve ürün taraflarındaki her bir elementin atom sayılarının ve toplam elektrik yüklerinin eşitlendiği kimyasal denklem.","Türlerin önündeki stokiyometrik katsayılar (ν) aracılığıyla tepkimeye giren ve oluşan maddelerin mol oranlarını tam olarak gösterir.","Atmosfer kimyasında kirleticilerin dönüşümünde, asit nötrleme hesaplarında ve fotokimyasal döngülerde madde dengesini kurmak için zorunludur."],"tanim_en":"A balanced equation is a chemical equation in which the number of atoms for each element and the total electric charge are equal on both sides.","bag":{"kavram":["stokiyometri"],"soru":[],"hesap":[]}},{"id":"cfc-12","tr":"CFC-12","en":"CFC-12","kisa":"CF₂Cl₂","tur":"kavram","es":["CF2Cl2","diklorodiflorometan","Freon-12","CF₂Cl₂","Dichlorodifluoromethane","dichlorodifluoromethane"],"tanim":["Troposferde son derece kararlı olan, kimyasal formülü CF₂Cl₂ ve mol kütlesi 120,9 g/mol olan yapay bir kloroflorokarbon bileşiği.","Atmosferik ömrü yaklaşık 100 yıldır; stratosfere ulaştığında sert morötesi ışınımla fotoliz olarak molekül başına iki adet klor atomu bırakır.","Kutup ozon deliğine ve küresel stratosferik ozon incelmesine yol açan temel klor kaynağı bileşiklerdendir."],"tanim_en":"A synthetic chlorofluorocarbon with the formula CF₂Cl₂ and an atmospheric lifetime of about 100 years that delivers ozone-depleting chlorine to the stratosphere.","bag":{"kavram":["stokiyometri","psc","katalitik"],"soru":["S42"],"hesap":[]}},{"id":"chlorine-atom","tr":"Klor atomu","en":"chlorine atom","kisa":"Cl","tur":"kavram","es":["Cl","klor radikali","atomik klor","chlorine radical"],"tanim":["Yedi değerlik elektronuna ve bir eşleşmemiş elektrona sahip, açık kabuklu ve yüksek tepkime yatkınlığı bulunan halojen serbest radikali (Cl).","Stratosferde CFC ve diğer halojenli bileşiklerin fotoliziyle oluşur; ozon molekülüyle hızla tepkiyerek ClO radikalini meydana getirir.","Katalitik döngülere girerek kararlı bir rezervuar türe bağlanana kadar binlerce ozon molekülünü parçalar."],"tanim_en":"A highly reactive open-shell halogen radical with an unpaired electron that acts as an efficient catalyst in stratospheric ozone destruction.","bag":{"kavram":["stokiyometri","psc","katalitik"],"soru":["S32","S42"],"hesap":["cfc-ozon"]}},{"id":"stoichiometric-coefficient","tr":"Stokiyometrik katsayı","en":"stoichiometric coefficient","kisa":"ν","tur":"olcu","es":["tepkime katsayısı","mol katsayısı","nu","stokiyometri katsayısı"],"tanim":["Denkleştirilmiş bir kimyasal tepkime denkleminde her bir kimyasal türün önünde yer alan ve mol oranını belirten tamsayı veya kesirli sayı.","Sembolü genellikle ν olup girenler için geleneksel olarak negatif, ürünler için pozitif kabul edilir veya bağıl oranlarda (ν_B/ν_A) kullanılır.","Kimyasal dönüşümlerde kütle ve mol korunumunu hesaplamayı, sınırlayıcı bileşeni ve gereken reaktif miktarını bulmayı sağlar."],"tanim_en":"A stoichiometric coefficient is the number written in front of a chemical formula in a balanced equation to indicate the molar ratio of the reaction.","bag":{"kavram":["stokiyometri"],"soru":["S28"],"hesap":["stokiyometri"]}},{"id":"absorptivity","tr":"Soğurma kesri","en":"absorptivity","kisa":"f","tur":"kavram","es":["soğurganlık","IR soğurma kesri","uzun dalga soğurma kesri","infrared absorptivity"],"tanim":["Bir ortamın veya atmosfer katmanının üzerine gelen ışınım akısının soğurulan oranını belirten 0 ile 1 arasındaki boyutsuz büyüklük.","Sembolü f olup Kirchhoff yasasına göre ısıl dengede katmanın uzun dalga yayıcılığına eşittir.","Tek katman sera modelinde atmosferin kızılötesi ışınımı tutma derecesini temsil eder; sera gazı derişimi arttıkça f büyür ve yüzey sıcaklığı yükselir."],"tanim_en":"Absorptivity is the dimensionless fraction of incident radiation absorbed by a medium or atmospheric layer.","bag":{"kavram":["tek-katman"],"soru":["S7"],"hesap":[]}},{"id":"bicarbonate","tr":"Hidrojen karbonat (bikarbonat) iyonu","en":"bicarbonate","kisa":"HCO₃⁻","tur":"kavram","es":["hidrojen karbonat","HCO3-","bikarbonat","hidrojen karbonat iyonu","bikarbonat iyonu","bicarbonate ion"],"tanim":["Karbonik asidin ilk protonunu vermesiyle oluşan bir değerlikli inorganik anyon (HCO₃⁻).","IUPAC adı hidrojen karbonat olup sulu çözeltilerde CO₂ çözünmesi ve ilk ayrışma dengesi (K₁ ≈ 4,3 × 10⁻⁷ mol/L) sonucunda meydana gelir.","Temiz yağmur suyunda baskın anyon olup hidrojen iyonu derişimini dengeler ([H⁺] ≈ [HCO₃⁻]) ve yağışın doğal pH değerinin 5,6 civarında kalmasını belirler."],"tanim_en":"Bicarbonate is the monovalent anion HCO₃⁻ formed by the primary dissociation of carbonic acid in aqueous solution.","bag":{"kavram":["temiz-yagmur","asit-yagmuru"],"soru":["S26","S29"],"hesap":[]}},{"id":"carbonic-acid","tr":"Karbonik asit","en":"carbonic acid","kisa":"H₂CO₃","tur":"kavram","es":["H2CO3","CO2·H2O","çözünmüş karbondioksit","H₂CO₃"],"tanim":["Atmosferdeki karbondioksit gazının su damlacıklarında Henry yasasına göre çözünmesiyle oluşan iki protonlu zayıf bir asit (H₂CO₃).","Sulu fazda çoğunlukla gevşek bağlı CO₂·H₂O biçiminde bulunur ve ilk ayrışma sabiti K₁ ≈ 4,3 × 10⁻⁷ mol/L değerine sahiptir.","Hiçbir hava kirliliği bulunmayan temiz yağmur suyuna doğal asitliğini vererek pH değerini yaklaşık 5,6 düzeyine çeker."],"tanim_en":"Carbonic acid is a weak diprotic acid formed by the dissolution of carbon dioxide in water, controlling the natural pH of clean precipitation.","bag":{"kavram":["temiz-yagmur","asit-yagmuru"],"soru":["S26","S27"],"hesap":[]}},{"id":"dissociation-constant","tr":"Ayrışma sabiti","en":"dissociation constant","kisa":"K₁","tur":"kavram","es":["asitlik sabiti","iyonlaşma sabiti","Ka1","acid dissociation constant"],"tanim":["Bir asit veya bazın sulu çözeltide iyonlarına ayrışma dengesini belirleyen ve kimyasal dengedeki türlerin derişim oranını veren denge sabiti.","Karbonik asidin ilk ayrışması için K₁ = [H⁺][HCO₃⁻]/[CO₂·H₂O] bağıntısıyla tanımlanır ve 25 °C sıcaklıkta yaklaşık 4,3 × 10⁻⁷ mol/L değerine sahiptir.","Atmosfer kimyasında gazların su damlacıkları içindeki asitlik şiddetini ve temiz ya da kirli yağışın pH değerini belirlemede kullanılır."],"tanim_en":"A dissociation constant is an equilibrium constant that quantifies the tendency of an acid to separate into ions in aqueous solution.","bag":{"kavram":["temiz-yagmur"],"soru":["S26"],"hesap":["ph-temiz"]}},{"id":"equilibrium","tr":"Kimyasal denge","en":"equilibrium","kisa":"","tur":"kavram","es":["dinamik denge"],"tanim":["İleri ve geri tepkime hızlarının birbirine eşit olduğu ve net derişim değişiminin sıfırlandığı dinamik durumdur.","Termodinamik denge sabiti K ile tanımlanır ve sistem sıcaklığına bağlıdır.","Atmosfer kimyasında gazların damlacıklarda çözünme dengelerinde (CO₂(g) ⇌ CO₂(aq)) ve sulu faz asit-baz tepkimelerinde kullanılır."],"tanim_en":"State of a reversible chemical reaction in which forward and backward reaction rates are equal, resulting in unchanging concentrations over time.","bag":{"kavram":["temiz-yagmur","asit-yagmuru"],"soru":["S26","S27"],"hesap":["ph-temiz"]}},{"id":"pre-industrial","tr":"Sanayi öncesi dönem","en":"pre-industrial","kisa":"","tur":"kavram","es":["pre-industrial era","sanayi öncesi","sanayi öncesi seviye"],"tanim":["Geniş ölçekli fosil yakıt tüketiminin ve insan kaynaklı emisyonların atmosfer bileşimini henüz belirgin biçimde değiştirmediği 1750 yılı öncesi dönem.","Bu referans döneminde atmosferik CO₂ karışım oranı yaklaşık 278 ppm (yuvarlak 280 ppm), CH₄ yaklaşık 729 ppb ve N₂O yaklaşık 270 ppb düzeyindeydi.","İklim değişikliği hesaplamalarında ışınımsal zorlama, küresel yüzey sıcaklığı artışı ve doğal yağmur pH değeri için temel referans noktasıdır."],"tanim_en":"The multi-century baseline era prior to widespread industrial activity around 1750 against which anthropogenic climate change and atmospheric composition changes are evaluated.","bag":{"kavram":["temiz-yagmur"],"soru":[],"hesap":[]}},{"id":"weak-acid","tr":"Zayıf asit","en":"weak acid","kisa":"","tur":"kavram","es":["kısmen ayrışan asit"],"tanim":["Sulu çözeltide protonlarını bütünüyle ortama aktarmayan, denge hâlinde kısmen iyonlaşan asittir.","Küçük bir ayrışma sabiti (K₁) ile nitelenir; ortamda iyonlaşmamış moleküller ile ayrışma ürünleri dinamik denge oluşturur.","Atmosferde havadaki CO₂ gazının damlada çözünmesiyle oluşan karbonik asit (H₂CO₃) tipik bir örnektir ve temiz yağmuru hafif asidik yapar."],"tanim_en":"Acid that undergoes incomplete ionization in aqueous solution, governed by a small dissociation constant.","bag":{"kavram":["temiz-yagmur"],"soru":[],"hesap":[]}},{"id":"henry-s-law-constant","tr":"Henry sabiti","en":"Henry's law constant","kisa":"K_H","tur":"olcu","es":["Henry yasası","Henry katsayısı","Kₕ","Henry's law"],"tanim":["Seyreltik bir çözeltide çözünen gazın derişimi ile o gazın sıvı üzerindeki kısmi basıncı arasındaki doğru orantıyı kuran denge katsayısıdır.","Kitaptaki çözünürlük biçiminde birimi mol L⁻¹ atm⁻¹ olup 25 °C sıcaklıkta CO₂ için tipik değeri 3,4 × 10⁻² mol L⁻¹ atm⁻¹ olarak ölçülür.","Atmosfer kimyasında gaz fazındaki iz gazların bulut damlalarına ve yağmur suyuna geçiş miktarını hesaplamada temel parametredir."],"tanim_en":"Temperature-dependent proportionality coefficient that relates the equilibrium concentration of a dissolved gas in liquid to its partial pressure in the gas phase.","bag":{"kavram":["temiz-yagmur"],"soru":["S26"],"hesap":["ph-temiz"]}},{"id":"charge-balance","tr":"Yük dengesi","en":"charge balance","kisa":"","tur":"yontem","es":["elektronötrallik","iyonik yük denkliği","electroneutrality"],"tanim":["Sulu bir çözeltide pozitif ve negatif elektrik yüklerinin toplamının birbirine eşit olması ilkesi.","İyon derişimleri eşdeğer derişim cinsinden yazılır; katyon ve anyon yüklerinin denkliği kimyasal analizlerin doğruluğunu denetler.","Atmosfer kimyasında bulut damlası ile yağmur suyunun pH eşitliklerini türetmekte temel bağıntı olarak kullanılır."],"tanim_en":"The condition of electroneutrality in an aqueous solution where the total positive electric charge equals the total negative electric charge.","bag":{"kavram":["temiz-yagmur","asit-yagmuru"],"soru":["S26","S27"],"hesap":["ph-temiz"]}},{"id":"downwind","tr":"Rüzgâraltı","en":"downwind","kisa":"","tur":"kavram","es":["rüzgâr altı","rüzgar altı","akış aşağısı","downstream"],"tanim":["Hava akımının estiği yönde, emisyon kaynağının arkasında kalan bölge.","Şehir merkezinden salınan birincil kirleticiler bu yöne doğru taşınırken güneş ışığı ve fotokimyasal tepkimelerle ikincil kirleticilere dönüşür.","NO titrasyonu şehir merkezinde ozonu baskılarken, fotokimyasal üretim ve taşınım nedeniyle en yüksek ozon derişimleri rüzgâraltı banliyölerde gözlenir."],"tanim_en":"In the direction toward which the wind is blowing, referring to the region located downstream from an emission source.","bag":{"kavram":["titrasyon","kutu-modeli","leighton"],"soru":["S43"],"hesap":["kutu-modeli"]}},{"id":"ground-level-ozone","tr":"Yer seviyesi ozonu","en":"ground-level ozone","kisa":"","tur":"kavram","es":["yerdeki ozon","troposferik ozon","yüzey ozonu"],"tanim":["Troposferin alt katmanlarında ve yüzeye yakın havada bulunan, insan sağlığına ve bitki örtüsüne zararlı ikincil hava kirleticisi.","Yüzeyde arka plan karışım oranı ≈ 30–50 ppb; WHO 2021 kılavuzunda 8 saatlik kılavuz değer 100 µg/m³.","Doğrudan bacadan salınmaz; NOₓ ve uçucu organik bileşiklerin güneş ışığında tepkimeye girmesiyle fotokimyasal duman içinde sentezlenir."],"tanim_en":"A secondary air pollutant formed near the Earth's surface through photochemical reactions between nitrogen oxides and volatile organic compounds in sunlight.","bag":{"kavram":["titrasyon","leighton"],"soru":["S44"],"hesap":[]}},{"id":"nitrogen-dioxide","tr":"Azot dioksit","en":"nitrogen dioxide","kisa":"NO₂","tur":"kavram","es":["azotdioksit","azot(IV) oksit","NO2"],"tanim":["Atmosferde kahverengimsi kırmızı renkli, keskin kokulu, zehirli ve reaktif bir azot oksit gazıdır.","Güneş ışığı altında fotoliz ömrü öğle vaktinde yaklaşık 2 dk sürer; WHO kılavuz değeri yıllık ortalama 10 µg/m³ olarak belirlenmiştir.","Troposferde morötesi ışınımla fotolize uğrayarak serbest oksijen atomu verir ve zemin ozonunu üreten tek doğrudan kimyasal mekanizmayı sağlar."],"tanim_en":"Brownish reactive trace gas that undergoes photolysis in sunlight to yield the oxygen atom required for tropospheric ozone formation.","bag":{"kavram":["titrasyon","leighton","asit-yagmuru"],"soru":["S2","S21","S40","S42","S43","S44"],"hesap":["leighton"]}},{"id":"pollutant","tr":"Kirletici","en":"pollutant","kisa":"","tur":"kavram","es":["hava kirleticisi","kirletici madde"],"tanim":["Çevreye salındığında doğal dengeleri bozan, canlı sağlığına, ekosisteme ya da malzemelere zarar veren madde veya enerji.","Atmosfer kimyasında gaz (SO₂, NOₓ, O₃, CO) ve aerosol (PM2.5, PM10) kirleticiler incelenir; derişim ppb ya da µg/m³ ile verilir.","Kaynağından doğrudan atmosfere salınan birincil kirleticiler ile atmosferdeki kimyasal tepkimeler sonucu sentezlenen ikincil kirleticiler olarak iki ana gruba ayrılır."],"tanim_en":"A pollutant is a substance introduced into the environment in amounts that harm living organisms, ecosystems or materials; air pollutants are classed as primary or secondary.","bag":{"kavram":["titrasyon","aerosol-sinif"],"soru":["S2","S19","S20","S21","S27","S28"],"hesap":[]}},{"id":"precursor","tr":"Öncül","en":"precursor","kisa":"","tur":"kavram","es":["öncül madde","öncül kirletici","ozon öncülü gazlar","ozon öncülleri","ozone precursors","öncül bileşik"],"tanim":["Atmosfer kimyasında, kimyasal ya da fotokimyasal tepkimeler sonucunda ikincil kirleticilere ya da aerosol parçacıklarına dönüşen başlangıç maddesi.","Ozon için NOₓ ve uçucu organik bileşikler (VOC), sülfat aerosolü için SO₂ gibi doğrudan salınan başlangıç bileşiklerini belirtir.","Gaz fazından düşük uçuculuklu ürünlere ve ince parçacıklara dönüşerek ikincil aerosol ve fotokimyasal duman oluşumunu kontrol eder."],"tanim_en":"A chemical substance that participates in a reaction to produce an atmospheric secondary pollutant or aerosol.","bag":{"kavram":["titrasyon","aerosol-sinif","leighton"],"soru":["S14","S21","S44"],"hesap":[]}},{"id":"weekend-effect","tr":"Hafta sonu etkisi","en":"Weekend effect","kisa":"","tur":"kavram","es":["haftasonu etkisi","ozon hafta sonu anomalisi"],"tanim":["Hafta sonları trafik kaynaklı NO emisyonlarının düşmesine karşın, şehir merkezlerinde ozon derişiminin paradoksal biçimde yükselmesi olgusudur.","Kimyasal açıdan VOC kısıtlı ve NO titrasyonunun baskın olduğu kirli kentsel alanlarda gözlenir; kırsal veya NOₓ kısıtlı bölgelerde ortaya çıkmaz.","Hava kalitesi yönetiminde yalnız NO azaltımının şehir merkezinde ozonu artırabileceğini, VOC ve NOₓ türlerinin birlikte kontrol edilmesi gerektiğini gösterir."],"tanim_en":"Observed phenomenon in VOC-limited urban environments where ground-level ozone reaches higher levels on weekends due to reduced nitric oxide titration.","bag":{"kavram":["titrasyon"],"soru":["S43"],"hesap":[]}},{"id":"peroxyacetyl-nitrate","tr":"Peroksiasetil nitrat","en":"peroxyacetyl nitrate","kisa":"PAN","tur":"kod","es":["PAN","peroksiasetilnitrat","CH3C(O)OONO2"],"tanim":["Peroksiasetil radikalinin azot dioksit ile tepkimesinden oluşan CH₃C(O)OONO₂ formüllü ikincil fotokimyasal kirleticidir.","Düşük sıcaklıklarda termal olarak kararlı olup serbest troposferde uzun ömürlü bir NOₓ rezervuarı gibi davranır.","Şehir kaynaklı azot oksitleri uzak kırsal bölgelere taşır ve fotokimyasal dumanın göz yaşartıcı ana bileşenlerindendir."],"tanim_en":"A secondary pollutant formed by the reaction of peroxyacetyl radicals with nitrogen dioxide, acting as a thermally sensitive reservoir for reactive nitrogen.","bag":{"kavram":["titrasyon","leighton"],"soru":[],"hesap":[]}},{"id":"cloud-condensation-nuclei","tr":"Bulut yoğuşma çekirdekleri","en":"cloud condensation nuclei","kisa":"CCN","tur":"kavram","es":["bulut yoğuşma çekirdeği","yoğuşma çekirdekleri","BYÇ","CCN"],"tanim":["Atmosferdeki su buharının üzerinde yoğuşarak bulut damlacıklarını oluşturabildiği mikroskobik higroskopik aerosol parçacıklarıdır.","Çoğunlukla 0,1 µm civarı birikme modundaki sülfat, nitrat veya deniz tuzu aerosollerinden oluşur; ortamdaki sayı derişimi deniz üzerinde 50–100 cm⁻³, karada 300–1000 cm⁻³ aralığında ölçülür.","Bulut damla sayısını ve boyutunu belirleyerek bulut albedosunu (Twomey etkisi) ve yağış oluşumunu doğrudan kontrol eder."],"tanim_en":"Hygroscopic aerosol particles that serve as nucleation sites for water vapor to form liquid cloud droplets.","bag":{"kavram":["twomey","boyut-modlari","bulut-isinim"],"soru":["S15","S22"],"hesap":[]}},{"id":"cloud-droplet","tr":"Bulut damlası","en":"cloud droplet","kisa":"","tur":"kavram","es":["bulut damlacığı","sıvı su damlası","liquid water droplet"],"tanim":["Bulut içinde asılı duran, aşırı soğumuş veya sıvı hâldeki mikron boyutlu su damlası.","Yarıçapı tipik olarak 5–15 µm arasında kalır ve bir bulut yoğuşma çekirdeği üzerinde yoğuşarak oluşur.","Yerçekimiyle hemen düşmeyip havada asılı kalır; güneş ışığını uzaya geri saçarak bulut albedosunu belirler."],"tanim_en":"A liquid or supercooled water drop suspended in the atmosphere within a cloud, typically with a radius between 5 and 15 µm.","bag":{"kavram":["twomey","bulut-isinim"],"soru":["S12","S22"],"hesap":[]}},{"id":"effective-radius","tr":"Etkin yarıçap","en":"effective radius","kisa":"","tur":"kavram","es":["etkili yarıçap","r_eff","optik etkin yarıçap"],"tanim":["Bir buluttaki damla boyut dağılımının ışınımsal özelliklerini temsil eden ağırlıklı ortalama yarıçap.","Matematiksel olarak damla yarıçaplarının üçüncü momentinin ikinci momentine oranıyla (∑r³ / ∑r²) hesaplanır.","Uydu uzaktan algılamasında bulut kirliliğini ve mikrofiziksel değişimi izlemek için temel büyüklüktür."],"tanim_en":"The area-weighted mean droplet radius defined as the ratio of the third to the second moment of the cloud droplet size distribution.","bag":{"kavram":["twomey"],"soru":[],"hesap":[]}},{"id":"semi-direct-effect","tr":"Yarı doğrudan etki","en":"semi-direct effect","kisa":"","tur":"kavram","es":["semi-direct aerosol effect"],"tanim":["Güneş ışığını soğuran aerosollerin bulundukları hava katmanını ısıtarak bulut örtüsünü ve bağıl nemi değiştirmesi süreci.","İs gibi parçacıkların güneş ışınımını soğurmasıyla yerel sıcaklık artar ve bağıl nem düşer.","Isınan katmandaki bulut damlalarının buharlaşmasına yol açarak bulutun dağılmasına ve yerel albedonun azalmasına neden olur."],"tanim_en":"The process where absorbing aerosol particles warm the atmospheric layer, lower relative humidity, and evaporate cloud droplets.","bag":{"kavram":["twomey","aerosol-dogrudan"],"soru":[],"hesap":[]}},{"id":"ship-tracks","tr":"Gemi izleri","en":"ship tracks","kisa":"","tur":"kavram","es":["gemi izi","gemi izi bulutları","parlak bulut çizgileri","ship track"],"tanim":["Okyanus üstündeki alçak denizel stratokümülüs bulutlarında seyreden gemilerin bacalarından çıkan aerosollerin oluşturduğu dar ve parlak bulut çizgileri.","Temiz denizel havaya salınan kükürtlü aerosol parçacıkları yerel bulut yoğuşma çekirdeği sayısını artırır.","Sıvı su içeriği sabitken artan çekirdekler damla sayısını artırıp yarıçapı küçültür; bu durum Twomey etkisinin uydu görüntülerindeki doğrudan kanıtıdır."],"tanim_en":"Narrow, bright streaks in low maritime clouds formed when aerosol emissions from ship stacks elevate droplet concentration and cloud reflectivity.","bag":{"kavram":["twomey","bulut-isinim"],"soru":["S22"],"hesap":[]}},{"id":"cloud-albedo","tr":"Bulut albedosu","en":"cloud albedo","kisa":"A_bulut","tur":"olcu","es":["bulut yansıtma oranı","bulut yansıtıcılığı","cloud reflectance","A_bulut"],"tanim":["Bir bulutun üzerine gelen güneş ışınımını uzaya geri yansıtma oranı (0 ile 1 arasında boyutsuz kesir).","Sıvı su yoluna, damla boyutuna ve optik derinliğe bağlıdır; kitaptaki örnekte ince sirrus için A ≈ 0,2, kalın stratus için A ≈ 0,6.","Yüzey albedosuyla arasındaki fark (ΔA) oranında fazladan güneş ışığını yansıtarak iklim üzerinde güçlü bir soğutma zorlaması yaratır."],"tanim_en":"The fraction of incident solar radiation reflected back to space by a cloud, determined by cloud thickness and droplet microphysics.","bag":{"kavram":["twomey","bulut-isinim"],"soru":["S10","S12","S22"],"hesap":["bulut-net"]}},{"id":"liquid-water-content","tr":"Sıvı su içeriği","en":"liquid water content","kisa":"LWC","tur":"olcu","es":["LWC","sıvı su miktarı","W","bulut sıvı su içeriği"],"tanim":["Bir bulutun birim hacminde bulunan sıvı su damlacıklarının toplam kütlesi.","Birimi g/m³ olup tipik bulutlarda 0,1 ile 1 g/m³ arasında değişir; W = N (4/3) π r³ ρ_w bağıntısıyla damla sayısı ve boyutuyla ilişkilidir.","Twomey etkisi türetiminde aerosol kirliliğiyle değişmediği varsayılarak damla yarıçapının değişimini belirler."],"tanim_en":"The total mass of liquid water droplets contained within a unit volume of cloud, typically expressed in grams per cubic metre.","bag":{"kavram":["twomey","bulut-isinim"],"soru":["S22"],"hesap":["twomey"]}},{"id":"sym-cloud-droplet-number","tr":"Bulut damlası sayı derişimi","en":"cloud droplet number concentration","kisa":"N","tur":"olcu","es":["damla sayı derişimi","CDNC","damla konsantrasyonu","damla sayı yoğunluğu","N"],"tanim":["Bulutun birim hacminde bulunan sıvı bulut damlalarının sayısı.","Birimi cm⁻³ olup tipik değerleri temiz denizel bulutlarda 50–100 cm⁻³, kirlenmiş karasal bulutlarda 300–1000 cm⁻³ düzeyinde seyreder.","Yoğuşan aerosol (CCN) sayısıyla doğrudan artar; sabit sıvı su miktarında damla boyutunu ve bulutun yansıtıcılığını kontrol eder."],"tanim_en":"The number of liquid cloud droplets per unit volume of air, typically quantified in droplets per cubic centimetre.","bag":{"kavram":["twomey","bulut-isinim"],"soru":[],"hesap":["twomey"]}},{"id":"sym-cloud-optical-depth","tr":"Bulut optik derinliği","en":"cloud optical depth","kisa":"τ_c","tur":"olcu","es":["bulut optik kalınlığı","cloud optical thickness","τ_c"],"tanim":["Güneş ışınımının bir bulut tabakasından geçerken damlacıklar tarafından saçılma ve soğurulma sonucu uğradığı toplam zayıflamanın boyutsuz ölçüsü.","Boyutsuz bir büyüklüktür; sönüm verimi Q_ext ≈ 2 kabulüyle damla yarıçapı, damla sayı derişimi ve bulut kalınlığından τ_c ≈ 2πr²NH bağıntısıyla hesaplanır (tipik değeri 5–50).","Sıvı su içeriği sabitken aerosol artışının damla sayısını artırıp yarıçapı küçültmesiyle büyür ve bulut albedosunu artırır."],"tanim_en":"A dimensionless measure of the total attenuation of solar radiation passing through a cloud layer due to scattering and absorption by cloud droplets.","bag":{"kavram":["twomey","beer-lambert"],"soru":["S22"],"hesap":["twomey"]}},{"id":"cloud-lifetime-effect","tr":"Bulut ömrü etkisi","en":"cloud lifetime effect","kisa":"","tur":"surec","es":["ikinci dolaylı etki","Albrecht etkisi","second indirect aerosol effect"],"tanim":["Aerosol kirliliği nedeniyle damlaların küçülmesi sonucu yağışın gecikmesi ve bulutun atmosferde daha uzun süre varlığını koruması süreci.","Daha küçük bulut damlacıkları çarpışma ve birleşme yoluyla yağmur damlasına dönüşmekte zorlanır; bu durum çisenti ve yağış oluşumunu baskılar.","Yağışla yok olmayan bulut örtüsü korunarak güneş ışınımı daha uzun süre uzaya yansıtılır ve iklim soğutulur."],"tanim_en":"The mechanism where smaller cloud droplets inhibit precipitation formation, thereby extending cloud duration and sunlight reflection.","bag":{"kavram":["twomey","bulut-isinim"],"soru":["S22"],"hesap":[]}},{"id":"doubling-time","tr":"İkiye katlanma süresi","en":"doubling time","kisa":"t₂","tur":"olcu","es":["iki katına çıkış süresi","t_2","ikiye katlanma zamanı"],"tanim":["Üstel olarak büyüyen bir büyüklüğün veya derişimin başlangıçtaki değerinin tam iki katına çıkması için geçen süre.","Yıllık kesirli büyüme oranı r olduğunda tam değeri t₂ = ln 2 / ln(1 + r) formülüyle hesaplanır.","Atmosferde CO₂ ve CH₄ gibi sera gazı salımlarının ve birikimlerinin gelecekteki artış hızını değerlendirmede kullanılır; yarı ömrün büyüme karşılığıdır."],"tanim_en":"The period of time required for an exponentially growing quantity to double in magnitude at a given growth rate.","bag":{"kavram":["ustel"],"soru":["S17","S21"],"hesap":["ustel-buyume"]}},{"id":"rule-of-70","tr":"70 kuralı","en":"rule of 70","kisa":"t₂ ≈ 70/%r","tur":"yontem","es":["yetmiş kuralı","ikiye katlanma kuralı","72 kuralı","rule of 72"],"tanim":["Üstel büyüyen bir değişkenin ikiye katlanma süresini yaklaşık olarak hesaplamak için kullanılan pratik kestirim yöntemi.","Küçük büyüme oranları için ln(1 + r) ≈ r yaklaşımına dayanır ve ikiye katlanma süresi yaklaşık t₂ ≈ 70 / (%r) formülüyle bulunur.","Sera gazı salımlarının ve birikimlerinin logaritma almadan zihinden hızlı sağlamasını yapmak için kullanılır."],"tanim_en":"A mental shortcut to estimate doubling time by dividing 70 by the percentage growth rate.","bag":{"kavram":["ustel"],"soru":["S21"],"hesap":["ustel-buyume"]}},{"id":"near-infrared","tr":"Yakın kızılötesi","en":"near-infrared","kisa":"NIR","tur":"kavram","es":["yakın-IR","near-IR","NIR","yakın IR","near infrared radiation"],"tanim":["Elektromanyetik tayfta görünür ışığın hemen ötesinde yaklaşık 0,7 ile 4 µm dalga boyu aralığını kapsayan güneş ışınımı bandı.","Güneş enerjisinin önemli bir payını taşır ve atmosferdeki su buharı ile sülfat aerosolleri tarafından kısmen soğurulur.","Isıl kızılötesi ışınıma kıyasla daha kısa dalga boylu olup iklim sisteminde gelen kısa dalga ışınım bütçesinde yer alır."],"tanim_en":"Near-infrared is the region of the electromagnetic spectrum immediately adjacent to visible light spanning wavelengths from approximately 0.7 to 4 micrometers.","bag":{"kavram":["volkan-aerosol","aerosol-dogrudan"],"soru":["S30"],"hesap":[]}},{"id":"polar-vortex","tr":"Kutup girdabı","en":"polar vortex","kisa":"","tur":"kavram","es":["polar girdap","kutupsal vorteks","stratosferik kutup girdabı","polar stratospheric vortex"],"tanim":["Kış aylarında kutup bölgesi üzerinde batıdan doğuya doğru esen güçlü stratosferik rüzgârların çevrelediği geniş siklonik hava dolaşımıdır.","Kutup havasını orta enlemlerden dinamik olarak yalıtarak kış boyunca kutup stratosferinin aşırı soğumasına ve sıcaklığın −78 °C'nin altına inmesine neden olur.","Bu soğuma kutup stratosfer bulutlarının (PSC) oluşmasını sağlar; kimyasal yalıtım ise ilkbaharda klor aktivasyonu sonucu ozon deliğinin gelişmesi için kapalı bir ortam yaratır."],"tanim_en":"A large-scale persistent cyclonic circulation in the polar stratosphere that thermally insulates polar air during winter and enables extremely low temperatures.","bag":{"kavram":["psc","katalitik"],"soru":["S30"],"hesap":[]}},{"id":"stratospheric-aerosol-layer","tr":"Stratosferik aerosol tabakası","en":"stratospheric aerosol layer","kisa":"","tur":"kavram","es":["Junge tabakası","stratosferik sülfat aerosolü","sülfat perdesi","stratospheric sulfate aerosol","Junge layer"],"tanim":["Stratosferde yaklaşık 15–25 km irtifada süregelen ve çoğunlukla alt mikron boyutlu sulu sülfürik asit damlacıklarından oluşan ince aerosol tabakası.","Arka plan durumunda OCS gazının fotoliziyle beslenir; büyük volkanik patlamalarda stratosfere ulaşan kükürt dioksitin dönüşümüyle optik kalınlığı belirgin biçimde artar.","Troposferdeki gibi yağışla yıkanma mekanizması bulunmadığı için buradaki aerosollerin kalış süresi yaklaşık 1 yıla kadar uzar."],"tanim_en":"The stratospheric aerosol layer is a persistent layer of submicron sulfate aerosol droplets situated between approximately 15 and 25 kilometers in altitude.","bag":{"kavram":["volkan-aerosol","ustel"],"soru":["S30","S31","S33"],"hesap":[]}},{"id":"north-atlantic-oscillation","tr":"Kuzey Atlantik Salınımı","en":"North Atlantic Oscillation","kisa":"NAO","tur":"kod","es":["NAO indeksi","NAO"],"tanim":["Kuzey Atlantik üzerinde İzlanda alçak basınç merkezi ile Azor yüksek basınç merkezi arasındaki deniz seviyesi basınç farkının büyük ölçekli salınımı.","Normalize edilmiş basınç farkından türetilen boyutsuz NAO indeksi ile izlenir; evreleri Avrupa ile Akdeniz havzasının fırtına rotalarını, sıcaklık ve yağış rejimini belirler.","Kitap Pinatubo sonrası NAO'nun geçici olarak negatif evreye geçtiğini yazar; gözlem çalışmalarının çoğu ise 1991–93 kışlarında pozitif evre ve Kuzey Avrasya'da ılık kış bildirir, konu tartışmalıdır."],"tanim_en":"A large-scale atmospheric circulation pattern characterized by fluctuations in the sea-level pressure difference between the Icelandic Low and the Azores High.","bag":{"kavram":["volkan-aerosol"],"soru":[],"hesap":[]}},{"id":"volcanic-explosivity-index","tr":"Volkanik patlama indeksi","en":"Volcanic Explosivity Index","kisa":"VEI","tur":"kod","es":["VEI ölçeği","volkanik patlayıcılık indeksi","volkan patlama ölçeği","VEI"],"tanim":["Patlamalı volkanik püskürmelerin büyüklüğünü püsküren tefra hacmine ve püskürme sütununun yüksekliğine göre derecelendiren 0 ile 8 arasındaki logaritmik ölçek.","Kısaltması VEI olup her bir basamak artışı püsküren malzeme hacminin yaklaşık on katına çıkmasına karşılık gelir.","Patlamanın mekanik büyüklüğünü gösterir fakat püskürtülen kükürt miktarını doğrudan vermez; bu nedenle iklimsel soğuma etkisini belirlemek için stratosfere ulaşan SO₂ kütlesi ayrıca incelenir."],"tanim_en":"The Volcanic Explosivity Index is a relative logarithmic scale from 0 to 8 defining the explosive magnitude of a volcanic eruption based on ejecta volume and eruption column height.","bag":{"kavram":["volkan-aerosol"],"soru":[],"hesap":[]}},{"id":"albedo","tr":"Albedo","en":"albedo","kisa":"A","tur":"olcu","es":["yansıtırlık","gezegen albedosu","planetary albedo","gezegensel albedo"],"tanim":["Bir yüzeyin yansıttığı ışınımın o yüzeye gelen ışınıma oranıdır.","Boyutsuzdur ve 0–1 arasındadır; kitapta A ile gösterilir ve gezegen albedosu yansıyan kısa dalga payıdır. Dünya ≈ 0,30, Venüs ≈ 0,70, taze kar ≈ 0,8–0,9, okyanus ≈ 0,06.","Soğurulan güneş S₀(1−A)/4'ü belirler; bulut, buz ve aerosol albedoyu değiştirerek iklimi etkiler. Aerosolün tek saçılma albedosu (ω) farklı bir kavramdır."],"tanim_en":"Albedo is the ratio of the radiation reflected by a surface to the radiation incident upon it.","bag":{"kavram":["volkan-aerosol","aerosol-dogrudan","isinim-dengesi"],"soru":["S6","S8","S9","S10","S11","S12"],"hesap":["etkin-sicaklik","bulut-net","optik-derinlik","beer-kesit"]}},{"id":"latent-heat","tr":"Gizli ısı","en":"latent heat","kisa":"L_v","tur":"olcu","es":["yoğuşma gizli ısısı","buharlaşma entalpisi","enthalpy of vaporization","buharlaşma gizli ısısı","latent heat of vaporization","L_v"],"tanim":["Bir maddenin hâl (faz) değişimi sırasında sıcaklığı değiştirmeden alınan ya da salınan enerji. Meteorolojide önemli olan su buharı, sıvı ve buz arasındaki değişimlerdir.","Buharlaşma için L_v ≈ 2,5 × 10⁶ J/kg; 1 kg suyu buhara çevirmek için gereken enerjidir. Faz değişiminde entropi farkı s_v − s_l = L_v / T olarak yazılır.","Yoğuşan buhar çevre havaya enerji verir (doymuş adyabatik soğuma yavaşlar); L_v ayrıca Clausius–Clapeyron bağıntısında doymuş buhar basıncının sıcaklıkla artışını belirler."],"tanim_en":"Latent heat is the amount of energy released or absorbed during a change of state of a substance, such as the evaporation or condensation of water.","bag":{"kavram":["volkan-aerosol","clausius","lcl"],"soru":["S11"],"hesap":["lcl"]}},{"id":"volcanic-eruption","tr":"Volkan patlaması","en":"volcanic eruption","kisa":"","tur":"surec","es":["volkanik püskürme","yanardağ patlaması","yanardağ püskürmesi","explosive eruption"],"tanim":["Yerkabuğunun derinliklerindeki magmanın, gazların ve katı kayaç parçalarının yeryüzüne veya atmosfere aniden ve şiddetle püskürmesi olayı.","İklim ve atmosfer kimyası açısından en kritik olanı, püskürme sütununun troposferi aşarak yaklaşık 15–20 km ve üzerine stratosfere ulaştığı patlayıcı püskürmelerdir.","Troposferde kalan kükürt dioksit birkaç günde yağışla yıkanırken stratosfere enjekte edilen gazlar küresel sülfat perdesi oluşturarak 2–3 yıl süren iklim soğumasına neden olur."],"tanim_en":"A volcanic eruption is the discharge of magma, gases, and particulate material from a volcanic vent into the atmosphere or onto the surface of the Earth.","bag":{"kavram":["volkan-aerosol"],"soru":["S30","S33","S34"],"hesap":[]}},{"id":"band-saturation","tr":"Bant doygunluğu","en":"band saturation","kisa":"","tur":"kavram","es":["doymuş soğurma bandı","absorption band saturation","soğurma bandı kanatları","absorption wings","bant kanatları","band wings"],"tanim":["Bir sera gazının belirli bir dalga boyu bandının merkezinde gelen ışınımın tamamına yakınını soğurarak doymuş hale gelmesi durumu.","Bant merkezi doyuma ulaştıktan sonra ortama eklenen yeni gaz molekülleri merkezde ek soğurma yapamaz; ışınımsal zorlama yalnızca bandın kanatlarında zayıf logaritmik bir artışla sürer.","CO₂ gazının 15 µm soğurma bandında görülür; bu nedenle CO₂ derişimi arttıkça oluşan ışınımsal zorlama doğrusal değil logaritmik oranla (ΔF = 5,35 ln(C/C₀)) hesaplanır."],"tanim_en":"Band saturation is the state in which an absorption band of a greenhouse gas absorbs nearly all incident radiation at its band center, making further radiative forcing depend logarithmically on concentration.","bag":{"kavram":["zorlama"],"soru":["S9"],"hesap":[]}},{"id":"carbon-dioxide-doubling","tr":"CO₂ derişiminin iki katına çıkması","en":"CO₂ doubling","kisa":"2×CO₂","tur":"kavram","es":["2xCO2","doubling of CO2","CO2 iki katına çıkması","karbondioksit ikiye katlanması","CO2 katlanması","CO₂ iki katına çıkması"],"tanim":["Atmosferdeki karbondioksit karışım oranının sanayi öncesi veya başlangıç referans düzeyinin tam iki katına (C/C₀ = 2) ulaşması durumu.","İklim modellerinde ve kuramsal hesaplarda standart bir ışınımsal zorlama kıyası olarak kullanılır; tropopozda yaklaşık 3,7 W/m² net akı değişimine yol açar.","Geri beslemeler hesaba katılmadığında yüzeyde yaklaşık 1 K, su buharı ve albedo gibi pozitif geri beslemeler eklendiğinde ise yaklaşık 3 K denge ısınması üretir."],"tanim_en":"CO₂ doubling refers to a doubling of atmospheric carbon dioxide concentration relative to baseline levels, yielding a radiative forcing of approximately 3.7 W/m².","bag":{"kavram":["zorlama","geri-besleme"],"soru":["S9"],"hesap":[]}},{"id":"equilibrium-climate-sensitivity","tr":"Denge iklim duyarlılığı","en":"equilibrium climate sensitivity","kisa":"","tur":"kavram","es":["ECS","denge iklim hassasiyeti","denge duyarlılığı","iklim duyarlılığı"],"tanim":["Atmosferik karbondioksit derişiminin iki katına (2×CO₂) çıkarılıp sabit tutulması ve tüm okyanus-atmosfer sisteminin yeni ısıl dengeye ulaşması durumunda gerçekleşen küresel ortalama yüzey sıcaklığı artışı.","Sembolü ECS olup birimi Kelvin (K) veya santigrat derecedir; IPCC AR6 raporuna göre en iyi tahmini 3 K, olası aralığı ise 2,5–4 K olarak belirlenmiştir.","İklim sistemindeki su buharı, bulut ve buz-albedo gibi tüm hızlı geri besleme süreçlerini içerir; iklim modellemelerinde gelecekteki uzun vadeli ısınmayı öngörmede temel parametredir."],"tanim_en":"Equilibrium climate sensitivity is the eventual change in global mean surface temperature resulting from a doubling of atmospheric carbon dioxide after the climate system attains steady state.","bag":{"kavram":["zorlama"],"soru":[],"hesap":[]}},{"id":"transient-climate-response","tr":"Geçici iklim tepkisi","en":"transient climate response","kisa":"","tur":"kavram","es":["TCR","geçici iklim hassasiyeti","geçici tepki"],"tanim":["Atmosferik karbondioksit derişiminin yılda %1 oranında düzenli arttığı bir senaryoda tam iki katına ulaşıldığı andaki küresel ortalama yüzey sıcaklığı artışı.","Sembolü TCR olup okyanusların devasa ısıl kapasitesi nedeniyle ısıyı derinlere soğurmasından ötürü denge iklim duyarlılığından (ECS) belirgin şekilde daha düşüktür.","IPCC AR6 raporunda en iyi tahmini yaklaşık 1,8 K olarak verilmiştir; yakın ve orta vadeli iklim değişikliğini değerlendirmede en gerçekçi göstergedir."],"tanim_en":"The transient climate response is the global mean surface warming at the time of atmospheric carbon dioxide doubling in a scenario where carbon dioxide grows by 1 percent per year.","bag":{"kavram":["zorlama"],"soru":[],"hesap":[]}},{"id":"tropopause","tr":"Tropopoz","en":"tropopause","kisa":"","tur":"kavram","es":["tropopoz seviyesi"],"tanim":["Troposfer ile stratosfer arasındaki sınır katmandır; sıcaklık düşey gradyanındaki belirgin değişimle belirlenir.","Sıcaklık azalma oranının 2 °C/km veya altına indiği en alt seviye olarak saptanır.","İklim dengesinde ışınımsal zorlamanın ve net ışınım akısı değişiminin hesaplandığı referans sınırdır."],"tanim_en":"The boundary between the troposphere and the stratosphere where the temperature lapse rate falls to 2 °C/km or less.","bag":{"kavram":["zorlama"],"soru":[],"hesap":[]}},{"id":"climate-sensitivity-parameter","tr":"İklim duyarlılık parametresi","en":"climate sensitivity parameter","kisa":"λ","tur":"olcu","es":["lambda","duyarlılık katsayısı","iklim duyarlılık katsayısı"],"tanim":["Birim ışınımsal zorlama başına küresel ortalama yüzey sıcaklığındaki denge değişimini veren katsayıdır.","Birimi K/(W m⁻²) olup kitapta geri beslemeler dahil toplam değer λ ≈ 0,8 K/(W m⁻²), geri beslemesiz Planck değeri ise λ₀ ≈ 0,27 K/(W m⁻²) olarak verilir.","Sera gazı birikimi gibi dış zorlamaların küresel yüzey sıcaklığını ne ölçüde değiştireceğini hesaplamakta kullanılır."],"tanim_en":"The proportionality parameter defined as the equilibrium change in global mean surface temperature per unit radiative forcing.","bag":{"kavram":["zorlama","geri-besleme"],"soru":["S9"],"hesap":["zorlama"]}},{"id":"specific-humidity","tr":"Özgül nem","en":"specific humidity","kisa":"q","tur":"kavram","es":["q","özgül nem oranı"],"tanim":["Nemli bir hava parselindeki su buharı kütlesinin toplam nemli hava kütlesine oranıdır.","Sembolü q olup birimi g/kg ya da boyutsuz kg/kg olarak ifade edilir.","Paydasında nemli hava yer aldığı için kuru havaya oranlanan karışma oranından çok az küçüktür (q ≈ r) ve yoğuşma gerçekleşmedikçe korunan bir büyüklüktür."],"tanim_en":"The ratio of the mass of water vapor to the total mass of moist air containing it.","bag":{"kavram":[],"soru":[],"hesap":[]}}]};
